QT_ISI(8,{"900":["(Kalau sekiranya Kami turunkan malaikat kepada mereka, dan orang-orang yang telah mati berbicara dengan mereka) seperti apa yang telah mereka minta (dan Kami kumpulkan pula) Kami himpunkan pula (segala sesuatu ke hadapan mereka) dibaca dengan damah kedua huruf permulaannya, jamak dari Lafal qabiil yakni gelombang demi gelombang. Dibaca kasrah huruf qaf-nya serta dibaca fatah huruf ba-nya; artinya: secara terang-terangan sehingga mereka dapat menyaksikan kebenaranmu (niscaya mereka tidak juga akan beriman) karena hal itu telah diketahui oleh Allah sebelumnya (kecuali) melainkan (jika Allah menghendaki) mereka beriman, maka baru mereka dapat beriman (akan tetapi kebanyakan mereka tidak mengetahui) tentang hal itu.",[["۞ وَلَوْ","Dan (walaupun) jika"],["أَنَّنَا","[bahawa] Kami (ada)"],["نَزَّلْنَآ","[Kami] turunkan"],["إِلَيْهِمُ","kepada mereka"],["ٱلْمَلَـٰٓئِكَةَ","para Malaikat"],["وَكَلَّمَهُمُ","dan bercakap kepada mereka"],["ٱلْمَوْتَىٰ","yang mati"],["وَحَشَرْنَا","dan Kami kumpulkan"],["عَلَيْهِمْ","sebelum mereka"],["كُلَّ","setiap"],["شَىْءٍۢ","perkara"],["قُبُلًۭا","bersemuka"],["مَّا","tidak"],["كَانُوا۟","mereka adalah"],["لِيُؤْمِنُوٓا۟","untuk beriman"],["إِلَّآ","melainkan"],["أَن","[bahawa]"],["يَشَآءَ","wasiat"],["ٱللَّهُ","Allah"],["وَلَـٰكِنَّ","Tetapi"],["أَكْثَرَهُمْ","kebanyakan mereka"],["يَجْهَلُونَ","(adalah) jahil"]]],"901":["(Dan demikianlah Kami jadikan bagi tiap-tiap nabi itu musuh) sebagaimana Kami telah jadikan mereka sebagai musuh-musuhmu; kemudian pengertian musuh itu dijelaskan (yakni setan-setan) siluman-siluman (dari jenis manusia dan jin yang memberikan bisikan) yang menghembuskan godaan (antara yang sebagian kepada sebagian lainnya tentang perkataan-perkataan yang indah-indah) yang memulas warna kebatilan (untuk membujuk) umat manusia. (Jika Tuhanmu menghendaki, niscaya mereka tidak mengerjakannya) maksudnya bisikan-bisikan yang menyesatkan tadi (maka tinggalkanlah mereka) biarkanlah orang-orang kafir itu (dan apa yang mereka ada-adakan) berupa kekafiran dan lain-lainnya yang sudah menjadi watak mereka; ayat ini diturunkan sebelum turunnya ayat perintah untuk berperang.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["جَعَلْنَا","Kami buat"],["لِكُلِّ","untuk setiap"],["نَبِىٍّ","Nabi"],["عَدُوًّۭا","seorang musuh"],["شَيَـٰطِينَ","syaitan"],["ٱلْإِنسِ","(dari) manusia"],["وَٱلْجِنِّ","dan jin"],["يُوحِى","memberi inspirasi"],["بَعْضُهُمْ","sebahagian mereka"],["إِلَىٰ","kepada"],["بَعْضٍۢ","yang lain"],["زُخْرُفَ","(dengan) hiasan"],["ٱلْقَوْلِ","[the] ucapan"],["غُرُورًۭا ۚ","(dalam) penipuan"],["وَلَوْ","Tetapi jika"],["شَآءَ","(telah) berkehendak"],["رَبُّكَ","Tuhanmu"],["مَا","tidak"],["فَعَلُوهُ ۖ","mereka (akan) melakukannya"],["فَذَرْهُمْ","jadi tinggalkan mereka"],["وَمَا","dan apa"],["يَفْتَرُونَ","mereka cipta"]]],"902":["(Dan juga agar mau mendengar) diathafkan kepada Lafal ghuruuran; artinya agar mau cenderung (kepada bisikan itu) yakni godaan tersebut (hati kecil) hati sanubari (orang-orang yang tidak beriman kepada kehidupan akhirat dan agar mereka merasa senang kepadanya dan supaya mereka mau mengerjakan) (apa yang setan-setan itu kerjakan) yaitu berupa perbuatan-perbuatan dosa sehingga mereka mendapat siksaan karenanya.",[["وَلِتَصْغَىٰٓ","Dan supaya condong"],["إِلَيْهِ","kepadanya"],["أَفْـِٔدَةُ","hati"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"],["بِٱلْـَٔاخِرَةِ","di akhirat"],["وَلِيَرْضَوْهُ","dan supaya mereka redha dengannya"],["وَلِيَقْتَرِفُوا۟","dan supaya mereka boleh melakukan"],["مَا","apa"],["هُم","mereka"],["مُّقْتَرِفُونَ","(sedang) melakukan"]]],"903":["Ayat ini diturunkan tatkala mereka meminta kepada Nabi saw. agar menjadikan seorang hakim yang melerai antara dia dan mereka; katakanlah: (Maka patutkah aku meminta kepada selain Allah) aku mencari (sebagai hakim) yang melerai antara aku dan kamu (padahal Dialah yang telah menurunkan Alkitab kepadamu) yakni Alquran (dengan terinci) di dalamnya terkandung penjelasan yang memisahkan antara perkara yang hak dengan perkara yang batil. (Orang-orang yang telah Kami datangkan kitab kepada mereka) yaitu kitab Taurat seperti Abdullah bin Salam dan teman-temannya (mereka mengetahui bahwa Alquran itu diturunkan) dengan dibaca takhfif dan dibaca tasydid (dari Tuhanmu dengan sebenarnya. Maka janganlah kamu sekali-kali termasuk orang-orang yang ragu-ragu) sehingga menjadi orang-orang yang bimbang terhadap Alquran. Yang dimaksud dengan pernyataan ini adalah sebagai bukti kepada orang-orang kafir bahwa sesungguhnya Alquran itu adalah benar.",[["أَفَغَيْرَ","Maka adakah (ia) selain"],["ٱللَّهِ","Allah"],["أَبْتَغِى","aku mencari"],["حَكَمًۭا","(sebagai) hakim"],["وَهُوَ","manakala Dia"],["ٱلَّذِىٓ","(ialah) Yang"],["أَنزَلَ","telah mendedahkan"],["إِلَيْكُمُ","kepada kamu"],["ٱلْكِتَـٰبَ","Kitab"],["مُفَصَّلًۭا ۚ","dijelaskan secara terperinci"],["وَٱلَّذِينَ","Dan mereka (kepada) mereka"],["ءَاتَيْنَـٰهُمُ","Kami memberi mereka"],["ٱلْكِتَـٰبَ","Kitab"],["يَعْلَمُونَ","mereka tahu"],["أَنَّهُۥ","bahawa ia"],["مُنَزَّلٌۭ","(adalah) diturunkan"],["مِّن","daripada"],["رَّبِّكَ","Tuhanmu"],["بِٱلْحَقِّ ۖ","dalam kebenaran"],["فَلَا","jadi (jangan)"],["تَكُونَنَّ","jadilah"],["مِنَ","antara"],["ٱلْمُمْتَرِينَ","mereka yang ragu-ragu"]]],"904":["(Dan telah sempurnalah kalimat Tuhanmu) yakni Alquran yang memuat hukum-hukum dan ancaman-ancaman (sebagai kalimat yang benar dan adil) menjadi tamyiz. (Tidak ada yang dapat mengubah-ubah kalimat-kalimat-Nya) baik dengan menguranginya atau menggantinya (dan Dialah Maha Mendengar) terhadap apa yang dikatakan olehnya (lagi Maha Mengetahui) tentang apa yang diperbuatnya.",[["وَتَمَّتْ","Dan (telah) dipenuhi"],["كَلِمَتُ","(perkataan)."],["رَبِّكَ","Tuhanmu"],["صِدْقًۭا","(dalam) kebenaran"],["وَعَدْلًۭا ۚ","dan keadilan"],["لَّا","Tidak"],["مُبَدِّلَ","seseorang boleh berubah"],["لِكَلِمَـٰتِهِۦ ۚ","kata-katanya"],["وَهُوَ","dan Dia"],["ٱلسَّمِيعُ","(ialah) Yang Maha Mendengar"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]],"905":["(Dan jika kamu menuruti kebanyakan orang-orang yang di muka bumi) yakni orang-orang kafir (niscaya mereka akan menyesatkanmu dari jalan Allah) yaitu agama-Nya (sama sekali) (mereka tidak akan mau mengikuti kecuali hanya pada prasangka belaka) dalam perdebatan mereka denganmu tentang masalah bangkai, yaitu di kala mereka berkata, \"Apa yang telah dibunuh oleh Allah lebih berhak untuk kamu makan daripada apa yang kamu bunuh sendiri.\" (dan sama sekali) tidak lain (mereka hanyalah berdusta) di dalam hal tersebut.",[["وَإِن","Dan jika"],["تُطِعْ","kamu taat"],["أَكْثَرَ","kebanyakannya"],["مَن","daripada"],["فِى","(mereka) dalam"],["ٱلْأَرْضِ","bumi"],["يُضِلُّوكَ","mereka akan menyesatkan kamu"],["عَن","daripada"],["سَبِيلِ","jalan"],["ٱللَّهِ ۚ","(milik) Allah"],["إِن","Tidak"],["يَتَّبِعُونَ","mereka ikut"],["إِلَّا","kecuali"],["ٱلظَّنَّ","[the] andaian"],["وَإِنْ","dan bukan"],["هُمْ","mereka (buat)"],["إِلَّا","kecuali"],["يَخْرُصُونَ","meneka"]]],"906":["(Sesungguhnya Tuhanmu Dialah yang lebih mengetahui) Maha Mengetahui (tentang orang yang tersesat dari jalan-Nya dan Dia lebih mengetahui tentang orang-orang yang mendapat petunjuk) dengan demikian maka Dia memberikan balasan pahala kepada mereka masing-masing.",[["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["هُوَ","Dia"],["أَعْلَمُ","lebih tahu"],["مَن","yang"],["يَضِلُّ","sesat"],["عَن","daripada"],["سَبِيلِهِۦ ۖ","cara dia"],["وَهُوَ","dan Dia"],["أَعْلَمُ","(adalah) yang paling mengetahui"],["بِٱلْمُهْتَدِينَ","daripada orang-orang yang mendapat petunjuk"]]],"907":["(Maka makanlah binatang-binatang yang halal yang disebutkan nama Allah atasnya) yang disembelih dengan menyebut nama-Nya (jika kamu beriman kepada ayat-ayat-Nya.)",[["فَكُلُوا۟","Jadi makan"],["مِمَّا","tentang apa"],["ذُكِرَ","(adalah) disebut"],["ٱسْمُ","(nama)"],["ٱللَّهِ","(milik) Allah"],["عَلَيْهِ","di atasnya"],["إِن","jika"],["كُنتُم","kamu"],["بِـَٔايَـٰتِهِۦ","dalam Ayat-ayatNya"],["مُؤْمِنِينَ","orang yang beriman"]]],"908":["(Mengapa kamu tidak mau memakan binatang-binatang yang halal yang disebut nama Allah atasnya) yaitu hewan-hewan sembelihan (padahal sesungguhnya Allah telah menjelaskan) boleh juga dibaca dengan bina maf`ul atau bina fa`il untuk kedua fi`ilnya (kepada kamu apa yang diharamkan-Nya atasmu) yang telah disebutkan di dalam ayat, \"Telah diharamkan atas kamu bangkai...\" (Q.S. Al-Maidah 3) (kecuali apa yang terpaksa kamu harus memakannya) di antara apa yang diharamkan itu maka hal itu juga dihalalkan bagi kamu. Adapun maknanya ialah: tidak ada larangan bagi kamu untuk memakan apa-apa yang telah disebutkan itu; Allah telah menjelaskan kepadamu apa-apa yang diharamkan kamu memakannya, maka ini bukanlah termasuk yang itu. (Dan sesungguhnya kebanyakan dari manusia benar-benar hendak menyesatkan orang lain) dengan dibaca fatah atau damah huruf ya-nya (dengan hawa nafsu mereka) dengan apa yang disukai hawa nafsu mereka; di antaranya ialah menghalalkan bangkai dan lain-lainnya (tanpa pengetahuan) yang secara sengaja mereka melakukannya. (Sesungguhnya Tuhanmu Dialah yang lebih mengetahui orang-orang yang melampaui batas) artinya orang-orang yang melampaui batas perkara yang dihalalkan untuk melakukan hal-hal yang diharamkan.",[["وَمَا","Dan apa"],["لَكُمْ","bagi kamu"],["أَلَّا","itu tidak"],["تَأْكُلُوا۟","kamu makan"],["مِمَّا","tentang apa"],["ذُكِرَ","telah disebut"],["ٱسْمُ","(nama)"],["ٱللَّهِ","(milik) Allah"],["عَلَيْهِ","di atasnya"],["وَقَدْ","apabila memang"],["فَصَّلَ","Beliau (telah) menjelaskan secara terperinci"],["لَكُم","kepada kamu"],["مَّا","apa"],["حَرَّمَ","Dia (telah) melarang"],["عَلَيْكُمْ","kepada kamu"],["إِلَّا","kecuali"],["مَا","apa"],["ٱضْطُرِرْتُمْ","kamu terpaksa"],["إِلَيْهِ ۗ","kepadanya"],["وَإِنَّ","Dan sesungguhnya"],["كَثِيرًۭا","ramai"],["لَّيُضِلُّونَ","pasti sesat"],["بِأَهْوَآئِهِم","dengan keinginan (yang sia-sia) mereka"],["بِغَيْرِ","tanpa"],["عِلْمٍ ۗ","pengetahuan"],["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["هُوَ","Dia"],["أَعْلَمُ","(adalah) yang paling mengetahui"],["بِٱلْمُعْتَدِينَ","daripada orang-orang yang melampaui batas"]]],"909":["(Dan tinggalkanlah) berhentilah kamu dari melakukan (dosa yang tampak dan yang tersembunyi) maksudnya dosa yang terang-terangan dan dosa yang tersembunyi; dikatakan bahwa yang dimaksud adalah perbuatan zina; dan dikatakan lagi adalah semua perbuatan maksiat. (Sesungguhnya orang-orang yang mengerjakan dosa, kelak akan diberi pembalasan) pada hari kiamat (disebabkan apa yang telah mereka kerjakan) usahakan.",[["وَذَرُوا۟","tinggalkan"],["ظَـٰهِرَ","terbuka"],["ٱلْإِثْمِ","[the] dosa"],["وَبَاطِنَهُۥٓ ۚ","dan rahsianya"],["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يَكْسِبُونَ","peroleh"],["ٱلْإِثْمَ","dosa itu"],["سَيُجْزَوْنَ","mereka akan mendapat balasan"],["بِمَا","bagi apa"],["كَانُوا۟","mereka dahulu"],["يَقْتَرِفُونَ","komited"]]],"910":["(Dan janganlah kamu memakan binatang-binatang yang tidak disebut nama Allah) seumpamanya karena mati dengan sendirinya atau disembelih dengan menyebut asma selain-Nya terkecuali apa yang disembelih oleh orang muslim, sekali pun tidak menyebut nama-Nya sewaktu menyembelihnya baik secara sengaja atau pun karena lupa, maka sembelihannya tetap halal, demikianlah menurut pendapat Ibnu Abbas, yang kemudian dianut oleh Imam Syafii. (Sesungguhnya) memakan hewan-hewan yang diharamkan itu (adalah suatu kefasikan) keluar dari garis apa yang telah dihalalkan. (Sesungguhnya setan itu membisikkan) menghembuskan godaannya (kepada kawan-kawannya) yaitu kepada orang-orang kafir (agar mereka membantah kamu) di dalam masalah menghalalkan bangkai (dan jika kamu menuruti mereka) di dalam hal ini (sesungguhnya kamu tentulah menjadi orang-orang musyrik). Ayat berikut ini diturunkan berkenaan dengan Abu Jahal dan lain-lainnya.",[["وَلَا","Dan jangan"],["تَأْكُلُوا۟","makan"],["مِمَّا","daripada itu"],["لَمْ","tidak"],["يُذْكَرِ","telah disebut"],["ٱسْمُ","(nama)"],["ٱللَّهِ","(milik) Allah"],["عَلَيْهِ","di atasnya"],["وَإِنَّهُۥ","dan sesungguhnya ia (adalah)"],["لَفِسْقٌۭ ۗ","kemaksiatan yang berat"],["وَإِنَّ","Dan sesungguhnya"],["ٱلشَّيَـٰطِينَ","syaitan"],["لَيُوحُونَ","memberi inspirasi"],["إِلَىٰٓ","kepada"],["أَوْلِيَآئِهِمْ","kawan-kawan mereka"],["لِيُجَـٰدِلُوكُمْ ۖ","supaya mereka berselisih dengan kamu"],["وَإِنْ","dan jika"],["أَطَعْتُمُوهُمْ","kamu taat kepada mereka"],["إِنَّكُمْ","sesungguhnya, kamu"],["لَمُشْرِكُونَ","(akan) menjadi orang-orang musyrik"]]],"911":["(Dan apakah yang sudah mati) oleh sebab kekafirannya (kemudian dia Kami hidupkan) dengan hidayah (dan Kami berikan kepadanya cahaya yang terang yang dengan cahaya itu dia dapat berjalan di tengah-tengah masyarakat manusia) dia dapat pula melihat perkara yang benar berkat cahaya itu dan dapat membedakannya daripada yang lainnya; yang dimaksud adalah keimanan (serupa dengan orang yang keadaannya) Lafal mitsl adalah tambahan, yakni sebagaimana seseorang (yang keadaannya dalam gelap-gulita yang sekali-kali tidak dapat keluar darinya) dimaksud orang kafir; sebagai jawabannya ialah tentu saja tidak. (Demikianlah) sebagaimana orang-orang mukmin dihiasi dengan keimanan (orang-orang kafir pun dihiasi pula dengan apa yang telah mereka kerjakan) berupa kekafiran dan maksiat-maksiat.",[["أَوَمَن","Adakah (seorang) yang"],["كَانَ","adalah"],["مَيْتًۭا","mati"],["فَأَحْيَيْنَـٰهُ","dan Kami hidupkan dia"],["وَجَعَلْنَا","dan Kami jadikan"],["لَهُۥ","baginya"],["نُورًۭا","ringan"],["يَمْشِى","dia berjalan"],["بِهِۦ","di mana"],["فِى","antara"],["ٱلنَّاسِ","manusia"],["كَمَن","seperti (seorang) siapa"],["مَّثَلُهُۥ","[serupa dengan dia]"],["فِى","(berada) dalam"],["ٱلظُّلُمَـٰتِ","kegelapan"],["لَيْسَ","tidak"],["بِخَارِجٍۢ","dia keluar"],["مِّنْهَا ۚ","daripadanya"],["كَذَٰلِكَ","Demikianlah"],["زُيِّنَ","dibuat kelihatan adil"],["لِلْكَـٰفِرِينَ","kepada orang-orang kafir"],["مَا","apa"],["كَانُوا۟","mereka adalah"],["يَعْمَلُونَ","melakukan"]]],"912":["(Dan demikianlah) sebagaimana yang telah Kami jadikan orang-orang fasik penduduk Mekah terdiri dari para pembesarnya (Kami adakan pada tiap-tiap negeri penjahat-penjahat yang terbesar agar mereka melakukan tipu daya dalam negeri itu) dengan cara menghalang-halangi jalan keimanan (Dan mereka tidak memperdayakan melainkan dirinya sendiri) sebab akibat perbuatannya menimpa diri mereka sendiri (sedangkan mereka tidak menyadarinya) tentang hal tersebut.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["جَعَلْنَا","Kami letak"],["فِى","dalam"],["كُلِّ","setiap"],["قَرْيَةٍ","bandar"],["أَكَـٰبِرَ","terhebat"],["مُجْرِمِيهَا","(dari) penjenayahnya"],["لِيَمْكُرُوا۟","supaya mereka merancang"],["فِيهَا ۖ","di dalamnya"],["وَمَا","Dan tidak"],["يَمْكُرُونَ","mereka merancang"],["إِلَّا","kecuali"],["بِأَنفُسِهِمْ","terhadap diri mereka sendiri"],["وَمَا","dan bukan"],["يَشْعُرُونَ","mereka rasa"]]],"913":["(Dan apabila datang kepada mereka) kepada penduduk Mekah (satu ayat) yang membenarkan Nabi saw. (mereka berkata, \"Kami tidak akan beriman) kepadanya (sehingga diberikan kepada kami yang serupa dengan apa yang telah diberikan kepada utusan-utusan Allah.\") berupa risalah dan wahyu kepada kami sebab kami adalah yang terbanyak hartanya dan yang paling tua umurnya lalu Allah swt. berfirman: (Allah lebih mengetahui di mana Dia menempatkan tugas kerasulan-Nya) dengan dibaca jamak dan tunggal dan Lafal haitsu menjadi maf`ul bihi dari fi`il yang ditunjuk oleh Lafal a`lamu. Artinya Allah mengetahui tempat yang layak untuk meletakkan risalah-Nya lalu Ia meletakkannya. Sedangkan mereka itu bukanlah orang-orang yang pantas untuk mengemban tugas risalah ini (orang-orang yang berdosa nanti akan ditimpa) sebab perkataan mereka itu (suatu kehinaan) yakni menjadi rendah (di sisi Allah dan siksa yang keras disebabkan mereka lalu membuat tipu daya) oleh tipu daya mereka sendiri.",[["وَإِذَا","Dan apabila"],["جَآءَتْهُمْ","datang kepada mereka"],["ءَايَةٌۭ","sebuah Tanda"],["قَالُوا۟","mereka berkata"],["لَن","tidak pernah"],["نُّؤْمِنَ","kita akan beriman"],["حَتَّىٰ","sehingga"],["نُؤْتَىٰ","kita diberi"],["مِثْلَ","suka"],["مَآ","apa"],["أُوتِىَ","telah diberikan"],["رُسُلُ","(kepada) para Rasul"],["ٱللَّهِ ۘ","(milik) Allah"],["ٱللَّهُ","Allah"],["أَعْلَمُ","lebih tahu"],["حَيْثُ","di mana"],["يَجْعَلُ","Dia meletakkan"],["رِسَالَتَهُۥ ۗ","Mesej beliau"],["سَيُصِيبُ","Akan merana"],["ٱلَّذِينَ","orang yang"],["أَجْرَمُوا۟","melakukan jenayah"],["صَغَارٌ","satu penghinaan"],["عِندَ","daripada"],["ٱللَّهِ","Allah"],["وَعَذَابٌۭ","dan hukuman"],["شَدِيدٌۢ","teruk"],["بِمَا","bagi apa"],["كَانُوا۟","mereka dahulu"],["يَمْكُرُونَ","plot"]]],"914":["(Siapa yang Allah menghendaki akan memberikan kepadanya petunjuk niscaya Dia melapangkan dadanya untuk memeluk agama Islam) dengan cara menyinarkan nur hidayah ke dalam dadanya sehingga dengan sadar ia mau menerima Islam dan mau membuka dadanya lebar-lebar untuk menerimanya. Demikianlah sebagaimana yang telah disebutkan dalam suatu hadis. (Dan siapa yang dikehendaki) Allah (kesesatannya niscaya Allah menjadikan dadanya sesak) dengan dibaca takhfif dan tasydid yakni merasa sempit untuk menerimanya (lagi sempit) terasa amat sempit; dengan dibaca kasrah huruf ra-nya menjadi sifat dan dibaca fathah sebagai mashdar yang diberi sifat dengan makna mubalaghah (seolah-olah ia sedang mendaki) menurut suatu qiraat dibaca yashsha`adu di dalam kedua bacaan tersebut berarti mengidgamkan ta asal ke dalam huruf shad. Menurut qiraat lainnya dengan dibaca sukun huruf shad-nya (ke langit) apabila iman dipaksakan kepadanya karena hal itu terasa berat sekali baginya. (Begitulah) sebagaimana kejadian itu (Allah menimpakan siksa) yakni azab atau setan, dengan pengertian azab atau setan itu menguasainya (kepada orang-orang yang tidak beriman).",[["فَمَن","Jadi sesiapa"],["يُرِدِ","mahu"],["ٱللَّهُ","Allah"],["أَن","bahawa"],["يَهْدِيَهُۥ","Dia membimbingnya"],["يَشْرَحْ","Dia mengembang"],["صَدْرَهُۥ","buah dadanya"],["لِلْإِسْلَـٰمِ ۖ","kepada Islam"],["وَمَن","dan sesiapa"],["يُرِدْ","Dia mahu"],["أَن","bahawa"],["يُضِلَّهُۥ","Dia biarkan dia sesat"],["يَجْعَلْ","Dia buat"],["صَدْرَهُۥ","buah dadanya"],["ضَيِّقًا","ketat"],["حَرَجًۭا","dan sempit"],["كَأَنَّمَا","seolah-olah"],["يَصَّعَّدُ","dia (sedang) mendaki"],["فِى","ke dalam"],["ٱلسَّمَآءِ ۚ","langit"],["كَذَٰلِكَ","Demikianlah"],["يَجْعَلُ","tempat-tempat"],["ٱللَّهُ","Allah"],["ٱلرِّجْسَ","kekotoran"],["عَلَى","pada"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"]]],"915":["(Dan inilah) apa yang engkau berada di dalamnya hai Muhammad! (jalan) titian (Tuhanmu yang lurus) tidak ada liku-likunya; Lafal mustaqiiman dibaca nashab menjadi hal yang mengukuhkan jumlah, sedangkan yang menjadi `amilnya adalah makna isyarah. (Sesungguhnya Kami telah menjelaskan) Kami telah menerangkan (ayat-ayat Kami kepada orang-orang yang mengambil pelajaran) Lafal yadzdzakkaruun dengan mengidgamkan huruf ta tambahan ke dalam huruf dzal asal; maknanya orang-orang yang mau mengambil sebagai pelajaran. Mereka disebutkan secara khusus sebab merekalah orang-orang yang mengambil manfaat darinya.",[["وَهَـٰذَا","Dan ini"],["صِرَٰطُ","(adalah) jalan"],["رَبِّكَ","(dari) Tuhanmu"],["مُسْتَقِيمًۭا ۗ","lurus"],["قَدْ","Sungguh"],["فَصَّلْنَا","Kami telah terperinci"],["ٱلْـَٔايَـٰتِ","ayat-ayat"],["لِقَوْمٍۢ","bagi kaum"],["يَذَّكَّرُونَ","yang mengambil iktibar"]]],"916":["(Bagi mereka disediakan Darussalam) yakni rumah keselamatan atau surga (pada sisi Tuhannya dan Dialah Pelindung mereka disebabkan amal-amal saleh yang selalu mereka kerjakan).",[["۞ لَهُمْ","Untuk mereka"],["دَارُ","(akan) pulang"],["ٱلسَّلَـٰمِ","(dari) kedamaian"],["عِندَ","dengan"],["رَبِّهِمْ ۖ","Tuhan mereka"],["وَهُوَ","Dan Dia"],["وَلِيُّهُم","(akan menjadi) pelindung mereka"],["بِمَا","kerana"],["كَانُوا۟","(dari apa) mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"917":["(Dan) ingatlah (hari di waktu Kami menghimpun mereka semuanya) dengan memakai nun dan ya; artinya Allahlah yang menghimpun semua makhluk kemudian diserukan kepada mereka (\"Hai golongan jin/setan! Sesungguhnya kamu telah banyak menyesatkan manusia,\") dengan cara kamu menyesatkan mereka (lalu berkatalah kawan-kawan mereka) yaitu mereka yang mau menaatinya (dari kalangan manusia, \"Ya Tuhan kami, sesungguhnya sebagian daripada kami telah dapat kesenangan dari sebagian yang lainnya) manusia telah mengambil manfaat melalui jin yang menghiasi keinginan-keinginan nafsu syahwat mereka, dan demikian pula jin pun mengambil manfaat dari manusia melalui ketaatan manusia kepada mereka (dan kami telah sampai kepada waktu yang telah Engkau tentukan bagi kami\") yakni hari kiamat; hal ini adalah merupakan ungkapan kekecewaan mereka (Allah berfirman) Maha Tinggi Allah, kepada mereka melalui lisan para malaikat-Nya (\"Neraka itulah tempat kamu) tempat diam kamu (sedangkan kamu kekal di dalamnya, kecuali kalau Allah menghendaki yang lain.\") batas-batas waktu tertentu di mana mereka dapat dikeluarkan dari neraka, untuk meminum hamim/keringat ahli neraka yang berada di luar neraka, demikianlah seperti apa yang dikatakan dalam firman-Nya, \"Kemudian sesungguhnya tempat kembali mereka benar-benar ke neraka Jahim,\" surah Ash-Shaffaat. Dan telah diriwayatkan dari Ibnu Abbas bahwasanya ayat ini diturunkan berkenaan dengan orang-orang yang telah diketahui Allah bahwa mereka orang-orang yang beriman. Dengan demikian berarti Lafal maa bermakna man. (Sesungguhnya Tuhanmu Maha Bijaksana) di dalam mengatur ciptaan-Nya (lagi Maha Mengetahui) tentang makhluk-makhluk-Nya.",[["وَيَوْمَ","Dan (hari) itu"],["يَحْشُرُهُمْ","Dia akan mengumpulkan mereka"],["جَمِيعًۭا","semua"],["يَـٰمَعْشَرَ","(dan akan berkata), \"Wahai perhimpunan"],["ٱلْجِنِّ","(dari) jin"],["قَدِ","Sungguh"],["ٱسْتَكْثَرْتُم","kamu telah (mengelirukan) ramai"],["مِّنَ","daripada"],["ٱلْإِنسِ ۖ","umat manusia"],["وَقَالَ","Dan akan berkata"],["أَوْلِيَآؤُهُم","kawan-kawan mereka"],["مِّنَ","antara"],["ٱلْإِنسِ","kaum lelaki"],["رَبَّنَا","Wahai Tuhan kami"],["ٱسْتَمْتَعَ","mendapat keuntungan"],["بَعْضُنَا","sebahagian daripada kita"],["بِبَعْضٍۢ","oleh orang lain"],["وَبَلَغْنَآ","dan kami telah sampai"],["أَجَلَنَا","istilah kami"],["ٱلَّذِىٓ","yang"],["أَجَّلْتَ","Kamu melantik"],["لَنَا ۚ","bagi kami"],["قَالَ","Dia akan berkata"],["ٱلنَّارُ","Api"],["مَثْوَىٰكُمْ","(ialah) tempat tinggal kamu"],["خَـٰلِدِينَ","akan kekal selama-lamanya"],["فِيهَآ","di dalamnya"],["إِلَّا","kecuali"],["مَا","(untuk) apa"],["شَآءَ","wasiat"],["ٱللَّهُ ۗ","Allah"],["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["حَكِيمٌ","(adalah) Maha Bijaksana"],["عَلِيمٌۭ","Maha Mengetahui"]]],"918":["(Dan demikianlah) sebagaimana yang telah Kami berikan nikmat kepada orang-orang yang maksiat dari golongan manusia dan jin sebagian mereka melalui sebagian lainnya (Kami jadikan berteman) saling bantu-membantu (sebagian orang-orang yang lalim itu dengan sebagian lainnya) atas sebagian lainnya (disebabkan apa yang mereka usahakan) berupa perbuatan-perbuatan maksiat.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["نُوَلِّى","Kami berkawan"],["بَعْضَ","beberapa (daripada)"],["ٱلظَّـٰلِمِينَ","orang yang zalim"],["بَعْضًۢا","(kepada) orang lain"],["بِمَا","bagi apa"],["كَانُوا۟","mereka dahulu"],["يَكْسِبُونَ","peroleh"]]],"919":["(Hai golongan jin dan manusia, apakah belum datang kepadamu rasul-rasul dari golongan kamu sendiri) kalangan kamu sendiri; artinya sebagian kamu yang percaya kepada manusia atau utusan-utusan jin yang sengaja Kami biarkan mereka mendengar ucapan-ucapan para rasul Kami kemudian mereka menyampaikannya kepada kaumnya (yang menceritakan kepada kamu tentang ayat-ayat-Ku dan memperingatkan kamu tentang pertemuanmu dengan hari ini? Mereka berkata, \"Kami menjadi saksi atas diri kami sendiri.\") bahwa sesungguhnya kami telah menerimanya. Allah swt. berfirman: (Kehidupan dunia telah menipu mereka) sehingga mereka tidak mau beriman (dan mereka menjadi saksi atas diri mereka sendiri bahwa mereka adalah orang-orang yang kafir.)",[["يَـٰمَعْشَرَ","Wahai perhimpunan"],["ٱلْجِنِّ","(dari) jin"],["وَٱلْإِنسِ","dan lelaki"],["أَلَمْ","Adakah (ada) tidak"],["يَأْتِكُمْ","datang kepada kamu"],["رُسُلٌۭ","Utusan"],["مِّنكُمْ","dari (antara) kamu"],["يَقُصُّونَ","mengaitkan"],["عَلَيْكُمْ","kepada kamu"],["ءَايَـٰتِى","Ayat-ayat Aku"],["وَيُنذِرُونَكُمْ","dan memberi amaran kepada kamu"],["لِقَآءَ","(daripada) mesyuarat"],["يَوْمِكُمْ","(dari) hari kamu"],["هَـٰذَا ۚ","ini"],["قَالُوا۟","Mereka akan berkata"],["شَهِدْنَا","Kami bersaksi"],["عَلَىٰٓ","terhadap"],["أَنفُسِنَا ۖ","diri kita sendiri"],["وَغَرَّتْهُمُ","Dan menipu mereka"],["ٱلْحَيَوٰةُ","kehidupan"],["ٱلدُّنْيَا","dunia"],["وَشَهِدُوا۟","dan mereka akan menjadi saksi"],["عَلَىٰٓ","terhadap"],["أَنفُسِهِمْ","diri mereka"],["أَنَّهُمْ","bahawa mereka"],["كَانُوا۟","adalah"],["كَـٰفِرِينَ","orang kafir"]]],"920":["(Yang demikian itu) dengan mengutus para utusan (supaya) huruf lam dimuqaddarahkan sedangkan an berasal dari anna yang ditakhfifkan; yaitu berasal dari liannahu (Tuhanmu tidak membinasakan kota-kota secara aniaya) sebagian dari kota-kota itu (sedangkan penduduknya dalam keadaan lengah) dan belum pernah diutus kepada mereka seorang rasul pun yang memberikan penjelasan kepada mereka.",[["ذَٰلِكَ","Itu (kerana)"],["أَن","[bahawa]"],["لَّمْ","tidak"],["يَكُن","ialah"],["رَّبُّكَ","Tuhanmu"],["مُهْلِكَ","seorang yang membinasakan"],["ٱلْقُرَىٰ","bandar-bandar"],["بِظُلْمٍۢ","kerana kesalahan (mereka)."],["وَأَهْلُهَا","sedangkan rakyat mereka"],["غَـٰفِلُونَ","(ada) tidak sedar"]]],"921":["(Dan masing-masing) dari kalangan orang-orang itu (memperoleh derajat-derajat) pembalasan (sesuai dengan apa yang telah dikerjakannya) berupa pembalasan yang baik dan pembalasan yang buruk (Dan Tuhanmu tidak lengah dari apa yang mereka kerjakan) dengan memakai ya dan ta.",[["وَلِكُلٍّۢ","Dan untuk semua"],["دَرَجَـٰتٌۭ","(akan) darjah"],["مِّمَّا","bagi apa"],["عَمِلُوا۟ ۚ","mereka lakukan"],["وَمَا","Dan tidak"],["رَبُّكَ","(ialah) Tuhanmu"],["بِغَـٰفِلٍ","tak sedar"],["عَمَّا","tentang apa"],["يَعْمَلُونَ","mereka lakukan"]]],"922":["(Dan Tuhanmu Maha Kaya) tidak membutuhkan makhluk-Nya dan juga tidak membutuhkan ibadah mereka (lagi mempunyai rahmat. Jika Dia menghendaki niscaya Dia memusnahkan kamu) hai penduduk Mekah yakni membinasakan kalian (dan menggantimu dengan siapa yang dikehendaki-Nya setelah kamu musnah) di antara makhluk-Nya (sebagaimana Dia telah menjadikan kamu dari keturunan orang-orang lain) yang telah Dia memusnahkan akan tetapi Dia tetap membiarkan kamu sebagai rahmat atas kamu sekalian.",[["وَرَبُّكَ","Dan Tuhanmu"],["ٱلْغَنِىُّ","(ialah) Yang Berdikari"],["ذُو","(the) Pemilik"],["ٱلرَّحْمَةِ ۚ","(dari) belas kasihan"],["إِن","Jika"],["يَشَأْ","Dia kehendaki"],["يُذْهِبْكُمْ","Dia boleh bawa kamu pergi"],["وَيَسْتَخْلِفْ","dan penggantian pemberian"],["مِنۢ","daripada"],["بَعْدِكُم","selepas kamu"],["مَّا","(kepada) siapa"],["يَشَآءُ","Dia kehendaki"],["كَمَآ","seperti"],["أَنشَأَكُم","Dia membesarkan kamu"],["مِّن","daripada"],["ذُرِّيَّةِ","keturunan"],["قَوْمٍ","(daripada) orang"],["ءَاخَرِينَ","lain"]]],"923":["(Sesungguhnya apa yang dijanjikan kepadamu) pada hari kiamat dan azab (pasti datang) tidak dapat ditawar-tawar lagi (dan kamu sekali-kali tidak sanggup menolaknya) tidak bisa selamat dari azab Kami.",[["إِنَّ","Sesungguhnya"],["مَا","apa"],["تُوعَدُونَ","kamu dijanjikan"],["لَـَٔاتٍۢ ۖ","(adalah) pasti akan datang"],["وَمَآ","Dan tidak"],["أَنتُم","(boleh) kamu"],["بِمُعْجِزِينَ","melarikan diri (ia)"]]],"924":["(Katakanlah) kepada mereka (\"Hai kaumku! Berbuatlah sepenuh kemampuanmu) sesuai dengan keadaanmu (sesungguhnya aku pun berbuat pula) sesuai dengan keadaanku. (Kelak kamu akan mengetahui siapakah di antara kita) man menjadi maushul dan menjadi maf`ul dari Lafal al-`ilm (yang akan memperoleh hasil yang baik dari dunia ini.\") akibat yang dipuji di akhirat nanti, apakah kami atau kamu? (Sesungguhnya tidak akan mendapat keberuntungan) kebahagiaan (orang-orang yang lalim itu) yaitu orang-orang kafir.",[["قُلْ","Katakanlah"],["يَـٰقَوْمِ","Wahai kaumku"],["ٱعْمَلُوا۟","Kerja"],["عَلَىٰ","pada"],["مَكَانَتِكُمْ","kedudukan kamu"],["إِنِّى","Memang aku"],["عَامِلٌۭ ۖ","seorang pekerja"],["فَسَوْفَ","Dan tidak lama lagi"],["تَعْلَمُونَ","kamu akan tahu"],["مَن","yang"],["تَكُونُ","akan mempunyai"],["لَهُۥ","untuk dirinya sendiri"],["عَـٰقِبَةُ","(pada) akhirnya"],["ٱلدَّارِ ۗ","rumah (yang baik)."],["إِنَّهُۥ","Sesungguhnya [dia]"],["لَا","(akan) tidak"],["يُفْلِحُ","berjaya"],["ٱلظَّـٰلِمُونَ","orang yang zalim"]]],"925":["(Dan mereka memperuntukkan) orang-orang kafir Mekah (bagi Allah satu bagian dari apa yang telah diciptakan)-Nya (yaitu berupa tanaman) hasil lahan (dan ternak sebagai bagian) yang mereka infakkan untuk tamu-tamu dan orang-orang miskin dan juga satu bagian lainnya untuk sesembahan-sesembahan mereka yang mereka berikan kepada para juru kuncinya (lalu mereka berkata sesuai dengan prasangka mereka, \"Ini untuk Allah) dengan dibaca fatah dan damah huruf zai-nya (dan ini untuk berhala-berhala kami.\") maksudnya apabila ada sesuatu yang terjatuh dari bagian untuk sesembahan mereka, mereka berani mengambilnya kembali. Tetapi apabila ada sesuatu yang terjatuh, dari bagian untuk Allah mereka membiarkannya kemudian mereka berkata, \"Sesungguhnya Allah tidak membutuhkan ini.\" Demikianlah sebagaimana yang diungkapkan dalam firman-Nya berikut ini: (Maka sajian-sajian yang diperuntukkan bagi berhala-berhala mereka tidak sampai kepada Allah) (dan sajian-sajian yang diperuntukkan bagi Allah, maka sajian itu sampai kepada berhala-berhala mereka. Amat buruklah) amat jeleklah (apa yang mereka tetapkan) yakni keputusan hukum mereka itu.",[["وَجَعَلُوا۟","Dan mereka menugaskan"],["لِلَّهِ","kepada Allah"],["مِمَّا","daripada apa"],["ذَرَأَ","Dia menghasilkan"],["مِنَ","daripada"],["ٱلْحَرْثِ","tanaman"],["وَٱلْأَنْعَـٰمِ","dan lembu"],["نَصِيبًۭا","satu bahagian"],["فَقَالُوا۟","dan mereka berkata"],["هَـٰذَا","Ini"],["لِلَّهِ","(adalah) untuk Allah"],["بِزَعْمِهِمْ","dengan tuntutan mereka"],["وَهَـٰذَا","Dan ini"],["لِشُرَكَآئِنَا ۖ","(adalah) untuk rakan kongsi kami"],["فَمَا","Tetapi apa"],["كَانَ","ialah"],["لِشُرَكَآئِهِمْ","untuk pasangan mereka"],["فَلَا","tidak"],["يَصِلُ","capai"],["إِلَى","[ke]"],["ٱللَّهِ ۖ","Allah"],["وَمَا","sedangkan apa"],["كَانَ","ialah"],["لِلَّهِ","kerana Allah"],["فَهُوَ","kemudian ia"],["يَصِلُ","mencapai"],["إِلَىٰ","[ke]"],["شُرَكَآئِهِمْ ۗ","rakan kongsi mereka"],["سَآءَ","jahat"],["مَا","(ialah) apa"],["يَحْكُمُونَ","mereka menilai"]]],"926":["(Dan demikianlah) sebagaimana telah menjadi kebiasaan mereka apa-apa yang telah disebutkan itu (telah menghiasi kebanyakan orang-orang musyrik memandang baik membunuh anak-anak mereka) dengan cara mengubur mereka hidup-hidup (karena hasutan sesembahan-sesembahan mereka) yang terdiri dari makhluk jin. Dengan dibaca rafa' sebagai fa'il dari fi'il zayyana; dan menurut suatu qiraat dengan dibaca bina maf'ul serta Lafal qatla dibaca rafa', dan dibaca nashab Lafal al-awlaad, berdasarkan bacaan ini Lafal syurakaaihim dibaca jar dengan mengidhafatkannya kepada Lafal al-qatlu; dengan demikian berarti ada fashal/pemisah antara mudhaf dan mudhaf ilaih yang dipisahkan oleh maf'ul, hal ini tidak mengapa, sebab mengidhafatkan Lafal al-qatlu kepada Lafal syurakaa karena merekalah pada hakikatnya yang melakukannya melalui bujukan mereka (untuk membinasakan mereka) untuk memusnahkan mereka (dan untuk mengaburkan) dengan mencampur-adukkan (bagi mereka agamanya. Dan kalau Allah menghendaki niscaya mereka tidak mengerjakannya, maka tinggalkanlah mereka dan apa yang mereka ada-adakan).",[["وَكَذَٰلِكَ","Dan begitu juga"],["زَيَّنَ","dibuat menyenangkan"],["لِكَثِيرٍۢ","kepada ramai"],["مِّنَ","daripada"],["ٱلْمُشْرِكِينَ","orang musyrik"],["قَتْلَ","(yang) membunuh"],["أَوْلَـٰدِهِمْ","(dari) anak-anak mereka"],["شُرَكَآؤُهُمْ","rakan kongsi mereka"],["لِيُرْدُوهُمْ","supaya mereka membinasakan mereka"],["وَلِيَلْبِسُوا۟","dan yang mereka buat mengelirukan"],["عَلَيْهِمْ","kepada mereka"],["دِينَهُمْ ۖ","agama mereka"],["وَلَوْ","Dan jika"],["شَآءَ","(telah) berkehendak"],["ٱللَّهُ","Allah"],["مَا","tidak"],["فَعَلُوهُ ۖ","(akan) mereka berbuat demikian"],["فَذَرْهُمْ","Jadi tinggalkan mereka"],["وَمَا","dan apa"],["يَفْتَرُونَ","mereka cipta"]]],"927":["(Dan mereka mengatakan, \"Inilah binatang ternak dan tanaman yang dilarang) yang diharamkan (tidak boleh memakannya kecuali orang yang kami kehendaki\") yaitu para pelayan berhala-berhala dan lain-lainnya (menurut anggapan mereka) artinya mereka tidak punya alasan lagi dalam masalah ini (dan ada binatang ternak yang diharamkan menungganginya) maka ternak-ternak itu tidak boleh dinaiki, seperti hewan sawaib dan hewan hawami (dan binatang ternak yang mereka tidak menyebut nama Allah atasnya) di kala menyembelihnya melainkan menyebut nama berhala-berhala mereka kemudian mengaitkan hal itu kepada Allah (semata-mata membuat-buat kedustaan terhadap Allah. Kelak Allah akan membalas mereka terhadap apa yang selalu mereka ada-adakan) sebagai balasannya.",[["وَقَالُوا۟","Dan mereka berkata"],["هَـٰذِهِۦٓ","Ini"],["أَنْعَـٰمٌۭ","(adalah) lembu"],["وَحَرْثٌ","dan tanaman"],["حِجْرٌۭ","dilarang"],["لَّا","tiada (satu)"],["يَطْعَمُهَآ","boleh makan mereka"],["إِلَّا","kecuali"],["مَن","yang"],["نَّشَآءُ","kita akan"],["بِزَعْمِهِمْ","dengan tuntutan mereka"],["وَأَنْعَـٰمٌ","Dan lembu"],["حُرِّمَتْ","dilarang"],["ظُهُورُهَا","(adalah) belakang mereka"],["وَأَنْعَـٰمٌۭ","dan lembu"],["لَّا","tidak"],["يَذْكُرُونَ","mereka menyebut"],["ٱسْمَ","(nama)"],["ٱللَّهِ","(milik) Allah"],["عَلَيْهَا","di atasnya"],["ٱفْتِرَآءً","(sebagai) ciptaan"],["عَلَيْهِ ۚ","terhadap Dia"],["سَيَجْزِيهِم","Dia akan membalas mereka"],["بِمَا","bagi apa"],["كَانُوا۟","mereka dahulu"],["يَفْتَرُونَ","mencipta"]]],"928":["(Dan mereka mengatakan, \"Apa yang dalam perut binatang ini) yaitu ternak yang diharamkan untuk dimakan seperti ternak sawaib dan ternak bahair (adalah khusus) dihalalkan (untuk pria kami dan diharamkan atas wanita kami\") yakni haram untuk perempuan-perempuan kami (dan jika yang dalam perut itu dilahirkan mati) dengan dibaca rafa` dan nashab serta fi`il dita`nitskan atau ditadzkirkan (maka pria dan wanita sama-sama boleh memakannya. Kelak akan membalas mereka) yakni Allah (terhadap ketetapan mereka) berupa pembelaan azab atas penghalalan dan pengharaman ini (Sesungguhnya Allah Maha Bijaksana) dalam ciptaan-Nya (lagi Maha Mengetahui) tentang makhluk-Nya.",[["وَقَالُوا۟","Dan mereka berkata"],["مَا","Apa"],["فِى","(berada) dalam"],["بُطُونِ","(rahim)."],["هَـٰذِهِ","(daripada) ini"],["ٱلْأَنْعَـٰمِ","lembu"],["خَالِصَةٌۭ","(adalah) secara eksklusif"],["لِّذُكُورِنَا","untuk lelaki kami"],["وَمُحَرَّمٌ","dan dilarang"],["عَلَىٰٓ","pada"],["أَزْوَٰجِنَا ۖ","pasangan kita"],["وَإِن","Tetapi jika"],["يَكُن","ialah"],["مَّيْتَةًۭ","(lahir) mati"],["فَهُمْ","kemudian mereka (semua)"],["فِيهِ","di dalamnya"],["شُرَكَآءُ ۚ","(adalah) rakan kongsi"],["سَيَجْزِيهِمْ","Dia akan membalas mereka"],["وَصْفَهُمْ ۚ","(untuk) atribusi mereka"],["إِنَّهُۥ","Sesungguhnya Dia"],["حَكِيمٌ","(adalah) Maha Bijaksana"],["عَلِيمٌۭ","Maha Mengetahui"]]],"929":["(Sesungguhnya rugilah orang-orang yang membunuh) dengan dibaca takhfif dan tasydid (anak-anak mereka) dengan mengubur mereka hidup-hidup (karena kebodohan) karena ketidakmengertian mereka (lagi tidak mengetahui dan mereka mengharamkan apa yang Allah telah memberi rezeki kepada mereka) yaitu apa-apa yang telah disebutkan (dengan semata-mata mengada-adakan terhadap Allah. Sesungguhnya mereka telah sesat dan tidaklah mereka mendapat petunjuk.)",[["قَدْ","Sungguh"],["خَسِرَ","(ada) hilang"],["ٱلَّذِينَ","orang yang"],["قَتَلُوٓا۟","dibunuh"],["أَوْلَـٰدَهُمْ","anak-anak mereka"],["سَفَهًۢا","(dalam) kebodohan"],["بِغَيْرِ","tanpa"],["عِلْمٍۢ","pengetahuan"],["وَحَرَّمُوا۟","dan melarang"],["مَا","apa"],["رَزَقَهُمُ","(bas telah) disediakan (kepada) mereka"],["ٱللَّهُ","(oleh) Allah"],["ٱفْتِرَآءً","mencipta (bohong)"],["عَلَى","terhadap"],["ٱللَّهِ ۚ","Allah"],["قَدْ","Sungguh"],["ضَلُّوا۟","mereka telah sesat"],["وَمَا","dan bukan"],["كَانُوا۟","mereka adalah"],["مُهْتَدِينَ","berpandu"]]],"930":["(Dan Dialah yang menjadikan) yang telah menciptakan (kebun-kebun) yang mendatar di permukaan tanah, seperti tanaman semangka (dan yang tidak terhampar) yang berdiri tegak di atas pohon seperti pohon kurma (dan) Dia menjadikan (pohon kurma dan tanaman-tanaman yang bermacam-macam buahnya) yakni yang berbeda-beda buah dan bijinya baik bentuk maupun rasanya (dan zaitun dan delima yang serupa) dedaunannya; menjadi hal (dan tidak sama) rasa keduanya (Makanlah dari buahnya yang bermacam-macam itu bila dia berbuah) sebelum masak betul (dan tunaikanlah haknya di hari memetik hasilnya) dengan dibaca fatah atau kasrah; yaitu sepersepuluhnya atau setengahnya (dan janganlah kamu berlebih-lebihan) dengan memberikannya semua tanpa sisa sedikit pun buat orang-orang tanggunganmu. (Sesungguhnya Allah tidak menyukai orang-orang yang berlebih-lebihan) yaitu orang-orang yang melampaui batas hal-hal yang telah ditentukan bagi mereka.",[["۞ وَهُوَ","Dan Dia"],["ٱلَّذِىٓ","(ialah) Yang"],["أَنشَأَ","dihasilkan"],["جَنَّـٰتٍۢ","taman-taman"],["مَّعْرُوشَـٰتٍۢ","bertali"],["وَغَيْرَ","dan selain daripada"],["مَعْرُوشَـٰتٍۢ","bertali"],["وَٱلنَّخْلَ","dan pokok kurma"],["وَٱلزَّرْعَ","dan tanaman"],["مُخْتَلِفًا","pelbagai"],["أُكُلُهُۥ","(adalah) rasanya"],["وَٱلزَّيْتُونَ","dan buah zaitun"],["وَٱلرُّمَّانَ","dan buah delima"],["مُتَشَـٰبِهًۭا","serupa"],["وَغَيْرَ","dan selain daripada"],["مُتَشَـٰبِهٍۢ ۚ","serupa"],["كُلُوا۟","makan"],["مِن","daripada"],["ثَمَرِهِۦٓ","buahnya"],["إِذَآ","apabila"],["أَثْمَرَ","ia membuahkan hasil"],["وَءَاتُوا۟","dan memberi"],["حَقَّهُۥ","sepatutnya"],["يَوْمَ","(pada) hari"],["حَصَادِهِۦ ۖ","(dari) tuaiannya"],["وَلَا","Dan jangan"],["تُسْرِفُوٓا۟ ۚ","(menjadi) boros"],["إِنَّهُۥ","Sesungguhnya Dia"],["لَا","tidak"],["يُحِبُّ","cinta"],["ٱلْمُسْرِفِينَ","mereka yang boros"]]],"931":["(Dan) Dia menjadikan (di antara binatang ternak itu sebagai kendaraan angkutan) yaitu layak untuk mengangkut barang-barang, seperti unta yang sudah dewasa (dan sebagai binatang sembelihan) yang tak layak untuk dijadikan angkutan, seperti unta yang masih muda dan kambing. Ia dinamakan farsy/hamparan karena ia mirip dengan hamparan tanah mengingat ia sangat dekat dengannya. (Makanlah dari rezeki yang telah diberikan Allah kepadamu dan janganlah kamu mengikuti langkah-langkah setan) jalan setan di dalam masalah pengharaman dan penghalalan. (Sesungguhnya setan itu musuh yang nyata bagimu) yang jelas permusuhannya.",[["وَمِنَ","Dan daripada"],["ٱلْأَنْعَـٰمِ","lembu itu"],["حَمُولَةًۭ","(adalah beberapa untuk) beban"],["وَفَرْشًۭا ۚ","dan (sebahagian untuk) daging"],["كُلُوا۟","makan"],["مِمَّا","tentang apa"],["رَزَقَكُمُ","(telah) disediakan (kepada) kamu"],["ٱللَّهُ","(oleh) Allah"],["وَلَا","dan jangan"],["تَتَّبِعُوا۟","ikut"],["خُطُوَٰتِ","(the) jejak kaki"],["ٱلشَّيْطَـٰنِ ۚ","(dari) Syaitan"],["إِنَّهُۥ","Sesungguhnya dia"],["لَكُمْ","(adalah) kepada kamu"],["عَدُوٌّۭ","seorang musuh"],["مُّبِينٌۭ","terbuka"]]],"932":["(Yaitu delapan binatang yang berpasangan) yang bermacam-macam, menjadi badal dari Lafal humuulah dan farasy (dari domba) yang sejodoh (sepasang) jantan dan betina (dan dari kambing) dibaca fathah atau sukun (sepasang. Katakanlah) hai Muhammad, terhadap orang yang terkadang mengharamkan binatang jantan dan terkadang mengharamkan binatang betina kemudian ia mengaitkan hal itu kepada Allah (\"Apakah dua yang jantan) baik dari kambing maupun dari domba (diharamkan) Allah atas kamu (ataukah dua yang betina) dari kedua jenis ternak itu (ataukah yang ada dalam kandungan dua betinanya?\") baik jantan atau pun betina. (Terangkanlah kepadaku dengan berdasar pengetahuan) tentang cara pengharaman hal itu (jika kamu memang orang-orang yang benar) di dalam ayat ini terkandung makna sebagai berikut: dari manakah datangnya pengharaman itu? Apabila dari pihak jantan, maka semua binatang yang jantan berarti haram; atau bila dari pihak betina, maka berarti semua binatang betina haram hukumnya dan demikian pula binatang-binatang yang masih berada di dalam rahimnya maka berarti kedua jenis itu diharamkan. Lalu dari manakah adanya pengecualian ini sedangkan kata tanya menunjukkan makna ingkar.",[["ثَمَـٰنِيَةَ","Lapan"],["أَزْوَٰجٍۢ ۖ","berpasangan"],["مِّنَ","daripada"],["ٱلضَّأْنِ","biri-biri itu"],["ٱثْنَيْنِ","dua"],["وَمِنَ","dan daripada"],["ٱلْمَعْزِ","kambing-kambing itu"],["ٱثْنَيْنِ ۗ","dua"],["قُلْ","Katakanlah"],["ءَآلذَّكَرَيْنِ","(Adalah) dua lelaki itu"],["حَرَّمَ","Dia telah melarang"],["أَمِ","atau"],["ٱلْأُنثَيَيْنِ","dua perempuan itu"],["أَمَّا","atau apa"],["ٱشْتَمَلَتْ","mengandungi"],["عَلَيْهِ","[di dalamnya]"],["أَرْحَامُ","(rahim)."],["ٱلْأُنثَيَيْنِ ۖ","(dari) dua perempuan itu"],["نَبِّـُٔونِى","maklumkan aku"],["بِعِلْمٍ","dengan ilmu"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"933":["(Dan dari sepasang unta dan dari sepasang lembu, katakanlah, \"Apakah dua yang jantan yang diharamkan ataukah dua yang betina, ataukah yang ada di dalam kandungan dua betinanya. Apakah) bahkan (kamu menyaksikan) hadir (di waktu Allah menetapkan ini bagimu?) tentang pengharaman ini kemudian sengaja kamu menyatakan hal ini, tidak, bahkan kamu adalah orang-orang yang dusta dalam hal ini. (Maka siapakah) tak ada seorang pun (yang lebih lalim daripada orang-orang yang membuat-buat dusta terhadap Allah) dalam hal itu (untuk menyesatkan manusia tanpa pengetahuan?\" Sesungguhnya Allah tidak memberi petunjuk kepada orang-orang yang lalim.)",[["وَمِنَ","Dan daripada"],["ٱلْإِبِلِ","unta"],["ٱثْنَيْنِ","dua"],["وَمِنَ","dan daripada"],["ٱلْبَقَرِ","lembu"],["ٱثْنَيْنِ ۗ","dua"],["قُلْ","Katakanlah"],["ءَآلذَّكَرَيْنِ","(Adakah) dua lelaki itu"],["حَرَّمَ","Dia (telah) melarang"],["أَمِ","atau"],["ٱلْأُنثَيَيْنِ","dua perempuan itu"],["أَمَّا","atau apa"],["ٱشْتَمَلَتْ","mengandungi"],["عَلَيْهِ","[di dalamnya]"],["أَرْحَامُ","(rahim)."],["ٱلْأُنثَيَيْنِ ۖ","(dari) dua perempuan itu"],["أَمْ","Atau"],["كُنتُمْ","adakah kamu"],["شُهَدَآءَ","saksi"],["إِذْ","apabila"],["وَصَّىٰكُمُ","menyuruh kamu"],["ٱللَّهُ","Allah"],["بِهَـٰذَا ۚ","dengan ini"],["فَمَنْ","Kemudian siapa"],["أَظْلَمُ","(adalah) lebih zalim"],["مِمَّنِ","daripada (seorang) yang"],["ٱفْتَرَىٰ","mencipta"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["كَذِبًۭا","satu pembohongan"],["لِّيُضِلَّ","untuk mengelirukan"],["ٱلنَّاسَ","manusia"],["بِغَيْرِ","tanpa"],["عِلْمٍ ۗ","pengetahuan"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يَهْدِى","panduan"],["ٱلْقَوْمَ","manusia"],["ٱلظَّـٰلِمِينَ","kesalahan itu"]]],"934":["(Katakanlah, \"Tiadalah aku peroleh dalam wahyu yang diwahyukan kepadaku) tentang sesuatu (yang diharamkan bagi orang yang hendak memakannya kecuali kalau yang dimakan itu) dengan memakai ya dan ta (bangkai) dengan dibaca nashab dan menurut suatu qiraat dibaca rafa` serta tahtaniyyah (atau darah yang mengalir) yang beredar berbeda dengan darah yang tidak mengalir seperti hati dan limpa (atau daging babi karena sesungguhnya semua itu kotor) haram (atau) kecuali jika hewan itu (binatang yang disembelih atas nama selain Allah) yakni hewan yang dipotong dengan menyebut nama selain nama Allah. (Siapa yang dalam keadaan terpaksa) menghadapi semua yang telah disebutkan sehingga ia memakannya (sedangkan ia tidak menginginkannya dan tidak pula melampaui batas, maka sesungguhnya Tuhanmu Maha Pengampun) kepadanya atas apa yang telah dimakannya (lagi Maha Penyayang.\") terhadapnya. Kemudian apa yang telah disebutkan itu dilengkapi dengan sebuah hadis yang menambahkan yaitu setiap hewan yang bertaring dan setiap burung yang berkuku tajam.",[["قُل","Katakanlah"],["لَّآ","Tidak"],["أَجِدُ","(ada) aku dapati"],["فِى","dalam"],["مَآ","apa"],["أُوحِىَ","telah didedahkan"],["إِلَىَّ","kepada aku"],["مُحَرَّمًا","(apa-apa) yang dilarang"],["عَلَىٰ","kepada"],["طَاعِمٍۢ","seorang pemakan"],["يَطْعَمُهُۥٓ","siapa yang memakannya"],["إِلَّآ","kecuali"],["أَن","bahawa"],["يَكُونَ","jadilah"],["مَيْتَةً","mati"],["أَوْ","atau"],["دَمًۭا","darah"],["مَّسْفُوحًا","dicurahkan"],["أَوْ","atau"],["لَحْمَ","(the) daging"],["خِنزِيرٍۢ","(dari) babi"],["فَإِنَّهُۥ","kerana sesungguhnya, ia"],["رِجْسٌ","(adalah) najis"],["أَوْ","atau"],["فِسْقًا","(iaitu) kemaksiatan"],["أُهِلَّ","[adalah] berdedikasi"],["لِغَيْرِ","kepada selain daripada"],["ٱللَّهِ","Allah"],["بِهِۦ ۚ","[di atasnya]"],["فَمَنِ","Tetapi siapa pun"],["ٱضْطُرَّ","(adalah) terpaksa"],["غَيْرَ","tidak"],["بَاغٍۢ","berkeinginan"],["وَلَا","dan bukan"],["عَادٍۢ","melanggar"],["فَإِنَّ","maka sesungguhnya"],["رَبَّكَ","Tuhanmu"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"935":["(Dan kepada orang-orang Yahudi) yaitu pemeluk agama Yahudi (Kami haramkan segala binatang yang berkuku) maksudnya hewan yang jari-jari kakinya tidak terpisah-pisah seperti unta dan burung unta (dan dari sapi dan domba, Kami haramkan atas mereka lemak dari kedua binatang) yaitu lemak perut dan lemak pantat (kecuali lemak yang melekat di punggung keduanya) lemak yang menggantung pada punggungnya (atau) yang menempel (di perut besar) yang ada di lambung, kata jamak dari haawiyaa atau haawiyah (atau yang bercampur dengan tulang) lemak yang menempel di tulang, maka jenis lemak ini dihalalkan untuk mereka. (Demikianlah) masalah pengharaman ini (Kami hukum mereka) sebagai balasan (atas kedurhakaan mereka) oleh sebab kelaliman mereka sendiri sebagaimana yang telah disebutkan dalam surah An-Nisa (dan sesungguhnya Kami adalah Maha Benar) di dalam berita-berita Kami dan janji-janji Kami.",[["وَعَلَى","Dan kepada"],["ٱلَّذِينَ","orang yang"],["هَادُوا۟","adalah Yahudi"],["حَرَّمْنَا","Kami melarang"],["كُلَّ","setiap"],["ذِى","(haiwan) dengan"],["ظُفُرٍۢ ۖ","cakar"],["وَمِنَ","dan daripada"],["ٱلْبَقَرِ","lembu"],["وَٱلْغَنَمِ","dan biri-biri"],["حَرَّمْنَا","Kami melarang"],["عَلَيْهِمْ","kepada mereka"],["شُحُومَهُمَآ","lemak mereka"],["إِلَّا","kecuali"],["مَا","apa"],["حَمَلَتْ","dibawa"],["ظُهُورُهُمَآ","belakang mereka"],["أَوِ","atau"],["ٱلْحَوَايَآ","bahagian dalam"],["أَوْ","atau"],["مَا","apa"],["ٱخْتَلَطَ","(adalah) menyertai"],["بِعَظْمٍۢ ۚ","dengan tulang"],["ذَٰلِكَ","Itu"],["جَزَيْنَـٰهُم","(ialah) balasan mereka"],["بِبَغْيِهِمْ ۖ","kerana pemberontakan mereka"],["وَإِنَّا","Dan sesungguhnya, Kami"],["لَصَـٰدِقُونَ","[sesungguhnya] adalah benar"]]],"936":["(Maka jika mereka mendustakan kamu) mengenai apa yang engkau sampaikan (katakanlah,) kepada mereka (\"Tuhanmu mempunyai rahmat yang luas) sehingga Dia tidak menyegerakan untuk menghukum kamu; di dalam ayat ini terkandung ajakan yang lembut untuk mereka kepada keimanan (dan siksa-Nya tidak dapat ditolak) yakni azab-Nya apabila datang (dari kaum yang berdosa.\")",[["فَإِن","Tetapi jika"],["كَذَّبُوكَ","mereka menafikan kamu"],["فَقُل","kemudian berkata"],["رَّبُّكُمْ","Tuhanmu"],["ذُو","(ialah) Pemilik"],["رَحْمَةٍۢ","(dari) Rahmat"],["وَٰسِعَةٍۢ","luas"],["وَلَا","tetapi tidak"],["يُرَدُّ","akan berpatah balik"],["بَأْسُهُۥ","murkanya"],["عَنِ","daripada"],["ٱلْقَوْمِ","manusia"],["ٱلْمُجْرِمِينَ","(yang) penjenayah"]]],"937":["(0rang-orang yang mempersekutukan Tuhan akan mengatakan, \"Jika Allah menghendaki niscaya kami tidak mempersekutukan-Nya) (dan juga bapak-bapak kami dan tidak pula kami mengharamkan sesuatu apa pun.\") kemusyrikan kami dan pengharaman kami adalah berdasarkan kehendak-Nya, Dia rela dengan ketentuan itu. Allah berfirman: (Demikian pulalah) sebagaimana mereka telah mendustakan (orang-orang yang sebelum mereka telah mendustakan) para utusan mereka (sampai mereka merasakan siksaan Kami) azab Kami (Katakanlah, \"Adakah kamu mempunyai sesuatu pengetahuan) bahwa Allah telah rela dengan hal itu (sehingga dapat kamu mengemukakannya kepada Kami?\") pasti kamu tidak mempunyai pengetahuan tentang hal ini. (Tidak) tiadakan (kamu mengikuti) dalam hal ini (kecuali hanya dugaan belaka dan tidak lain) tiada lain (kamu hanya berdusta) hanya membual.",[["سَيَقُولُ","Akan berkata"],["ٱلَّذِينَ","orang yang"],["أَشْرَكُوا۟","mempersekutukan (dengan Allah)"],["لَوْ","Jika"],["شَآءَ","Sempat berkehendak"],["ٱللَّهُ","Allah"],["مَآ","tidak"],["أَشْرَكْنَا","kami (akan) mempersekutukan (dengan Allah)"],["وَلَآ","dan bukan"],["ءَابَآؤُنَا","nenek moyang kita"],["وَلَا","dan bukan"],["حَرَّمْنَا","kami (akan) melarang"],["مِن","[daripada]"],["شَىْءٍۢ ۚ","sesuatu"],["كَذَٰلِكَ","Begitu juga"],["كَذَّبَ","dinafikan"],["ٱلَّذِينَ","orang yang"],["مِن","(daripada)"],["قَبْلِهِمْ","sebelum mereka"],["حَتَّىٰ","sehingga"],["ذَاقُوا۟","mereka rasa"],["بَأْسَنَا ۗ","kemarahan kami"],["قُلْ","Katakanlah"],["هَلْ","Adakah"],["عِندَكُم","bersama kamu"],["مِّنْ","[daripada]"],["عِلْمٍۢ","sebarang pengetahuan"],["فَتُخْرِجُوهُ","kemudian menghasilkannya"],["لَنَآ ۖ","bagi kami"],["إِن","Tidak"],["تَتَّبِعُونَ","kamu ikut"],["إِلَّا","kecuali"],["ٱلظَّنَّ","andaian itu"],["وَإِنْ","dan bukan"],["أَنتُمْ","kamu (buat)"],["إِلَّا","tetapi"],["تَخْرُصُونَ","meneka"]]],"938":["(Katakanlah) apabila kamu tidak mempunyai hujah (\"Allah mempunyai hujah yang jelas lagi kuat) yang sempurna (maka jika Dia menghendaki) memberikan hidayah kepadamu (pasti Dia memberi hidayah kepada kamu semuanya.\")",[["قُلْ","Katakanlah"],["فَلِلَّهِ","Dengan Allah"],["ٱلْحُجَّةُ","(ialah) hujahnya"],["ٱلْبَـٰلِغَةُ ۖ","yang konklusif"],["فَلَوْ","Dan jika"],["شَآءَ","Dia (telah) menghendaki"],["لَهَدَىٰكُمْ","sesungguhnya Dia telah memberi petunjuk kepada kamu"],["أَجْمَعِينَ","semua"]]],"939":["(Katakanlah, \"Bawalah ke mari) datangkanlah (saksi-saksi kamu yang dapat mempersaksikan bahwasanya Allah telah mengharamkan ini\") yaitu makanan yang kamu haramkan. (Jika mereka mempersaksikan, maka janganlah kamu ikut pula menjadi saksi bersama mereka dan janganlah kamu mengikuti hawa nafsu orang-orang yang mendustakan ayat-ayat Kami dan orang-orang yang tidak beriman kepada kehidupan akhirat sedangkan mereka mempersekutukan Tuhan mereka) berlaku musyrik terhadap-Nya.",[["قُلْ","Katakanlah"],["هَلُمَّ","Bawa ke hadapan"],["شُهَدَآءَكُمُ","saksi kamu"],["ٱلَّذِينَ","orang yang"],["يَشْهَدُونَ","memberi keterangan"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["حَرَّمَ","dilarang"],["هَـٰذَا ۖ","ini"],["فَإِن","Kemudian jika"],["شَهِدُوا۟","mereka bersaksi"],["فَلَا","maka (buat) jangan"],["تَشْهَدْ","memberi keterangan"],["مَعَهُمْ ۚ","bersama mereka"],["وَلَا","Dan jangan"],["تَتَّبِعْ","ikut"],["أَهْوَآءَ","(the) keinginan"],["ٱلَّذِينَ","orang yang"],["كَذَّبُوا۟","dinafikan"],["بِـَٔايَـٰتِنَا","Tanda-Tanda Kami"],["وَٱلَّذِينَ","dan orang yang"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"],["بِٱلْـَٔاخِرَةِ","di akhirat"],["وَهُم","sedangkan mereka"],["بِرَبِّهِمْ","dengan Tuhan mereka"],["يَعْدِلُونَ","sediakan sama"]]],"940":["(Katakanlah, \"Marilah kubacakan yang diharamkan atas kamu oleh Tuhanmu, yaitu) an bermakna menafsirkan (janganlah kamu mempersekutukan sesuatu dengan Dia dan) berbuat baiklah (terhadap kedua orang tua sebaik-baiknya dan janganlah kamu membunuh anak-anak kamu) dengan menguburkan hidup-hidup (karena) sebab (takut kemiskinan) kemelaratan yang kamu khawatirkan (Kami akan memberi rezeki kepadamu dan kepada mereka dan janganlah kamu mendekati perbuatan-perbuatan yang keji) dosa-dosa besar seperti perbuatan zina (baik yang tampak di antaranya maupun yang tersembunyi) yang kelihatan dan yang tidak kelihatan. (Dan janganlah kamu membunuh jiwa yang diharamkan Allah membunuhnya kecuali dengan sesuatu sebab yang benar.\") yaitu seperti hukum kisas dan hudud murtad serta rajam bagi yang pezina muhshan. (Demikian itu) apa yang telah disebutkan itu (adalah yang diperintahkan oleh Tuhanmu kepadamu supaya kamu memahaminya) supaya kamu memikirkannya.",[["۞ قُلْ","Katakanlah"],["تَعَالَوْا۟","Datang"],["أَتْلُ","aku akan mengaji"],["مَا","apa"],["حَرَّمَ","telah melarang"],["رَبُّكُمْ","Tuhanmu"],["عَلَيْكُمْ ۖ","kepada kamu"],["أَلَّا","Itu (jangan) tidak"],["تُشْرِكُوا۟","bersekutu"],["بِهِۦ","dengan Dia"],["شَيْـًۭٔا ۖ","sesuatu"],["وَبِٱلْوَٰلِدَيْنِ","dan dengan ibu bapa"],["إِحْسَـٰنًۭا ۖ","(jadi) baik"],["وَلَا","dan jangan"],["تَقْتُلُوٓا۟","membunuh"],["أَوْلَـٰدَكُم","anak-anak kamu"],["مِّنْ","(keluar) daripada"],["إِمْلَـٰقٍۢ ۖ","kemiskinan"],["نَّحْنُ","Kami"],["نَرْزُقُكُمْ","menyediakan untuk kamu"],["وَإِيَّاهُمْ ۖ","dan untuk mereka"],["وَلَا","Dan jangan"],["تَقْرَبُوا۟","pergi dekat"],["ٱلْفَوَٰحِشَ","[the] maksiat"],["مَا","apa"],["ظَهَرَ","(adalah) jelas"],["مِنْهَا","daripada mereka"],["وَمَا","dan apa"],["بَطَنَ ۖ","(adalah) disembunyikan"],["وَلَا","Dan jangan"],["تَقْتُلُوا۟","membunuh"],["ٱلنَّفْسَ","jiwa"],["ٱلَّتِى","yang"],["حَرَّمَ","telah (telah) diharamkan"],["ٱللَّهُ","(oleh) Allah"],["إِلَّا","kecuali"],["بِٱلْحَقِّ ۚ","dengan hak (undang-undang)."],["ذَٰلِكُمْ","Itu"],["وَصَّىٰكُم","(Dia) telah memerintahkan kamu"],["بِهِۦ","dengannya"],["لَعَلَّكُمْ","supaya kamu"],["تَعْقِلُونَ","guna akal"]]],"941":["(Dan janganlah kamu dekati harta anak yatim kecuali dengan cara) dengan sikap yang (lebih baik) yaitu cara yang di dalamnya mengandung kemaslahatan/manfaat bagi anak yatim hingga ia dewasa) seumpamanya dia sudah balig. (Dan sempurnakanlah takaran dan timbangan dengan adil) secara adil dan tidak curang. (Kami tidak memikulkan beban kepada seseorang melainkan sekadar kesanggupannya) sesuai dengan kemampuannya dalam hal ini; apabila ia berbuat kekeliruan di dalam menakar atau menimbang sesuatu, maka Allah mengetahui kebenaran niat yang sesungguhnya, oleh karena itu maka ia tidak berdosa, sebagaimana yang telah disebutkan dalam hadis Nabi saw. (Dan apabila kamu berkata) dalam masalah hukum atau lainnya (maka hendaklah kamu berlaku adil) jujur (kendatipun dia) orang yang bersangkutan (adalah kerabatmu) famili (dan penuhilah janji Allah. Yang demikian itu diperintahkan Allah kepadamu agar kamu ingat) dengan memakai tasydid agar menjadikannya sebagai pelajaran; dan juga dibaca dengan sukun.",[["وَلَا","Dan jangan"],["تَقْرَبُوا۟","pergi dekat"],["مَالَ","kekayaan"],["ٱلْيَتِيمِ","(dari) anak-anak yatim"],["إِلَّا","kecuali"],["بِٱلَّتِى","dengan itu"],["هِىَ","yang"],["أَحْسَنُ","(adalah) terbaik"],["حَتَّىٰ","sehingga"],["يَبْلُغَ","dia sampai"],["أَشُدَّهُۥ ۖ","kematangannya"],["وَأَوْفُوا۟","Dan berikan sepenuhnya"],["ٱلْكَيْلَ","ukuran"],["وَٱلْمِيزَانَ","dan berat"],["بِٱلْقِسْطِ ۖ","dengan keadilan"],["لَا","Tidak"],["نُكَلِّفُ","Kita bebankan"],["نَفْسًا","mana-mana jiwa"],["إِلَّا","kecuali"],["وُسْعَهَا ۖ","(kepada) kapasitinya"],["وَإِذَا","Dan apabila"],["قُلْتُمْ","kamu bercakap"],["فَٱعْدِلُوا۟","maka berlaku adillah"],["وَلَوْ","walaupun"],["كَانَ","dia adalah"],["ذَا","(salah satu)"],["قُرْبَىٰ ۖ","saudara terdekat"],["وَبِعَهْدِ","Dan (perjanjian)."],["ٱللَّهِ","(milik) Allah"],["أَوْفُوا۟ ۚ","memenuhi"],["ذَٰلِكُمْ","Itu"],["وَصَّىٰكُم","(Dia) telah memerintahkan kamu"],["بِهِۦ","dengannya"],["لَعَلَّكُمْ","supaya kamu"],["تَذَكَّرُونَ","ingat"]]],"942":["(Dan bahwa) dengan memakai harakat fatah mentakdirkan lam, dan dengan memakai harakat kasrah sebagai jumlah isti'naf/permulaan (hal ini) apa yang Kami pesankan kepada kamu (adalah jalan-Ku yang lurus) menjadi hal (maka ikutilah dia; dan janganlah kamu mengikuti jalan-jalan) cara-cara yang bertentangan dengannya (karena jalan itu mencerai-beraikan) dengan membuang salah satu di antara dua huruf ta, yakni akan menyelewengkan (kamu dari jalan-Nya) agama-Nya (yang demikian itu diperintahkan Allah kepadamu agar kamu bertakwa.)",[["وَأَنَّ","Dan bahawa"],["هَـٰذَا","ini"],["صِرَٰطِى","(ialah) jalan aku"],["مُسْتَقِيمًۭا","lurus"],["فَٱتَّبِعُوهُ ۖ","jadi ikutilah"],["وَلَا","Dan jangan"],["تَتَّبِعُوا۟","ikut"],["ٱلسُّبُلَ","jalan (yang lain)."],["فَتَفَرَّقَ","maka mereka akan berpisah"],["بِكُمْ","kamu"],["عَن","daripada"],["سَبِيلِهِۦ ۚ","jalan dia"],["ذَٰلِكُمْ","Itu"],["وَصَّىٰكُم","(Dia) telah memerintahkan kamu"],["بِهِۦ","[dengannya]"],["لَعَلَّكُمْ","supaya kamu"],["تَتَّقُونَ","menjadi soleh"]]],"943":["(Kemudian Kami telah memberikan Alkitab kepada Musa) kitab Taurat; tsumma bermakna untuk tertibnya rentetan kisah (untuk menyempurnakan) nikmat (kepada orang-orang yang berbuat kebaikan) agar mengamalkan kandungan isinya (dan untuk menjelaskan) menerangkan (segala sesuatu) yang diperlukan dalam masalah agama (dan sebagai petunjuk dan rahmat agar mereka) kaum Bani Israel (terhadap hari pertemuan dengan Tuhan mereka) dengan dibangkitkannya mereka (mereka mau beriman.)",[["ثُمَّ","Lebih-lebih lagi"],["ءَاتَيْنَا","Kami memberi"],["مُوسَى","Musa"],["ٱلْكِتَـٰبَ","Kitab"],["تَمَامًا","menyelesaikan (Nikmat Kami)"],["عَلَى","pada"],["ٱلَّذِىٓ","orang yang"],["أَحْسَنَ","berbuat baik"],["وَتَفْصِيلًۭا","dan penjelasan"],["لِّكُلِّ","daripada setiap"],["شَىْءٍۢ","perkara"],["وَهُدًۭى","dan hidayah"],["وَرَحْمَةًۭ","dan belas kasihan"],["لَّعَلَّهُم","supaya mereka boleh"],["بِلِقَآءِ","dalam mesyuarat itu"],["رَبِّهِمْ","(dengan) Tuhan mereka"],["يُؤْمِنُونَ","beriman"]]],"944":["(Dan ini) maksudnya Alquran ini (adalah kitab yang Kami turunkan yang diberkati, maka ikutilah dia) hai penduduk Mekah dengan mengamalkan apa yang dikandungnya (dan bertakwalah kamu) jangan melakukan kekafiran (agar kamu diberi rahmat) Kami turunkan dia yaitu Alquran.",[["وَهَـٰذَا","Dan ini"],["كِتَـٰبٌ","(ialah) sebuah Kitab"],["أَنزَلْنَـٰهُ","Kami telah mendedahkannya"],["مُبَارَكٌۭ","diberkati"],["فَٱتَّبِعُوهُ","jadi ikutilah"],["وَٱتَّقُوا۟","dan bertakwalah kepada Allah"],["لَعَلَّكُمْ","supaya kamu"],["تُرْحَمُونَ","mendapat rahmat"]]],"945":["(Agar jangan) tidak (kamu mengatakan bahwa kitab itu hanya diturunkan kepada dua golongan saja) yaitu golongan Yahudi dan golongan Nasrani (sebelum kami dan sesungguhnya) ditakhfifkan dari innaa yang bertasydid sedangkan isimnya dibuang (kami terhadap pelajaran mereka) apa yang mereka baca (tidak memperhatikan) oleh sebab kami tidak mengerti tentangnya karena bukan bahasa kami.",[["أَن","Jangan-jangan"],["تَقُولُوٓا۟","kamu cakap"],["إِنَّمَآ","Hanya"],["أُنزِلَ","telah didedahkan"],["ٱلْكِتَـٰبُ","Kitab"],["عَلَىٰ","pada"],["طَآئِفَتَيْنِ","kedua-dua kumpulan itu"],["مِن","daripada"],["قَبْلِنَا","sebelum kita"],["وَإِن","dan sesungguhnya"],["كُنَّا","kami"],["عَن","tentang"],["دِرَاسَتِهِمْ","kajian mereka"],["لَغَـٰفِلِينَ","tentu tidak sedar"]]],"946":["(Atau agar kamu tidak mengatakan, \"Sesungguhnya jika kitab itu diturunkan kepada kami tentulah kami lebih mendapat petunjuk dari mereka.\") oleh karena kebersihan hati kami. (Sesungguhnya telah datang kepada kamu keterangan yang nyata) yaitu penjelasan (dari Tuhanmu, petunjuk dan rahmat) bagi orang yang mengikutinya (maka siapakah) artinya tidak ada seorang pun (yang lebih lalim daripada orang yang mendustakan ayat-ayat Allah dan berpaling) memalingkan diri (daripadanya. Kelak Kami akan memberi balasan kepada orang-orang yang berpaling dari ayat-ayat Kami dengan siksaan yang buruk) siksaan yang paling keras (disebabkan mereka selalu berpaling.)",[["أَوْ","Atau"],["تَقُولُوا۟","kamu cakap"],["لَوْ","Jika"],["أَنَّآ","[bahawa]"],["أُنزِلَ","telah didedahkan"],["عَلَيْنَا","kepada kami"],["ٱلْكِتَـٰبُ","Kitab"],["لَكُنَّآ","sesungguhnya kami (akan) begitu"],["أَهْدَىٰ","lebih baik dibimbing"],["مِنْهُمْ ۚ","daripada mereka"],["فَقَدْ","Maka sesungguhnya"],["جَآءَكُم","telah datang kepada kamu"],["بَيِّنَةٌۭ","bukti yang jelas"],["مِّن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["وَهُدًۭى","dan Petunjuk"],["وَرَحْمَةٌۭ ۚ","dan Rahmat"],["فَمَنْ","Kemudian siapa"],["أَظْلَمُ","(adalah) lebih zalim"],["مِمَّن","daripada (dia) yang"],["كَذَّبَ","menafikan"],["بِـَٔايَـٰتِ","[dengan] (the) Ayat"],["ٱللَّهِ","(milik) Allah"],["وَصَدَفَ","dan berpaling"],["عَنْهَا ۗ","daripada mereka"],["سَنَجْزِى","Kami akan membalasnya"],["ٱلَّذِينَ","orang yang"],["يَصْدِفُونَ","berpaling"],["عَنْ","daripada"],["ءَايَـٰتِنَا","Tanda-Tanda Kami"],["سُوٓءَ","(dengan) kejahatan"],["ٱلْعَذَابِ","hukuman"],["بِمَا","kerana"],["كَانُوا۟","mereka dahulu"],["يَصْدِفُونَ","berpaling"]]],"947":["(Tiadalah yang mereka nantikan) apa yang mereka nanti-nanti (kecuali hanyalah datang kepada mereka) dapat dibaca ta`tiyahum atau ya`tiyahum (malaikat-malaikat) untuk mencabut arwah-arwah mereka (atau kedatangan Tuhanmu) yaitu perintah-Nya yang dimaksud adalah azab-Nya (atau kedatangan beberapa ayat Tuhanmu) tanda-tanda dari Tuhanmu yang menunjukkan dekatnya hari kiamat. (Pada hari datangnya beberapa ayat dari Tuhanmu) terbitnya matahari dari ufuk barat sebagaimana yang telah disebutkan di dalam hadis riwayat Bukhari dan Muslim (tidaklah bermanfaat lagi iman seseorang kepada dirinya sendiri yang belum beriman sebelum itu) jumlah lam takun menjadi sifat dari Lafal nafsan (atau) jiwa yang belum pernah (mengusahakan kebaikan dalam masa imannya) yakni ketaatan; artinya tobatnya tidak lagi bermanfaat bagi dirinya seperti apa yang telah dijelaskan oleh hadis. (Katakanlah, \"Tunggulah olehmu) salah satu dari alamat-alamat tersebut (sesungguhnya kami pun menunggu pula.\") hal tersebut.",[["هَلْ","Adakah"],["يَنظُرُونَ","mereka menunggu"],["إِلَّآ","kecuali"],["أَن","bahawa"],["تَأْتِيَهُمُ","datang kepada mereka"],["ٱلْمَلَـٰٓئِكَةُ","para Malaikat"],["أَوْ","atau"],["يَأْتِىَ","datang"],["رَبُّكَ","Tuhanmu"],["أَوْ","atau"],["يَأْتِىَ","datang"],["بَعْضُ","beberapa (daripada)"],["ءَايَـٰتِ","(the) Tanda-tanda"],["رَبِّكَ ۗ","Tuhanmu"],["يَوْمَ","(The) Hari"],["يَأْتِى","(apabila) datang"],["بَعْضُ","beberapa (daripada)"],["ءَايَـٰتِ","(the) Tanda-tanda"],["رَبِّكَ","Tuhanmu"],["لَا","tidak"],["يَنفَعُ","akan mendapat manfaat"],["نَفْسًا","sebuah jiwa"],["إِيمَـٰنُهَا","imannya"],["لَمْ","tidak"],["تَكُنْ","(jika) ia ada"],["ءَامَنَتْ","beriman"],["مِن","daripada"],["قَبْلُ","sebelum"],["أَوْ","atau"],["كَسَبَتْ","diperolehi"],["فِىٓ","melalui"],["إِيمَـٰنِهَا","imannya"],["خَيْرًۭا ۗ","apa-apa kebaikan"],["قُلِ","Katakanlah"],["ٱنتَظِرُوٓا۟","Tunggu"],["إِنَّا","Sesungguhnya kami"],["مُنتَظِرُونَ","(ialah) orang-orang yang menunggu"]]],"948":["(Sesungguhnya orang-orang yang memecah belah agamanya) oleh sebab mereka bercerai-berai di dalamnya, yaitu mereka mengambil sebagian peraturannya dan meninggalkan sebagian lainnya (dan mereka menjadi berpuak-puak) menjadi bersekte-sekte dan masalah agama. Menurut suatu qiraat artinya mereka berpecah-belah dan meninggalkan agamanya yang harus mereka peluk, mereka adalah orang-orang Yahudi dan Nasrani (tidak ada sedikit pun tanggung jawabmu terhadap mereka) janganlah engkau menghalang-halangi mereka. (Sesungguhnya urusan mereka hanyalah terserah kepada Allah) Dialah yang mengurusnya (kemudian Allah memberitahukan kepada mereka) di akhirat kelak (apa yang telah mereka perbuat) Allah memberikan balasan kepada mereka. Ayat ini telah dinasakh dengan turunnya ayat saif/ayat yang memerintahkan berperang.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["فَرَّقُوا۟","bahagikan"],["دِينَهُمْ","agama mereka"],["وَكَانُوا۟","dan menjadi"],["شِيَعًۭا","mazhab"],["لَّسْتَ","kamu tidak"],["مِنْهُمْ","bersama mereka"],["فِى","dalam"],["شَىْءٍ ۚ","sesuatu"],["إِنَّمَآ","Hanya"],["أَمْرُهُمْ","urusan mereka"],["إِلَى","(adalah) dengan"],["ٱللَّهِ","Allah"],["ثُمَّ","kemudian"],["يُنَبِّئُهُم","Dia akan memberitahu mereka"],["بِمَا","tentang apa"],["كَانُوا۟","mereka dahulu"],["يَفْعَلُونَ","lakukan"]]],"949":["(Siapa membawa amal yang baik) yakni zikir laa ilaaha illallaah/tidak ada tuhan selain Allah (maka baginya pahala sepuluh kali lipat amalnya) balasan pahalanya adalah sepuluh kali kebaikan (dan siapa membawa perbuatan yang jahat, maka dia tidak diberi pembalasan melainkan seimbang dengan kejahatannya) balasannya yang setimpal (sedang mereka sedikit pun tidak dianiaya atau dirugikan) dikurangi sesuatu dari pembalasan yang sebenarnya.",[["مَن","Siapa pun"],["جَآءَ","datang"],["بِٱلْحَسَنَةِ","dengan perbuatan yang baik"],["فَلَهُۥ","kemudian untuk dia"],["عَشْرُ","(adalah) sepuluh (kali)"],["أَمْثَالِهَا ۖ","seumpamanya"],["وَمَن","Dan sesiapa"],["جَآءَ","datang"],["بِٱلسَّيِّئَةِ","dengan perbuatan jahat"],["فَلَا","maka tidak"],["يُجْزَىٰٓ","dia akan mendapat balasan"],["إِلَّا","kecuali"],["مِثْلَهَا","seumpamanya"],["وَهُمْ","dan mereka"],["لَا","tidak akan"],["يُظْلَمُونَ","(menjadi) dizalimi"]]],"950":["(Katakanlah, \"Sesungguhnya Aku telah ditunjuki oleh Tuhanku kepada jalan yang lurus) kemudian dijadikan badal (yaitu agama yang benar) agama yang lurus (agama Ibrahim yang lurus dan Ibrahim itu bukanlah termasuk orang-orang yang musyrik\").",[["قُلْ","Katakanlah"],["إِنَّنِى","Sesungguhnya (adapun) aku"],["هَدَىٰنِى","telah membimbing aku"],["رَبِّىٓ","Tuhanku"],["إِلَىٰ","kepada"],["صِرَٰطٍۢ","satu laluan"],["مُّسْتَقِيمٍۢ","lurus"],["دِينًۭا","sebuah agama"],["قِيَمًۭا","betul"],["مِّلَّةَ","agama"],["إِبْرَٰهِيمَ","(dari) Ibrahim"],["حَنِيفًۭا ۚ","seorang ahli tauhid yang sebenar"],["وَمَا","Dan tidak"],["كَانَ","dia adalah"],["مِنَ","daripada"],["ٱلْمُشْرِكِينَ","orang musyrik"]]],"951":["(Katakanlah, \"Sesungguhnya salatku, ibadahku) amal ibadahku, yaitu ibadah haji dan lain-lainnya (hidupku) kehidupanku (dan matiku) meninggalku (hanyalah untuk Allah, Tuhan semesta alam).",[["قُلْ","Katakanlah"],["إِنَّ","Sesungguhnya"],["صَلَاتِى","doa aku"],["وَنُسُكِى","dan upacara pengorbanan aku"],["وَمَحْيَاىَ","dan kehidupan aku"],["وَمَمَاتِى","dan kematian aku"],["لِلَّهِ","(adalah) untuk Allah"],["رَبِّ","Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"952":["(Tiada sekutu bagi-Nya) di dalam hal tersebut (dan demikian itulah) ketauhidan (yang diperintahkan kepadaku, dan aku adalah orang yang pertama-tama menyerahkan diri kepada Allah\") dari kalangan umat ini.",[["لَا","Tidak"],["شَرِيكَ","rakan kongsi"],["لَهُۥ ۖ","untuk Dia"],["وَبِذَٰلِكَ","dan dengan itu"],["أُمِرْتُ","Aku telah diperintahkan"],["وَأَنَا۠","Dan aku"],["أَوَّلُ","(yang) pertama"],["ٱلْمُسْلِمِينَ","(dari) orang-orang yang berserah diri (kepada-Nya)"]]],"953":["(Katakanlah, \"Apakah aku akan mencari Tuhan selain Allah) sebagai sesembahan; artinya aku tidak mencari Tuhan selain-Nya (Dia adalah Tuhan) yang memiliki (segala sesuatu. Dan tidaklah seorang membuat dosa) berbuat dosa (melainkan kemudaratannya kembali kepada dirinya sendiri; dan seorang yang berdosa tidak akan memikul) maksudnya seseorang tidak akan memikul (dosa) perbuatan dosa (orang lain. Kemudian kepada Tuhanmulah kamu kembali dan akan diberitakannya kepadamu apa yang kamu perselisihkan.)",[["قُلْ","Katakanlah"],["أَغَيْرَ","Adakah (ia) selain daripada"],["ٱللَّهِ","Allah"],["أَبْغِى","Aku (harus) mencari"],["رَبًّۭا","(sebagai) Tuhan"],["وَهُوَ","manakala Dia"],["رَبُّ","(ialah) Tuhan"],["كُلِّ","(daripada) setiap"],["شَىْءٍۢ ۚ","perkara"],["وَلَا","Dan tidak"],["تَكْسِبُ","memperolehi"],["كُلُّ","setiap"],["نَفْسٍ","jiwa"],["إِلَّا","kecuali"],["عَلَيْهَا ۚ","terhadap dirinya sendiri"],["وَلَا","dan bukan"],["تَزِرُ","beruang"],["وَازِرَةٌۭ","mana-mana pembawa beban"],["وِزْرَ","bebanan"],["أُخْرَىٰ ۚ","(dari) yang lain"],["ثُمَّ","Kemudian"],["إِلَىٰ","kepada"],["رَبِّكُم","Tuhanmu"],["مَّرْجِعُكُمْ","(adalah) kamu kembali"],["فَيُنَبِّئُكُم","kemudian Dia akan memberitahu kamu"],["بِمَا","tentang apa"],["كُنتُمْ","kamu dahulu"],["فِيهِ","berkenaan dengannya"],["تَخْتَلِفُونَ","berbeza"]]],"954":["(Dan Dialah yang menjadikan kamu penguasa-penguasa di bumi) jamak dari kata khalifah; yakni sebagian di antara kamu mengganti sebagian lainnya di dalam masalah kekhalifahan ini (dan Dia meninggikan sebagian kamu atas sebagian yang lain beberapa derajat) dengan harta benda, kedudukan dan lain sebagainya (untuk mengujimu) untuk mencobamu (tentang apa yang diberikan kepadamu) artinya Dia memberi kamu agar jelas siapakah di antara kamu yang taat dan siapakah yang maksiat. (Sesungguhnya Tuhanmu itu adalah amat cepat siksaan-Nya) terhadap orang-orang yang berbuat maksiat kepada-Nya (dan sesungguhnya Dia Maha Pengampun) terhadap orang-orang mukmin (lagi Maha Penyayang.\") terhadap mereka.",[["وَهُوَ","Dan Dia"],["ٱلَّذِى","(ialah) Yang"],["جَعَلَكُمْ","(telah) menjadikan kamu"],["خَلَـٰٓئِفَ","pengganti"],["ٱلْأَرْضِ","(dari) bumi"],["وَرَفَعَ","dan dinaikkan"],["بَعْضَكُمْ","sebahagian daripada kamu"],["فَوْقَ","di atas"],["بَعْضٍۢ","yang lain"],["دَرَجَـٰتٍۢ","(dalam) pangkat"],["لِّيَبْلُوَكُمْ","supaya Dia menguji kamu"],["فِى","dalam"],["مَآ","apa"],["ءَاتَىٰكُمْ ۗ","Dia telah memberi kamu"],["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["سَرِيعُ","(adalah) pantas"],["ٱلْعِقَابِ","(dalam) hukuman"],["وَإِنَّهُۥ","dan sesungguhnya Dia (adalah)"],["لَغَفُورٌۭ","[tentunya], Maha Pengampun"],["رَّحِيمٌۢ","Maha Mengasihani"]]],"955":["(Alif laam miim shaad) hanya Allah-lah yang mengetahui apa yang dimaksud dengannya.",[["الٓمٓصٓ","Alif Laam Mim Saad"]]],"956":["Ini adalah (kitab yang diturunkan kepadamu) khithab atau pembicaraan ayat ini ditujukan kepada Nabi saw. (maka janganlah ada kesempitan di dalam dadamu) kerumitan (karenanya) sewaktu engkau akan menyampaikannya karena merasa khawatir akan didustakan (supaya kamu memberi peringatan) berkaitan dengan lafal unzila, artinya supaya engkau memperingatkan (dengan kitab itu dan menjadi pelajaran) yaitu bahan pengingat (bagi orang-orang yang beriman) kepada kitab itu.",[["كِتَـٰبٌ","(Ini adalah) sebuah Kitab"],["أُنزِلَ","didedahkan"],["إِلَيْكَ","kepada kamu"],["فَلَا","jadi (biar) jangan"],["يَكُن","jadilah"],["فِى","dalam"],["صَدْرِكَ","payudara kamu"],["حَرَجٌۭ","sebarang kegelisahan"],["مِّنْهُ","daripadanya"],["لِتُنذِرَ","yang kamu beri amaran"],["بِهِۦ","dengannya"],["وَذِكْرَىٰ","dan peringatan"],["لِلْمُؤْمِنِينَ","untuk orang yang beriman"]]],"957":["Katakanlah kepada mereka, (Ikutilah apa yang diturunkan kepadamu dari Tuhanmu) yakni Alquran (dan janganlah kamu mengikuti) maksudnya jangan kamu menjadikan (selain-Nya) selain Allah, (sebagai pemimpin-pemimpin) yang kamu taati untuk berbuat maksiat kepada Allah swt. (Amat sedikitlah kamu mengambil pelajaran) dengan memakai ta atau ya; yakni mengambil pelajaran darinya. Lafal tadzakkaruun dibaca dengan mengidgamkan ta asal ke dalam dzal. Menurut suatu qiraat dibaca tadzkuruun. Sedangkan huruf maa adalah tambahan, yang diadakan untuk mengukuhkan makna sedikit, sehingga artinya menjadi amat sedikit.",[["ٱتَّبِعُوا۟","Ikut"],["مَآ","apa"],["أُنزِلَ","telah didedahkan"],["إِلَيْكُم","kepada kamu"],["مِّن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["وَلَا","dan jangan"],["تَتَّبِعُوا۟","ikut"],["مِن","daripada"],["دُونِهِۦٓ","disampingNya"],["أَوْلِيَآءَ ۗ","mana-mana sekutu"],["قَلِيلًۭا","sedikit"],["مَّا","(ialah) apa"],["تَذَكَّرُونَ","kamu ingat"]]],"958":["(Betapa banyaknya) kalimat berita dan menjadi maf`ul (negeri) yang dimaksud adalah penduduknya (yang telah Kami binasakan) Kami bermaksud untuk membinasakannya (maka datanglah kekuatan Kami) yakni siksaan Kami (tengah malam) yaitu pada malam hari (atau di waktu mereka beristirahat di tengah hari) artinya sedang tidur-tiduran di siang hari. Yang dimaksud dengan al-qailulah, artinya beristirahat di tengah hari sekalipun tidak tidur. Yakni siksaan itu terkadang datang di waktu tengah malam dan terkadang di siang hari.",[["وَكَم","Dan berapa banyak"],["مِّن","daripada"],["قَرْيَةٍ","sebuah bandar"],["أَهْلَكْنَـٰهَا","Kami memusnahkannya"],["فَجَآءَهَا","dan datang kepadanya"],["بَأْسُنَا","hukuman kita"],["بَيَـٰتًا","(pada) malam"],["أَوْ","atau"],["هُمْ","(sementara) mereka"],["قَآئِلُونَ","sedang tidur tengah hari"]]],"959":["(Maka tidak adalah keluhan mereka) yaitu perkataan mereka (di waktu datang kepada mereka siksaan Kami kecuali mengatakan, \"Sesungguhnya kami adalah orang-orang yang lalim.\")",[["فَمَا","Kemudian tidak"],["كَانَ","adalah"],["دَعْوَىٰهُمْ","rayuan mereka"],["إِذْ","apabila"],["جَآءَهُم","datang kepada mereka"],["بَأْسُنَآ","hukuman kita"],["إِلَّآ","kecuali"],["أَن","bahawa"],["قَالُوٓا۟","mereka berkata"],["إِنَّا","Sesungguhnya kami"],["كُنَّا","adalah"],["ظَـٰلِمِينَ","orang yang zalim"]]],"960":["(Maka sesungguhnya Kami akan menanyai umat-umat yang telah diutus rasul-rasul kepada mereka) yaitu kepada umat-umat tentang tanggapan mereka terhadap rasul-rasul dan pengamalan mereka terhadap apa-apa yang telah disampaikan kepada mereka (dan sesungguhnya Kami akan menanyai pula rasul-rasul Kami) tentang penyampaian mereka.",[["فَلَنَسْـَٔلَنَّ","Maka sesungguhnya Kami akan mempersoalkan"],["ٱلَّذِينَ","mereka (kepada) siapa"],["أُرْسِلَ","telah dihantar"],["إِلَيْهِمْ","kepada mereka (Rasul-rasul)"],["وَلَنَسْـَٔلَنَّ","dan sesungguhnya Kami akan mempersoalkan"],["ٱلْمُرْسَلِينَ","para Rasul"]]],"961":["(Maka sesungguhnya akan Kami kabarkan kepada mereka dengan penuh pengetahuan). Kami akan menceritakan kepada mereka tentang apa-apa yang telah mereka perbuat dengan penuh pengetahuan (dan Kami sekali-kali tidak gaib) untuk menyampaikan kepada rasul-rasul dan umat-umat terdahulu tentang apa-apa yang pernah mereka perbuat.",[["فَلَنَقُصَّنَّ","Kemudian sesungguhnya Kami akan menceritakannya"],["عَلَيْهِم","kepada mereka"],["بِعِلْمٍۢ ۖ","dengan ilmu"],["وَمَا","dan bukan"],["كُنَّا","adalah Kami"],["غَآئِبِينَ","tidak hadir"]]],"962":["(Dan timbangan) untuk amal-amal perbuatan atau untuk lembaran-lembaran catatan amal perbuatan yang ditaruh di dalamnya. Timbangan itu memiliki jarum penunjuk berat dan dua gantungan, demikian sebagaimana yang telah dijelaskan oleh hadis. Timbangan itu ada (pada hari itu) yakni hari penghisaban yang telah disebutkan, yaitu hari kiamat (adalah benar) adalah adil, menjadi sifat dari lafal al-wazn (maka barang siapa berat timbangannya) oleh kebaikan (maka mereka itulah orang-orang yang berbahagia) orang-orang yang beruntung.",[["وَٱلْوَزْنُ","Dan timbangannya"],["يَوْمَئِذٍ","hari itu"],["ٱلْحَقُّ ۚ","(akan menjadi) kebenaran"],["فَمَن","Jadi siapa"],["ثَقُلَتْ","(akan) berat"],["مَوَٰزِينُهُۥ","penimbangnya"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","[mereka]"],["ٱلْمُفْلِحُونَ","(akan menjadi) orang-orang yang berjaya"]]],"963":["(Dan siapa yang ringan timbangannya) oleh sebab amal-amal keburukannya (maka itulah orang-orang yang merugikan dirinya sendiri) yang membawa dirinya ke neraka (disebabkan mereka selalu mengingkari ayat-ayat Kami) mereka tidak mau mempercayainya.",[["وَمَنْ","Dan (untuk) mereka"],["خَفَّتْ","(akan) ringan"],["مَوَٰزِينُهُۥ","penimbangnya"],["فَأُو۟لَـٰٓئِكَ","jadi mereka"],["ٱلَّذِينَ","(akan menjadi) orang-orang yang"],["خَسِرُوٓا۟","hilang"],["أَنفُسَهُم","diri mereka"],["بِمَا","kerana"],["كَانُوا۟","mereka adalah"],["بِـَٔايَـٰتِنَا","kepada Ayat-ayat Kami"],["يَظْلِمُونَ","(melakukan) ketidakadilan"]]],"964":["(Sesungguhnya Kami telah menempatkan kamu sekalian) hai anak-anak Adam (di muka bumi dan Kami adakan bagimu di muka bumi itu sumber-sumber penghidupan) dengan memakai huruf ya, yakni sarana-sarana untuk kamu bisa hidup. Ma`ayisy jamak dari kata ma'isyah (amat sedikitlah) untuk mengukuhkan keminiman (kamu bersyukur) terhadap kesemuanya itu.",[["وَلَقَدْ","Dan sungguh"],["مَكَّنَّـٰكُمْ","Kami meneguhkan kamu"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَجَعَلْنَا","dan Kami jadikan"],["لَكُمْ","bagi kamu"],["فِيهَا","di dalamnya"],["مَعَـٰيِشَ ۗ","rezeki"],["قَلِيلًۭا","sedikit"],["مَّا","(ialah) apa"],["تَشْكُرُونَ","kamu (bersyukur)."]]],"965":["(Sesungguhnya Kami telah menciptakanmu) maksudnya ayah kamu yaitu Adam (lalu Kami bentuk tubuhmu) Kami membentuk tubuhnya sedangkan kamu masih berada di dalam sulbinya (kemudian Kami katakan kepada para malaikat, \"Bersujudlah kamu kepada Adam,\") sebagai penghormatan, yaitu dengan menundukkan punggung (maka mereka pun bersujud kecuali iblis) yaitu kakek moyang bangsa jin yang ada di antara malaikat (dia tidak termasuk mereka yang bersujud).",[["وَلَقَدْ","Dan sungguh"],["خَلَقْنَـٰكُمْ","Kami mencipta kamu"],["ثُمَّ","kemudian"],["صَوَّرْنَـٰكُمْ","Kami membentuk kamu"],["ثُمَّ","Kemudian"],["قُلْنَا","Kami berkata"],["لِلْمَلَـٰٓئِكَةِ","kepada para Malaikat"],["ٱسْجُدُوا۟","Sujud"],["لِـَٔادَمَ","kepada Adam"],["فَسَجَدُوٓا۟","Maka sujudlah mereka"],["إِلَّآ","kecuali"],["إِبْلِيسَ","Iblis"],["لَمْ","Tidak"],["يَكُن","dia adalah"],["مِّنَ","daripada"],["ٱلسَّـٰجِدِينَ","mereka yang sujud"]]],"966":["(Allah berfirman,) Maha Tinggi Allah, (\"Apakah yang menghalangimu untuk) huruf laa adalah tambahan (bersujud di waktu) tatkala (Aku menyuruhmu.\" Menjawab iblis, \"Aku lebih baik daripadanya, Engkau ciptakan aku dari api sedangkan dia Engkau ciptakan dari tanah.\")",[["قَالَ","(Allah) berfirman"],["مَا","Apa"],["مَنَعَكَ","menghalang kamu"],["أَلَّا","itu tidak"],["تَسْجُدَ","kamu sujud"],["إِذْ","apabila"],["أَمَرْتُكَ ۖ","aku perintahkan kamu"],["قَالَ","(Syaitan) berkata"],["أَنَا۠","aku"],["خَيْرٌۭ","lebih baik"],["مِّنْهُ","daripada dia"],["خَلَقْتَنِى","Kamu cipta aku"],["مِن","daripada"],["نَّارٍۢ","kebakaran"],["وَخَلَقْتَهُۥ","dan Engkau ciptakan dia"],["مِن","daripada"],["طِينٍۢ","tanah liat"]]],"967":["(Allah berfirman, \"Turunlah kamu dari surga itu) ada yang mengatakan dari langit (karena tidak patut) tidak layak (bagi kamu menyombongkan diri di dalamnya, maka keluarlah) dari surga (sesungguhnya kamu termasuk orang-orang yang hina.\") maksudnya orang-orang yang terhina.",[["قَالَ","(Allah) berfirman"],["فَٱهْبِطْ","Lepas tu turun"],["مِنْهَا","daripadanya"],["فَمَا","kerana tidak"],["يَكُونُ","ia adalah"],["لَكَ","bagi kamu"],["أَن","bahawa"],["تَتَكَبَّرَ","kamu jadi sombong"],["فِيهَا","di dalamnya"],["فَٱخْرُجْ","Jadi keluar"],["إِنَّكَ","sesungguhnya, kamu"],["مِنَ","(adalah) daripada"],["ٱلصَّـٰغِرِينَ","yang terhina"]]],"968":["(Iblis menjawab, \"Beri tangguhlah saya) artinya berilah saya kesempatan (sampai waktu mereka dibangkitkan.\") yakni sampai manusia dibangkitkan.",[["قَالَ","(Syaitan) berkata"],["أَنظِرْنِىٓ","Beri aku tangguh"],["إِلَىٰ","sehingga"],["يَوْمِ","(the) Hari"],["يُبْعَثُونَ","mereka dibangkitkan"]]],"969":["(Allah berfirman, \"Sesungguhnya kamu termasuk mereka yang diberi tangguh.\") pada ayat lain disebutkan, \"Hingga hari yang telah ditentukan,\" yaitu waktu ditiupnya sangkakala pertama.",[["قَالَ","(Allah) berfirman"],["إِنَّكَ","Sesungguhnya kamu"],["مِنَ","(adalah) daripada"],["ٱلْمُنظَرِينَ","yang diberi tangguh"]]],"970":["(Iblis menjawab, \"Karena Engkau telah menyesatkan saya) Engkau telah menghukum saya; huruf ba mengandung makna qasam/sumpah dan sebagai jawabnya ialah (saya benar-benar akan menghalang-halangi mereka) yaitu anak-anak Adam (dari jalan Engkau yang lurus) maksudnya dari jalan yang dapat mempertemukan mereka kepada Engkau.",[["قَالَ","(Syaitan) berkata"],["فَبِمَآ","Kerana"],["أَغْوَيْتَنِى","Engkau telah menyesatkanku"],["لَأَقْعُدَنَّ","pasti aku akan duduk"],["لَهُمْ","bagi mereka"],["صِرَٰطَكَ","(di) jalan kamu"],["ٱلْمُسْتَقِيمَ","yang lurus"]]],"971":["(Kemudian saya akan mendatangi mereka dari muka dan dari belakang, dari kanan dan dari kiri mereka) maksudnya dari segala penjuru, kemudian aku halang-halangi mereka untuk bisa menempuh jalan-Mu itu. Akan tetapi Ibnu Abbas memberikan penafsirannya, bahwa iblis tidak akan dapat mendatangi mereka dari arah atasnya hal itu supaya ia jangan menghalang-halangi jalan antara hamba dengan rahmat Allah swt. (dan engkau tidak akan mendapati kebanyakan mereka bersyukur\") yakni beriman.",[["ثُمَّ","Kemudian"],["لَـَٔاتِيَنَّهُم","nescaya Aku akan mendatangi mereka"],["مِّنۢ","daripada"],["بَيْنِ","sebelum"],["أَيْدِيهِمْ","mereka"],["وَمِنْ","dan daripada"],["خَلْفِهِمْ","belakang mereka"],["وَعَنْ","dan daripada"],["أَيْمَـٰنِهِمْ","hak mereka"],["وَعَن","dan daripada"],["شَمَآئِلِهِمْ ۖ","kiri mereka"],["وَلَا","dan bukan"],["تَجِدُ","Kamu (akan) dapati"],["أَكْثَرَهُمْ","kebanyakan mereka"],["شَـٰكِرِينَ","bersyukur"]]],"972":["(Allah berfirman, \"Keluarlah kamu dari surga itu sebagai orang yang terhina) dengan memakai hamzah, artinya tercela atau kena murka Allah (lagi terusir) dijauhkan dari rahmat Allah. (Sesungguhnya barang siapa di antara mereka mengikuti kamu) dari kalangan umat manusia; huruf lam menunjukkan makna ibtida/permulaan kalimat atau sebagai pendahuluan dari qasam/sumpah, yang mana sumpahnya adalah (sungguh Aku akan memenuhi neraka Jahanam dengan kamu semuanya\") yakni kamu dan anak-cucumu serta manusia. Di dalam ayat ini terkandung makna taghliibul haadhir `alal ghaaib atau mengutamakan yang hadir daripada yang tidak hadir; jumlah ini mengandung makna syarat, yakni: Barang siapa yang mengikutimu Aku akan menyiksanya.",[["قَالَ","(Allah) berfirman"],["ٱخْرُجْ","Keluar"],["مِنْهَا","daripadanya"],["مَذْءُومًۭا","terhina"],["مَّدْحُورًۭا ۖ","dan dibuang"],["لَّمَن","Sudah tentu, sesiapa sahaja"],["تَبِعَكَ","mengikut kamu"],["مِنْهُمْ","antara mereka"],["لَأَمْلَأَنَّ","pasti, aku akan penuhi"],["جَهَنَّمَ","Neraka"],["مِنكُمْ","bersama kamu"],["أَجْمَعِينَ","semua"]]],"973":["(Dan) Allah berfirman (\"Hai Adam bertempat tinggallah kamu) lafal anta merupakan pengukuhan terhadap dhamir yang terdapat di dalam lafal uskun, tujuannya ialah untuk dijadikan sebagai ma'thuf alaih (dan istrimu) yakni Hawa, dengan dibaca panjang (di surga serta makanlah olehmu berdua buah-buahan mana saja yang kamu sukai, dan janganlah kamu berdua mendekati pohon ini) dengan cara memakannya, yang dimaksud adalah pohon gandum (maka menjadilah kamu berdua termasuk orang-orang yang lalim\").",[["وَيَـٰٓـَٔادَمُ","Dan wahai Adam"],["ٱسْكُنْ","Tinggal"],["أَنتَ","kamu"],["وَزَوْجُكَ","dan isteri kamu"],["ٱلْجَنَّةَ","(dalam) Taman"],["فَكُلَا","dan kamu berdua makan"],["مِنْ","daripada"],["حَيْثُ","di mana sahaja"],["شِئْتُمَا","kamu berdua mahu"],["وَلَا","tetapi (buat) tidak"],["تَقْرَبَا","mendekati [kamu berdua]"],["هَـٰذِهِ","ini"],["ٱلشَّجَرَةَ","[the] pokok"],["فَتَكُونَا","supaya kamu berdua tidak"],["مِنَ","antara"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"974":["(Maka setan mulai menggoda keduanya) yakni iblis (untuk menampakkan) memperlihatkan (kepada keduanya apa yang tertutup) dengan wazan fu`ila dari lafal al-muwaaraah (dari mereka, yaitu auratnya dan setan berkata, \"Tuhan kamu tidak melarangmu dari mendekati pohon ini melainkan) karena khawatir (supaya kamu berdua tidak menjadi malaikat) dan menurut suatu qiraat dibaca dengan malikaini/lam dikasrahkan (atau tidak menjadi orang-orang yang kekal dalam surga\") berdasarkan hal itu maka memakan pohon itu adalah suatu keharusan sebagaimana yang disebutkan pula di dalam ayat lain, yaitu, \"Maukah saya tunjukkan kepada kamu pohon kekekalan dan kerajaan yang tidak akan binasa.\" (Q.S. Thaha 120)",[["فَوَسْوَسَ","Kemudian berbisik"],["لَهُمَا","kepada mereka berdua"],["ٱلشَّيْطَـٰنُ","syaitan"],["لِيُبْدِىَ","untuk membuat jelas"],["لَهُمَا","kepada mereka berdua"],["مَا","apa"],["وُۥرِىَ","telah disembunyikan"],["عَنْهُمَا","daripada mereka berdua"],["مِن","daripada"],["سَوْءَٰتِهِمَا","keaiban mereka"],["وَقَالَ","Dan dia berkata"],["مَا","(Adakah) tidak"],["نَهَىٰكُمَا","melarang kamu berdua"],["رَبُّكُمَا","Tuhanmu"],["عَنْ","daripada"],["هَـٰذِهِ","ini"],["ٱلشَّجَرَةِ","[the] pokok"],["إِلَّآ","kecuali"],["أَن","bahawa"],["تَكُونَا","kamu berdua menjadi"],["مَلَكَيْنِ","malaikat"],["أَوْ","atau"],["تَكُونَا","kamu berdua menjadi"],["مِنَ","daripada"],["ٱلْخَـٰلِدِينَ","yang abadi"]]],"975":["(Dan dia, setan, bersumpah kepada keduanya) setan bersumpah dengan nama Allah kepada keduanya (\"Sesungguhnya saya adalah termasuk orang yang memberi nasihat kepada kamu berdua.\") di dalam hal ini.",[["وَقَاسَمَهُمَآ","Dan dia bersumpah (kepada) keduanya"],["إِنِّى","Memang aku"],["لَكُمَا","kepada kamu berdua"],["لَمِنَ","antara"],["ٱلنَّـٰصِحِينَ","para penasihat yang ikhlas"]]],"976":["(Maka setan membujuk keduanya) untuk menurunkan kedudukan keduanya (dengan tipu daya) darinya. (Tatkala keduanya telah merasai buah pohon itu) mereka berdua telah memakannya (nampaklah bagi keduanya aurat-auratnya) yakni kedua kemaluan masing-masing tampak oleh lainnya; kedua anggota tubuh itu dinamakan sau`ah, sebab jika terbuka akan membuat malu orang yang bersangkutan (dan mulailah keduanya menutupi) maksud keduanya mengambil penutup untuk menutupi (kedua auratnya dengan daun-daun surga) untuk menutupinya. (Kemudian Tuhan mereka menyeru mereka, \"Bukankah Aku telah melarang kamu berdua dari pohon itu dan Aku katakan kepadamu, 'Sesungguhnya setan itu adalah musuh yang nyata bagi kamu berdua.')\" yang jelas permusuhannya; kata tanya menunjukkan makna penegasan.",[["فَدَلَّىٰهُمَا","Jadi dia membuat kedua-duanya jatuh"],["بِغُرُورٍۢ ۚ","dengan penipuan"],["فَلَمَّا","Kemudian apabila"],["ذَاقَا","mereka berdua rasa"],["ٱلشَّجَرَةَ","pokok itu"],["بَدَتْ","menjadi jelas"],["لَهُمَا","kepada mereka berdua"],["سَوْءَٰتُهُمَا","keaiban mereka"],["وَطَفِقَا","dan mereka mula"],["يَخْصِفَانِ","(untuk) mengikat"],["عَلَيْهِمَا","atas diri mereka sendiri"],["مِن","daripada"],["وَرَقِ","(the) daun"],["ٱلْجَنَّةِ ۖ","(dari) Taman"],["وَنَادَىٰهُمَا","Dan memanggil mereka berdua"],["رَبُّهُمَآ","Tuhan mereka"],["أَلَمْ","tidak"],["أَنْهَكُمَا","Aku melarang kamu berdua"],["عَن","daripada"],["تِلْكُمَا","ini"],["ٱلشَّجَرَةِ","[the] pokok"],["وَأَقُل","dan [aku] berkata"],["لَّكُمَآ","kepada kamu berdua"],["إِنَّ","bahawa"],["ٱلشَّيْطَـٰنَ","Syaitan"],["لَكُمَا","kepada kamu berdua"],["عَدُوٌّۭ","(adalah) musuh"],["مُّبِينٌۭ","terbuka"]]],"977":["(Keduanya berkata, \"Ya Tuhan kami, kami telah menganiaya diri kami sendiri) oleh sebab perbuatan maksiat kami berdua (dan jika Engkau tidak mengampuni kami dan memberi rahmat kepada kami, niscaya pastilah kami termasuk orang-orang yang merugi.\")",[["قَالَا","Kata mereka berdua"],["رَبَّنَا","Wahai Tuhan kami"],["ظَلَمْنَآ","kami telah melakukan kesalahan"],["أَنفُسَنَا","diri kita sendiri"],["وَإِن","dan jika"],["لَّمْ","tidak"],["تَغْفِرْ","kamu maafkan"],["لَنَا","[untuk] kita"],["وَتَرْحَمْنَا","dan kasihanilah kami"],["لَنَكُونَنَّ","pasti, kita akan jadi"],["مِنَ","antara"],["ٱلْخَـٰسِرِينَ","yang rugi"]]],"978":["(Allah berfirman, \"Turunlah kamu sekalian) yakni Adam dan Hawa serta anak-cucu kamu yang masih berada di dalam diri kamu (sebagian kamu) maksudnya sebagian keturunan (menjadi musuh bagi sebagian yang lain) sebagian mereka berlaku aniaya terhadap sebagian yang lainnya. (Dan kamu di muka bumi mempunyai tempat kediaman) yaitu tempat tinggal (dan kesenangan) tempat bersenang-senang (sampai waktu yang ditentukan.\") apabila ajal kamu telah sampai pada saatnya.",[["قَالَ","(Allah) berfirman"],["ٱهْبِطُوا۟","Turun"],["بَعْضُكُمْ","sebahagian daripada kamu"],["لِبَعْضٍ","kepada beberapa orang lain"],["عَدُوٌّۭ ۖ","(sebagai) musuh"],["وَلَكُمْ","Dan untuk kamu"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["مُسْتَقَرٌّۭ","(adalah) tempat kediaman"],["وَمَتَـٰعٌ","dan rezeki"],["إِلَىٰ","bagi"],["حِينٍۢ","suatu masa"]]],"979":["(Allah berfirman, \"Di muka bumi itu kamu hidup dan di muka bumi itu kamu mati, dan dari bumi itu pula kamu akan dikeluarkan\") dibangkitkan, dengan memakai bina fa`il dan bina maf`ul atau bentuk aktif dan bentuk pasif.",[["قَالَ","Dia berkata"],["فِيهَا","Di dalamnya"],["تَحْيَوْنَ","kamu akan hidup"],["وَفِيهَا","dan di dalamnya"],["تَمُوتُونَ","kamu akan mati"],["وَمِنْهَا","dan daripadanya"],["تُخْرَجُونَ","kamu akan dilahirkan"]]],"980":["(Hai anak Adam! Sesungguhnya Kami telah menurunkan kepadamu pakaian) Kami telah menciptakannya untuk kamu (untuk menutupi) guna menutupi (auratmu dan pakaian perhiasan) pakaian yang digunakan sebagai perhiasan. (Dan pakaian takwa) yakni amal saleh dan akhlak yang baik; dengan dibaca nashab karena diathafkan kepada lafal libaasan, dan dibaca rafa' sebagai mubtada sedangkan khabarnya ialah jumlah berikut ini (itulah yang lebih baik. Yang demikian itu adalah sebagian tanda-tanda kekuasaan Allah) bukti-bukti yang menunjukkan kekuasaan-Nya (mudah-mudahan mereka selalu ingat) kemudian mau beriman; di dalam jumlah ini terkandung iltifat atau kata sindiran terhadap mukhathab atau orang yang diajak bicara.",[["يَـٰبَنِىٓ","Wahai Kanak-kanak"],["ءَادَمَ","(dari) Adam"],["قَدْ","Sesungguhnya"],["أَنزَلْنَا","Kami telah menurunkan"],["عَلَيْكُمْ","kepada kamu"],["لِبَاسًۭا","pakaian"],["يُوَٰرِى","ia meliputi"],["سَوْءَٰتِكُمْ","keaiban kamu"],["وَرِيشًۭا ۖ","dan (sebagai) perhiasan"],["وَلِبَاسُ","Tetapi pakaian"],["ٱلتَّقْوَىٰ","(dari) kebenaran"],["ذَٰلِكَ","bahawa"],["خَيْرٌۭ ۚ","(adalah) terbaik"],["ذَٰلِكَ","Itu"],["مِنْ","(adalah) daripada"],["ءَايَـٰتِ","(the) Tanda-tanda"],["ٱللَّهِ","(milik) Allah"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَذَّكَّرُونَ","ingat"]]],"981":["(Hai anak Adam janganlah sekali-kali kamu dapat ditipu) disesatkan (oleh setan) janganlah kamu mengikuti setan sehingga akibatnya kamu akan tertipu (sebagaimana ia telah mengeluarkan ibu-bapakmu) dengan senjata tipu-dayanya (dari surga, di mana ia menanggalkan) menjadi hal (daripada keduanya yaitu pakaian mereka berdua untuk memperlihatkan kepada keduanya aurat masing-masing. Sesungguhnya ia) yakni setan itu (dan pengikut-pengikutnya melihat kamu) yaitu bala tentaranya (dari suatu tempat yang kamu tidak bisa melihat mereka) karena kehalusan jasad mereka atau karena mereka tidak berwarna. (Sesungguhnya Kami telah menjadikan setan-setan itu pemimpin-pemimpin) artinya pendukung-pendukung dan teman-teman (bagi orang-orang yang tidak beriman).",[["يَـٰبَنِىٓ","Wahai Kanak-kanak"],["ءَادَمَ","(dari) Adam"],["لَا","(Biar) jangan"],["يَفْتِنَنَّكُمُ","menggoda kamu"],["ٱلشَّيْطَـٰنُ","Syaitan"],["كَمَآ","seperti"],["أَخْرَجَ","dia memandu keluar"],["أَبَوَيْكُم","ibu bapa kamu"],["مِّنَ","daripada"],["ٱلْجَنَّةِ","Syurga"],["يَنزِعُ","pelucutan"],["عَنْهُمَا","daripada mereka berdua"],["لِبَاسَهُمَا","pakaian mereka"],["لِيُرِيَهُمَا","untuk menunjukkan kedua-duanya"],["سَوْءَٰتِهِمَآ ۗ","keaiban mereka"],["إِنَّهُۥ","Sesungguhnya dia"],["يَرَىٰكُمْ","jumpa kamu"],["هُوَ","dia"],["وَقَبِيلُهُۥ","dan sukunya"],["مِنْ","daripada"],["حَيْثُ","di mana"],["لَا","tidak"],["تَرَوْنَهُمْ ۗ","kamu melihat mereka"],["إِنَّا","Sesungguhnya"],["جَعَلْنَا","Kami telah membuat"],["ٱلشَّيَـٰطِينَ","syaitan"],["أَوْلِيَآءَ","kawan-kawan"],["لِلَّذِينَ","daripada mereka yang"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"]]],"982":["(Dan apabila mereka melakukan perbuatan keji) seperti perbuatan syirik dan tawaf mereka di sekeliling Kakbah dalam keadaan telanjang seraya mengemukakan alasan mereka, \"Kami tidak akan melakukan tawaf dengan pakaian yang biasa kami gunakan untuk maksiat.\" Kemudian mereka dilarang dari perbuatan tersebut (mereka berkata, \"Kami mendapati nenek-moyang kami mengerjakan yang demikian itu) kami hanya mengikut kepada mereka (dan Allah menyuruh kami mengerjakannya.\") juga. (Katakanlah) kepada mereka (\"Sesungguhnya Allah tidak menyuruh mengadakan perbuatan yang keji.\" Mengapa kamu mengada-adakan terhadap Allah apa yang tidak kamu ketahui?) bahwa Allah mengatakannya; istifham atau kata tanya di sini menunjukkan makna ingkar atau sanggahan.",[["وَإِذَا","Dan apabila"],["فَعَلُوا۟","mereka lakukan"],["فَـٰحِشَةًۭ","maksiat"],["قَالُوا۟","mereka berkata"],["وَجَدْنَا","Kami jumpa"],["عَلَيْهَآ","di atasnya"],["ءَابَآءَنَا","nenek moyang kita"],["وَٱللَّهُ","dan Allah"],["أَمَرَنَا","(telah) memerintahkan kami"],["بِهَا ۗ","daripadanya"],["قُلْ","Katakanlah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يَأْمُرُ","pesanan"],["بِٱلْفَحْشَآءِ ۖ","maksiat"],["أَتَقُولُونَ","Adakah kamu berkata"],["عَلَى","tentang"],["ٱللَّهِ","Allah"],["مَا","apa"],["لَا","tidak"],["تَعْلَمُونَ","kamu tahu"]]],"983":["(Katakanlah, \"Tuhanku menyuruh menjalankan keadilan\") yaitu perbuatan yang adil. (Dan luruskanlah) diathafkan secara makna kepada lafal bil qisthi, yang artinya, Ia berkata, \"Berlaku adillah kamu dan luruskanlah dirimu.\" Atau diathafkan kepada lafal sebelumnya dengan menyimpan taqdir yakni: Hadapkanlah dirimu (mukamu) kepada Allah (di setiap salatmu) ikhlaslah kamu kepada-Nya di dalam sujudmu (dan sembahlah Allah) beribadahlah kepada-Nya (dengan mengikhlaskan ketaatan kepada-Nya) bersih dari kemusyrikan. (Sebagaimana Dia menciptakanmu pada permulaan) yang sebelumnya kamu bukanlah merupakan sesuatu (demikian pulalah akan kembali kepada-Nya) artinya Dia akan mengembalikan kamu pada hari kiamat dalam keadaan hidup kembali.",[["قُلْ","Katakanlah"],["أَمَرَ","(Telah) diperintahkan"],["رَبِّى","(oleh) Tuhanku"],["بِٱلْقِسْطِ ۖ","keadilan"],["وَأَقِيمُوا۟","dan tetapkan"],["وُجُوهَكُمْ","muka kamu"],["عِندَ","di"],["كُلِّ","setiap"],["مَسْجِدٍۢ","masjid"],["وَٱدْعُوهُ","dan memohon kepada-Nya"],["مُخْلِصِينَ","(bersifat) ikhlas"],["لَهُ","kepada-Nya"],["ٱلدِّينَ ۚ","(dalam) agama"],["كَمَا","Sebagai"],["بَدَأَكُمْ","Dia berasal dari kamu"],["تَعُودُونَ","(maka) adakah kamu akan kembali"]]],"984":["(Sebagian) dari kamu (diberi-Nya petunjuk dan sebagian lagi telah pasti kesesatan bagi mereka. Sesungguhnya mereka menjadikan setan-setan pelindung mereka selain Allah) (dan mereka mengira bahwa mereka mendapat petunjuk).",[["فَرِيقًا","Satu kumpulan"],["هَدَىٰ","Dia membimbing"],["وَفَرِيقًا","dan kumpulan"],["حَقَّ","layak"],["عَلَيْهِمُ","[pada] mereka"],["ٱلضَّلَـٰلَةُ ۗ","yang sesat"],["إِنَّهُمُ","Sesungguhnya mereka"],["ٱتَّخَذُوا۟","ambil"],["ٱلشَّيَـٰطِينَ","syaitan"],["أَوْلِيَآءَ","(sebagai) sekutu"],["مِن","daripada"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["وَيَحْسَبُونَ","sambil mereka berfikir"],["أَنَّهُم","bahawa mereka"],["مُّهْتَدُونَ","(adalah) orang-orang yang mendapat petunjuk"]]],"985":["(Hai anak Adam, pakailah pakaianmu yang indah) yaitu buat menutupi auratmu (di setiap memasuki mesjid) yaitu di kala hendak melakukan salat dan tawaf (makan dan minumlah) sesukamu (dan janganlah berlebih-lebihan. Sesungguhnya Allah tidak menyukai orang yang berlebih-lebihan).",[["۞ يَـٰبَنِىٓ","Wahai Kanak-kanak"],["ءَادَمَ","(dari) Adam"],["خُذُوا۟","ambil"],["زِينَتَكُمْ","perhiasan kamu"],["عِندَ","di"],["كُلِّ","setiap"],["مَسْجِدٍۢ","masjid"],["وَكُلُوا۟","dan makan"],["وَٱشْرَبُوا۟","dan minum"],["وَلَا","tetapi (buat) tidak"],["تُسْرِفُوٓا۟ ۚ","berlebih-lebihan"],["إِنَّهُۥ","Sesungguhnya Dia"],["لَا","tidak"],["يُحِبُّ","cinta"],["ٱلْمُسْرِفِينَ","yang boros"]]],"986":["(Katakanlah,) sebagai rasa ingkar kepada mereka (\"Siapakah yang mengharamkan perhiasan dari Allah yang telah dikeluarkan-Nya untuk hamba-hamba-Nya) yang terdiri dari pakaian (dan yang baik-baik) yakni kelezatan-kelezatan (dari rezeki?\" Katakanlah, \"Semuanya itu disediakan bagi orang-orang yang beriman dalam kehidupan dunia) yang berhak memilikinya sekalipun selain mereka turut pula memilikinya (khusus) khusus untuk mereka saja; dengan dibaca rafa` sedangkan dibaca nashab menjadi hal (di hari kiamat.\" Demikianlah Kami menjelaskan ayat-ayat itu) maksudnya Kami menerangkan hal itu sedemikian terincinya (bagi orang-orang yang mengetahui) yaitu mereka yang mau menggunakan pikirannya sebab hanya merekalah yang dapat memanfaatkannya secara baik.",[["قُلْ","Katakanlah"],["مَنْ","Siapa"],["حَرَّمَ","telah melarang"],["زِينَةَ","(the) perhiasan"],["ٱللَّهِ","(dari) Allah"],["ٱلَّتِىٓ","yang"],["أَخْرَجَ","Dia telah melahirkan"],["لِعِبَادِهِۦ","untuk hamba-Nya"],["وَٱلطَّيِّبَـٰتِ","dan perkara-perkara yang suci"],["مِنَ","daripada"],["ٱلرِّزْقِ ۚ","rezeki"],["قُلْ","Katakanlah"],["هِىَ","mereka"],["لِلَّذِينَ","(adalah) bagi mereka yang"],["ءَامَنُوا۟","beriman"],["فِى","semasa"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا","dunia"],["خَالِصَةًۭ","eksklusif (untuk mereka)"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ ۗ","(dari) Kebangkitan"],["كَذَٰلِكَ","Demikianlah"],["نُفَصِّلُ","Kami terangkan"],["ٱلْـَٔايَـٰتِ","Tanda-tanda"],["لِقَوْمٍۢ","untuk (orang ramai)."],["يَعْلَمُونَ","siapa tahu"]]],"987":["(Katakanlah, \"Tuhanku hanya mengharamkan perbuatan yang keji) yaitu dosa-dosa besar seperti perbuatan zina (baik yang tampak atau pun yang tersembunyi) yang terang-terangan atau pun yang sifatnya rahasia (dan perbuatan dosa) perbuatan maksiat (melanggar hak) orang lain (tanpa alasan yang benar) perbuatan lalim (mempersekutukan Allah dengan sesuatu yang Allah tidak menurunkan tentangnya) memusyrikkan-Nya (suatu kekuasaan pun) suatu hujah pun (dan mengharamkan mengada-adakan terhadap Allah apa yang tidak kamu ketahui.\") yaitu mengharamkan apa yang tidak diharamkan dan lain sebagainya.",[["قُلْ","Katakanlah"],["إِنَّمَا","Hanya"],["حَرَّمَ","(telah) melarang"],["رَبِّىَ","Tuhanku"],["ٱلْفَوَٰحِشَ","perbuatan yang memalukan"],["مَا","apa"],["ظَهَرَ","(adalah) jelas"],["مِنْهَا","daripadanya"],["وَمَا","dan apa"],["بَطَنَ","disembunyikan"],["وَٱلْإِثْمَ","dan dosa"],["وَٱلْبَغْىَ","dan penindasan"],["بِغَيْرِ","tanpa"],["ٱلْحَقِّ","[yang] betul"],["وَأَن","dan bahawa"],["تُشْرِكُوا۟","kamu bergaul (orang lain)"],["بِٱللَّهِ","dengan Allah"],["مَا","apa"],["لَمْ","tidak"],["يُنَزِّلْ","Dia (telah) menurunkan"],["بِهِۦ","daripadanya"],["سُلْطَـٰنًۭا","mana-mana pihak berkuasa"],["وَأَن","dan bahawa"],["تَقُولُوا۟","kamu cakap"],["عَلَى","tentang"],["ٱللَّهِ","Allah"],["مَا","apa"],["لَا","tidak"],["تَعْلَمُونَ","kamu tahu"]]],"988":["(Tiap-tiap umat mempunyai ajal) yakni masa tertentu (maka apabila telah datang ajalnya, mereka tidak dapat mengundurkannya) ajal itu (barang sesaat pun dan tidak dapat pula memajukannya) memajukan temponya.",[["وَلِكُلِّ","Dan untuk setiap"],["أُمَّةٍ","bangsa"],["أَجَلٌۭ ۖ","(adalah istilah tetap)."],["فَإِذَا","Maka apabila"],["جَآءَ","datang"],["أَجَلُهُمْ","istilah mereka"],["لَا","(mereka boleh) tidak"],["يَسْتَأْخِرُونَ","berusaha untuk menangguhkan"],["سَاعَةًۭ ۖ","sejam"],["وَلَا","dan bukan"],["يَسْتَقْدِمُونَ","berusaha untuk memajukan (itu)"]]],"989":["(Hai anak-anak Adam, jika) lafal immaa merupakan gabungan antara in syarthiah dan maa zaaidah atau tambahan (datang kepadamu rasul-rasul daripada kamu yang menceritakan kepadamu ayat-ayat-Ku, maka siapa yang bertakwa) menjauhkan diri dari kemusyrikan (dan mengadakan perbaikan) amal perbuatannya (tidaklah ada kekhawatiran terhadap mereka dan tidak pula mereka bersedih hati) di akhirat kelak.",[["يَـٰبَنِىٓ","Wahai Kanak-kanak"],["ءَادَمَ","(dari) Adam"],["إِمَّا","Jika"],["يَأْتِيَنَّكُمْ","datang kepada kamu"],["رُسُلٌۭ","Utusan"],["مِّنكُمْ","daripada kamu"],["يَقُصُّونَ","mengaitkan"],["عَلَيْكُمْ","kepada kamu"],["ءَايَـٰتِى ۙ","Ayat-ayat Aku"],["فَمَنِ","maka sesiapa"],["ٱتَّقَىٰ","takut kepada Allah"],["وَأَصْلَحَ","dan pembaharuan"],["فَلَا","maka tidak"],["خَوْفٌ","bertakwa"],["عَلَيْهِمْ","ke atas mereka"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يَحْزَنُونَ","akan bersedih"]]],"990":["(Dan orang-orang yang mendustakan ayat-ayat Kami dan menyombongkan diri) berlaku takabur (terhadapnya) sehingga mereka tidak mau percaya kepadanya (mereka itu penghuni-penghuni neraka; mereka kekal di dalamnya).",[["وَٱلَّذِينَ","Tetapi mereka yang"],["كَذَّبُوا۟","menafikan"],["بِـَٔايَـٰتِنَا","Ayat Kami"],["وَٱسْتَكْبَرُوا۟","dan (bersifat) sombong"],["عَنْهَآ","terhadap mereka"],["أُو۟لَـٰٓئِكَ","mereka"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلنَّارِ ۖ","(dari) api"],["هُمْ","mereka"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","akan kekal selama-lamanya"]]],"991":["(Maka siapakah) maksudnya tidak ada seorang pun (yang lebih lalim daripada orang yang membuat-buat dusta terhadap Allah) dengan mengatakan bahwa Allah itu mempunyai sekutu atau Ia beranak (atau mendustakan ayat-ayat-Nya?) yakni Alquran. (Orang-orang itu akan memperoleh) mereka tetap akan mendapat (bagian mereka) yakni bagian yang telah ditentukan untuknya (dalam Alkitab) yaitu apa-apa yang telah dipastikan dan tertulis untuk mereka di Lohmahfuz berupa rezeki, ajal dan lain-lainnya (sehingga bila datang kepada mereka utusan-utusan Kami) para malaikat (untuk mengambil nyawa mereka seraya mengatakan,) kepada mereka dengan nada mengejek (\"Di mana berhala-berhala yang biasa kamu sembah) sesembahan-sesembahan yang selalu kamu puja-puja (selain Allah.\" Mereka menjawab, \"Berhala-berhala itu telah lenyap) telah hilang (dari kami) sehingga kami tidak dapat melihatnya (dan mereka mengakui terhadap diri mereka) di kala menjelang ajalnya (bahwa mereka adalah orang-orang yang kafir\").",[["فَمَنْ","Kemudian siapa"],["أَظْلَمُ","(adalah) lebih zalim"],["مِمَّنِ","daripada (seorang) yang"],["ٱفْتَرَىٰ","dicipta"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["كَذِبًا","satu pembohongan"],["أَوْ","atau"],["كَذَّبَ","menafikan"],["بِـَٔايَـٰتِهِۦٓ ۚ","Ayat-ayatNya"],["أُو۟لَـٰٓئِكَ","Itu"],["يَنَالُهُمْ","akan sampai kepada mereka"],["نَصِيبُهُم","bahagian mereka"],["مِّنَ","daripada"],["ٱلْكِتَـٰبِ ۖ","Kitab"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["جَآءَتْهُمْ","datang kepada mereka"],["رُسُلُنَا","Rasul-rasul Kami (Malaikat)"],["يَتَوَفَّوْنَهُمْ","(untuk) membawa mereka dalam kematian"],["قَالُوٓا۟","mereka berkata"],["أَيْنَ","Di mana"],["مَا","mereka (yang)"],["كُنتُمْ","kamu pernah"],["تَدْعُونَ","menyeru"],["مِن","daripada"],["دُونِ","selain"],["ٱللَّهِ ۖ","Allah"],["قَالُوا۟","Mereka berkata"],["ضَلُّوا۟","Mereka sesat"],["عَنَّا","daripada kami"],["وَشَهِدُوا۟","dan mereka (akan) menjadi saksi"],["عَلَىٰٓ","terhadap"],["أَنفُسِهِمْ","diri mereka"],["أَنَّهُمْ","bahawa mereka"],["كَانُوا۟","adalah"],["كَـٰفِرِينَ","orang kafir"]]],"992":["(Allah berfirman,) Maha Tinggi Allah; Dia berfirman kepada mereka kelak di hari kiamat (\"Masuklah kamu sekalian ke dalam) golongan (umat-umat yang telah terdahulu sebelum kamu dari kalangan jin dan manusia ke dalam neraka\") Jar dan majrurnya berta'alluq pada lafal udkhuluu. (Setiap umat yang masuk) ke dalam neraka (dia mengutuk kawannya) yang sebelumnya telah menyesatkannya (sehingga apabila mereka masuk) menyusul kawan-kawannya (ke dalam neraka semuanya, berkatalah orang-orang yang masuk kemudian) mereka adalah orang-orang yang hanya mengikuti (kepada orang-orang yang masuk terdahulu) maksudnya para penghulu mereka yang menjadi panutan (\"Ya Tuhan kami, mereka telah menyesatkan kami, sebab itu datangkanlah kepada mereka siksaan yang berlipat ganda) yang berkali-kali lipat (dari neraka.\" Allah berfirman,) Maha Tinggi Allah (\"Masing-masing) dari kamu dan dari mereka (mendapat siksaan yang berlipat ganda) maksudnya azab yang berlipat ganda (akan tetapi mereka tidak mengetahui.\") dengan memakai ya dan ta; mereka tidak mengetahui siksaan apa yang diterima oleh masing-masing golongan.",[["قَالَ","Dia (akan) berkata"],["ٱدْخُلُوا۟","Masuk"],["فِىٓ","antara"],["أُمَمٍۢ","(the) negara"],["قَدْ","(siapa)"],["خَلَتْ","meninggal dunia"],["مِن","daripada"],["قَبْلِكُم","sebelum kamu"],["مِّنَ","daripada"],["ٱلْجِنِّ","jin"],["وَٱلْإِنسِ","dan lelaki"],["فِى","dalam"],["ٱلنَّارِ ۖ","neraka"],["كُلَّمَا","setiap masa"],["دَخَلَتْ","masuk"],["أُمَّةٌۭ","sebuah bangsa"],["لَّعَنَتْ","ia mengutuk"],["أُخْتَهَا ۖ","kakaknya (bangsa)"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["ٱدَّارَكُوا۟","mereka telah mengatasi satu sama lain"],["فِيهَا","di dalamnya"],["جَمِيعًۭا","semua"],["قَالَتْ","(akan) berkata"],["أُخْرَىٰهُمْ","(yang) terakhir daripada mereka"],["لِأُولَىٰهُمْ","tentang yang pertama daripada mereka"],["رَبَّنَا","Wahai Tuhan kami"],["هَـٰٓؤُلَآءِ","ini"],["أَضَلُّونَا","menyesatkan kita"],["فَـَٔاتِهِمْ","jadi berikan mereka"],["عَذَابًۭا","hukuman"],["ضِعْفًۭا","berganda"],["مِّنَ","daripada"],["ٱلنَّارِ ۖ","neraka"],["قَالَ","Dia (akan) berkata"],["لِكُلٍّۢ","Untuk setiap"],["ضِعْفٌۭ","(adalah) berganda"],["وَلَـٰكِن","[dan] tetapi"],["لَّا","tidak"],["تَعْلَمُونَ","kamu tahu"]]],"993":["(Dan berkata orang-orang yang masuk terdahulu di antara mereka kepada orang-orang yang masuk kemudian, \"Kamu tidak mempunyai kelebihan sedikit pun atas kami\") sebab kamu ikut kafir seperti kami, maka kami dan kamu adalah sama, kemudian Allah berfirman kepada mereka semua, (maka rasakanlah siksaan dari perbuatan yang telah kamu lakukan).",[["وَقَالَتْ","Dan (akan) berkata"],["أُولَىٰهُمْ","(yang) pertama daripada mereka"],["لِأُخْرَىٰهُمْ","kepada (yang) terakhir daripada mereka"],["فَمَا","Kemudian tidak"],["كَانَ","ialah"],["لَكُمْ","bagi kamu"],["عَلَيْنَا","atas kita"],["مِن","sebarang"],["فَضْلٍۢ","keunggulan"],["فَذُوقُوا۟","jadi rasa"],["ٱلْعَذَابَ","azab"],["بِمَا","bagi apa"],["كُنتُمْ","kamu pernah"],["تَكْسِبُونَ","peroleh"]]],"994":["(Sesungguhnya orang-orang yang mendustakan ayat-ayat Kami dan menyombongkan diri) mereka berlaku sombong (terhadapnya) kemudian mereka tidak mau percaya terhadapnya (sekali-kali tidak akan dibukakan bagi mereka pintu-pintu langit) yaitu apabila arwah-arwah mereka dinaikkan sesudah mati, sehingga arwah mereka turun kembali ke Sijjin atau neraka yang ada di dalam perut bumi. Berbeda dengan arwahnya orang yang beriman, pintu-pintu langit dibukakan untuknya, sehingga arwahnya dapat naik ke langit yang ke tujuh, demikianlah menurut penjelasan hadis (dan tidak pula mereka masuk surga hingga unta masuk) yakni jika ada unta yang dapat masuk (ke dalam lubang jarum) maksudnya lubang yang ada pada jarum; ini kata kiasan bahwa hal itu tidak mungkin terjadi, demikian pula masuknya mereka ke dalam surga. (Demikianlah) pembalasan itu (Kami memberi balasan kepada orang-orang yang berbuat kejahatan) oleh sebab kekafirannya.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["كَذَّبُوا۟","dinafikan"],["بِـَٔايَـٰتِنَا","Ayat Kami"],["وَٱسْتَكْبَرُوا۟","dan (bersifat) sombong"],["عَنْهَا","terhadap mereka"],["لَا","(akan) tidak"],["تُفَتَّحُ","dibuka"],["لَهُمْ","bagi mereka"],["أَبْوَٰبُ","(the) pintu"],["ٱلسَّمَآءِ","(dari) syurga"],["وَلَا","dan bukan"],["يَدْخُلُونَ","mereka akan masuk"],["ٱلْجَنَّةَ","Syurga"],["حَتَّىٰ","sehingga"],["يَلِجَ","pas"],["ٱلْجَمَلُ","unta itu"],["فِى","melalui"],["سَمِّ","(mata)."],["ٱلْخِيَاطِ ۚ","(dari) jarum"],["وَكَذَٰلِكَ","Dan dengan demikian"],["نَجْزِى","Kami membalas"],["ٱلْمُجْرِمِينَ","penjenayah"]]],"995":["(Mereka mempunyai tikar tidur dari api neraka) alas untuk tidur (dan di atas mereka ada selimut) penutup dari api neraka; ghawaasyin bentuk jamak dari kata ghaasyiyah, sedangkan tanwinnya adalah merupakan pergantian dari ya yang telah dibuang. (Demikianlah Kami memberi balasan kepada orang-orang yang zalim).",[["لَهُم","Untuk mereka"],["مِّن","daripada"],["جَهَنَّمَ","(the) Neraka"],["مِهَادٌۭ","(adalah) katil"],["وَمِن","dan daripada"],["فَوْقِهِمْ","atas mereka"],["غَوَاشٍۢ ۚ","penutup"],["وَكَذَٰلِكَ","Dan dengan demikian"],["نَجْزِى","Kami membalas"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"996":["(Orang-orang yang beriman dan mengerjakan amal-amal saleh) menjadi mubtada, sedangkan firman Allah swt. (Kami tidak memikulkan kewajiban kepada diri seseorang melainkan sekedar kesanggupannya) sesuai kemampuannya dalam beramal; ini adalah jumlah mu'taridhah antara mubtada dan khabarnya, sedangkan khabarnya ialah (mereka itulah penghuni-penghuni surga, mereka kekal di dalamnya).",[["وَٱلَّذِينَ","Tetapi mereka yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","[yang] amal soleh"],["لَا","tidak"],["نُكَلِّفُ","Kita bebankan"],["نَفْسًا","mana-mana jiwa"],["إِلَّا","kecuali"],["وُسْعَهَآ","(kepada) kapasitinya"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلْجَنَّةِ ۖ","(dari) Syurga"],["هُمْ","mereka"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","(akan) kekal selama-lamanya"]]],"997":["(Dan Kami cabut segala macam dendam yang berada di dalam dada mereka) perasaan dengki yang pernah ada sewaktu mereka hidup di alam dunia (mengalir di bawah mereka) di bawah gedung-gedung tempat tinggal mereka (sungai-sungai dan mereka berkata,) tatkala mereka mulai menetap di tempat tinggal masing-masing (\"Segala puji bagi Allah yang telah menunjuki kami kepada surga ini) yakni amal perbuatan yang balasannya adalah hal ini (Dan kami sekali-kali tidak akan mendapat petunjuk kalau Allah tidak memberi kami petunjuk) di sini membuang jawabnya laula, hal itu bisa diketahui karena ada tanda sebelumnya yang menunjukkan kepadanya. (Sesungguhnya telah datang rasul-rasul Tuhan kami, membawa kebenaran.\" Dan diserukan kepada mereka bahwasanya) dengan anna yang ditakhfifkan, yakni annahuu. Atau dapat juga berasal dari an mufassirah (itulah surga yang diwariskan kepadamu, disebabkan apa yang dahulu kamu kerjakan).",[["وَنَزَعْنَا","Dan Kami akan hapuskan"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["صُدُورِهِم","buah dada mereka"],["مِّنْ","daripada"],["غِلٍّۢ","niat jahat"],["تَجْرِى","mengalir"],["مِن","daripada"],["تَحْتِهِمُ","di bawah mereka"],["ٱلْأَنْهَـٰرُ ۖ","sungai-sungai"],["وَقَالُوا۟","Dan mereka akan berkata"],["ٱلْحَمْدُ","Segala pujian"],["لِلَّهِ","(adalah) untuk Allah"],["ٱلَّذِى","yang Esa"],["هَدَىٰنَا","membimbing kami"],["لِهَـٰذَا","kepada ini"],["وَمَا","dan bukan"],["كُنَّا","kami"],["لِنَهْتَدِىَ","untuk mendapat bimbingan"],["لَوْلَآ","jika tidak"],["أَنْ","[bahawa]"],["هَدَىٰنَا","(telah) membimbing kami"],["ٱللَّهُ ۖ","Allah"],["لَقَدْ","Sungguh"],["جَآءَتْ","datang"],["رُسُلُ","Utusan"],["رَبِّنَا","(dari) Tuhan kami"],["بِٱلْحَقِّ ۖ","dengan kebenaran"],["وَنُودُوٓا۟","Dan mereka akan ditangani"],["أَن","[bahawa]"],["تِلْكُمُ","Ini"],["ٱلْجَنَّةُ","(ialah) Syurga"],["أُورِثْتُمُوهَا","kamu telah dijadikan untuk mewarisinya"],["بِمَا","bagi apa"],["كُنتُمْ","kamu pernah"],["تَعْمَلُونَ","lakukan"]]],"998":["(Dan penghuni-penghuni surga berseru kepada penghuni-penghuni neraka,) sebagai pernyataan dan ejekan (\"Sesungguhnya kami telah memperoleh apa yang telah Tuhan kami menjanjikannya kepada kami) berupa pahala (dengan sebenarnya. Maka apakah kamu telah memperoleh apa yang telah dijanjikan) kepadamu (oleh Tuhanmu) berupa azab (dengan sebenarnya?\" Mereka, penduduk neraka, menjawab, \"Betul.\" Kemudian seorang penyeru, malaikat, mengumumkan) menyerukan pengumuman (di antara mereka) yaitu di antara kedua golongan itu. Malaikat itu mengumandangkan kepada mereka (\"Kutukan Allah ditimpakan kepada orang-orang yang lalim).",[["وَنَادَىٰٓ","Dan akan memanggil"],["أَصْحَـٰبُ","(para) sahabat"],["ٱلْجَنَّةِ","(dari) Syurga"],["أَصْحَـٰبَ","(kepada) para sahabat"],["ٱلنَّارِ","(dari) api"],["أَن","bahawa"],["قَدْ","Sesungguhnya"],["وَجَدْنَا","kami jumpa"],["مَا","apa"],["وَعَدَنَا","(telah) berjanji kepada kami"],["رَبُّنَا","Tuhan kami"],["حَقًّۭا","benar"],["فَهَلْ","Jadi mempunyai"],["وَجَدتُّم","kamu jumpa"],["مَّا","apa"],["وَعَدَ","(telah) dijanjikan"],["رَبُّكُمْ","(oleh) Tuhanmu"],["حَقًّۭا ۖ","(menjadi) benar"],["قَالُوا۟","Mereka akan berkata"],["نَعَمْ ۚ","ya"],["فَأَذَّنَ","Kemudian akan mengumumkan"],["مُؤَذِّنٌۢ","seorang juruhebah"],["بَيْنَهُمْ","antara mereka"],["أَن","[bahawa]"],["لَّعْنَةُ","(The) sumpahan"],["ٱللَّهِ","(milik) Allah"],["عَلَى","(berada) di atas"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"999":["(Yaitu orang-orang yang menghalangi) manusia (dari jalan Allah) dari tuntunan agama-Nya (dan menginginkan agar jalan itu) maksudnya mereka menghendaki agar jalan Allah itu (bengkok) tidak lurus (dan mereka ingkar terhadap kehidupan akhirat).",[["ٱلَّذِينَ","Orang yang"],["يَصُدُّونَ","menghalang"],["عَن","daripada"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["وَيَبْغُونَهَا","dan carilah di dalamnya"],["عِوَجًۭا","kebengkokan"],["وَهُم","sedangkan mereka (ada)"],["بِٱلْـَٔاخِرَةِ","tentang akhirat"],["كَـٰفِرُونَ","orang kafir"]]],"1000":["(Dan di antara keduanya) yaitu antara para penghuni surga dan para penghuni neraka (ada batas) penghalang; menurut suatu pendapat batas itu berupa tembok vang diberi nama Al-A'raaf (di atas Al-A`raaf itu) yakni nama tembok surga (ada orang-orang) yang amat tampan dan amat buruk rupanya, rupa mereka sama, artinya yang cantik sama cantiknya dan yang buruk sama pula buruknya, sebagaimana yang dijelaskan oleh hadis (yang mengenal masing-masing dari kedua golongan itu) penduduk surga dan neraka (dengan tanda-tanda mereka) ciri-ciri khas mereka, yakni berbadan putih bagi orang-orang yang beriman dan berbadan hitam bagi orang-orang kafir, oleh sebab orang-orang yang di atas Al-A`raaf itu dapat langsung melihat kedua golongan itu mengingat mereka berada di tempat yang tinggi. (Dan mereka menyeru penduduk surga, 'Mudah-mudahan Allah melimpahkan kesejahteraan atas kamu.') Allah swt. berfirman, ('Mereka belum lagi memasukinya) yakni para penghuni Al-A'raaf itu ke surga (sedangkan mereka ingin segera')\" memasukinya. Hasan mengatakan, \"Mereka tidak terdorong oleh rasa keinginan yang sangat melainkan karena memang Allah telah menghendakinya untuk mereka.\" Dan Imam Hakim telah meriwayatkan dari Hudzaifah yang telah mengatakan, \"Tatkala calon penghuni surga itu dalam keadaan demikian berada di Al-A'raaf, kemudian Tuhanmu muncul di hadapan mereka seraya berfirman, 'Masuklah kamu sekalian ke dalam surga, sesungguhnya Aku telah mengampuni kamu.'\"",[["وَبَيْنَهُمَا","Dan antara mereka"],["حِجَابٌۭ ۚ","(akan menjadi) partition"],["وَعَلَى","dan seterusnya"],["ٱلْأَعْرَافِ","ketinggian"],["رِجَالٌۭ","(akan) lelaki"],["يَعْرِفُونَ","mengiktiraf"],["كُلًّۢا","semua"],["بِسِيمَىٰهُمْ ۚ","dengan markah mereka"],["وَنَادَوْا۟","Dan mereka akan memanggil"],["أَصْحَـٰبَ","(kepada) para sahabat"],["ٱلْجَنَّةِ","(dari) Syurga"],["أَن","bahawa"],["سَلَـٰمٌ","Damai"],["عَلَيْكُمْ ۚ","(berada) atas kamu"],["لَمْ","Tidak"],["يَدْخُلُوهَا","mereka telah memasukinya"],["وَهُمْ","tetapi mereka"],["يَطْمَعُونَ","harapan"]]],"1001":["(Dan apabila pandangan mereka dialihkan) yakni Ashhaabul A`raaf itu (ke arah) ke sebelah (penghuni neraka, mereka berkata, \"Ya Tuhan kami! Janganlah Engkau tempatkan kami) di dalam neraka (bersama-sama orang-orang yang lalim itu\").",[["۞ وَإِذَا","Dan apabila"],["صُرِفَتْ","dipusingkan"],["أَبْصَـٰرُهُمْ","mata mereka"],["تِلْقَآءَ","ke arah"],["أَصْحَـٰبِ","(para) sahabat"],["ٱلنَّارِ","(dari) api"],["قَالُوا۟","mereka (akan) berkata"],["رَبَّنَا","Wahai Tuhan kami"],["لَا","Jangan"],["تَجْعَلْنَا","letak kita"],["مَعَ","dengan"],["ٱلْقَوْمِ","rakyat"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"1002":["(Dan orang-orang yang di atas Al-A`raaf memanggil beberapa orang pemuka-pemuka) penduduk neraka (yang mereka mengenalnya dengan tanda-tandanya dengan mengatakan, \"Tidaklah memberi manfaat kepadamu) dapat menyelamatkanmu dari neraka (apa yang kamu kumpulkan) yakni harta benda atau banyaknya bilangan kamu (dan apa yang selalu kamu sombongkan itu.\") yaitu kepongahanmu tidak mau beriman, kemudian orang-orang yang di atas Al-A`raaf bertanya kepada penghuni neraka seraya memberi isyarat kepada orang-orang Islam yang lemah.",[["وَنَادَىٰٓ","Dan (akan) menyeru"],["أَصْحَـٰبُ","(para) sahabat"],["ٱلْأَعْرَافِ","(dari) ketinggian"],["رِجَالًۭا","(kepada) lelaki"],["يَعْرِفُونَهُم","yang mereka kenali"],["بِسِيمَىٰهُمْ","dengan markah mereka"],["قَالُوا۟","berkata"],["مَآ","Tidak"],["أَغْنَىٰ","(telah) mendapat manfaat"],["عَنكُمْ","[kepada] kamu"],["جَمْعُكُمْ","perhimpunan kamu"],["وَمَا","dan apa"],["كُنتُمْ","kamu dahulu"],["تَسْتَكْبِرُونَ","sombong (tentang)"]]],"1003":["(\"Itukah orang-orang yang telah kamu bersumpah bahwa mereka tidak akan mendapat rahmat Allah?\") akan tetapi telah dikatakan kepada orang-orang Islam yang lemah itu (\"Masuklah ke dalam surga, tidak ada kekhawatiran terhadapmu dan tidak pula kamu bersedih hati\") menurut suatu qiraat dibaca dengan bina maf'ul yakni udkhiluu dan dukhiluu, jumlah nafi menjadi hal yakni perkataan tersebut ditujukan kepada mereka.",[["أَهَـٰٓؤُلَآءِ","Adakah ini"],["ٱلَّذِينَ","mereka yang"],["أَقْسَمْتُمْ","kamu telah bersumpah"],["لَا","(itu) tidak"],["يَنَالُهُمُ","(akan) memberi mereka"],["ٱللَّهُ","Allah"],["بِرَحْمَةٍ ۚ","belas kasihan"],["ٱدْخُلُوا۟","Masuk"],["ٱلْجَنَّةَ","Syurga"],["لَا","(Akan ada) tidak"],["خَوْفٌ","bertakwa"],["عَلَيْكُمْ","ke atas kamu"],["وَلَآ","dan bukan"],["أَنتُمْ","kamu"],["تَحْزَنُونَ","akan bersedih"]]],"1004":["(Dan penghuni neraka menyeru kepada penghuni surga, \"Limpahkanlah kepada kami sedikit air atau apa yang telah direzekikan Allah kepadamu.\") yaitu makanan (Mereka, para penghuni surga, menjawab, \"Sesungguhnya Allah telah mengharamkan keduanya) telah melarang makanan dan minuman itu (atas orang-orang kafir).",[["وَنَادَىٰٓ","Dan (akan) menyeru"],["أَصْحَـٰبُ","(para) sahabat"],["ٱلنَّارِ","(dari) api"],["أَصْحَـٰبَ","(kepada) para sahabat"],["ٱلْجَنَّةِ","(dari) Syurga"],["أَنْ","[bahawa]"],["أَفِيضُوا۟","tuang"],["عَلَيْنَا","atas kita"],["مِنَ","[daripada]"],["ٱلْمَآءِ","(beberapa) air"],["أَوْ","atau"],["مِمَّا","tentang apa"],["رَزَقَكُمُ","(telah) disediakan (kepada) kamu"],["ٱللَّهُ ۚ","(oleh) Allah"],["قَالُوٓا۟","Mereka (akan) berkata"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["حَرَّمَهُمَا","telah mengharamkan keduanya"],["عَلَى","kepada"],["ٱلْكَـٰفِرِينَ","orang kafir"]]],"1005":["(Yaitu orang-orang yang menjadikan agama mereka sebagai main-mainan dan senda-gurau, dan kehidupan dunia telah menipu mereka.\" Maka pada hari ini, hari kiamat, Kami melupakan mereka) Kami membiarkan mereka di dalam neraka (sebagaimana mereka melupakan pertemuan mereka dengan hari ini) di mana mereka mengabaikan beramal baik untuk menghadapinya (dan sebagaimana mereka selalu mengingkari ayat-ayat Kami) sebagaimana mereka telah berlaku ingkar terhadapnya.",[["ٱلَّذِينَ","Orang yang"],["ٱتَّخَذُوا۟","mengambil"],["دِينَهُمْ","agama mereka"],["لَهْوًۭا","(sebagai) satu hiburan"],["وَلَعِبًۭا","dan bermain"],["وَغَرَّتْهُمُ","dan menipu mereka"],["ٱلْحَيَوٰةُ","kehidupan"],["ٱلدُّنْيَا ۚ","dunia"],["فَٱلْيَوْمَ","Jadi hari ini"],["نَنسَىٰهُمْ","Kita lupakan mereka"],["كَمَا","seperti"],["نَسُوا۟","mereka lupa"],["لِقَآءَ","(the) mesyuarat"],["يَوْمِهِمْ","(pada) hari mereka"],["هَـٰذَا","ini"],["وَمَا","dan [apa]"],["كَانُوا۟","(sebagaimana) mereka dahulu"],["بِـَٔايَـٰتِنَا","dengan Ayat-ayat Kami"],["يَجْحَدُونَ","mereka menolak"]]],"1006":["(Dan sesungguhnya Kami telah mendatangkan kepada mereka) para penduduk Mekah (sebuah Kitab) yakni Alquran (yang Kami telah menjelaskannya) telah Kami terangkan melalui berita-beritanya, janji-janjinya dan ancaman-ancamannya (atas dasar pengetahuan Kami) menjadi hal, yakni Kami mengetahui tentang apa yang terincikan di dalamnya (menjadi petunjuk) menjadi hal bagi dhamir ha (dan rahmat bagi orang-orang yang beriman) kepadanya.",[["وَلَقَدْ","Dan sungguh"],["جِئْنَـٰهُم","Kami telah membawa mereka"],["بِكِتَـٰبٍۢ","sebuah Buku"],["فَصَّلْنَـٰهُ","yang telah Kami jelaskan"],["عَلَىٰ","dengan"],["عِلْمٍ","pengetahuan"],["هُدًۭى","sebagai panduan"],["وَرَحْمَةًۭ","dan belas kasihan"],["لِّقَوْمٍۢ","bagi kaum"],["يُؤْمِنُونَ","yang beriman"]]],"1007":["(Tiadalah mereka menunggu-nunggu) mereka tidak menunggu (kecuali terlaksananya kebenaran Alquran itu) akibat dari apa yang ada di dalamnya. (Pada hari datangnya kebenaran pemberitaan Alquran itu) yaitu hari kiamat (berkatalah orang-orang yang melupakannya sebelum itu,) mereka tidak mau beriman kepada Alquran (\"Sesungguhnya telah datang rasul-rasul Tuhan kami membawa yang hak, maka adakah bagi kami pemberi syafaat yang akan memberi syafaat kepada kami atau) dapatkah (kami dikembalikan) ke dunia (sehingga dapat beramal yang lain dari yang pernah kami amalkan?\") kami akan mentauhidkan Allah dan meninggalkan kemusyrikan. Kemudian dikatakan kepada mereka, \"Tidak dapat.\" Allah swt. berfirman, (Sungguh mereka telah merugikan diri mereka sendiri) sebab mereka menjadi binasa (dan lenyaplah) maksudnya hilanglah (dari mereka tuhan-tuhan yang mereka ada-adakan) sebagai sekutu Allah yang mereka buat-buat sendiri.",[["هَلْ","buat"],["يَنظُرُونَ","mereka menunggu"],["إِلَّا","kecuali"],["تَأْوِيلَهُۥ ۚ","(untuk) pemenuhannya"],["يَوْمَ","(The) Hari"],["يَأْتِى","(akan) datang"],["تَأْوِيلُهُۥ","pemenuhannya"],["يَقُولُ","akan berkata"],["ٱلَّذِينَ","orang yang"],["نَسُوهُ","telah melupakannya"],["مِن","daripada"],["قَبْلُ","sebelum"],["قَدْ","Sesungguhnya"],["جَآءَتْ","telah datang"],["رُسُلُ","(para) Rasul"],["رَبِّنَا","(dari) Tuhan kami"],["بِٱلْحَقِّ","dengan kebenaran"],["فَهَل","begitu juga (ada)"],["لَّنَا","bagi kami"],["مِن","sebarang"],["شُفَعَآءَ","pemberi syafaat"],["فَيَشْفَعُوا۟","supaya mereka memberi syafaat"],["لَنَآ","bagi kami"],["أَوْ","atau"],["نُرَدُّ","kami dihantar balik"],["فَنَعْمَلَ","supaya (agar) kami melakukan (perbuatan)"],["غَيْرَ","selain daripada"],["ٱلَّذِى","itu yang"],["كُنَّا","kita dulu"],["نَعْمَلُ ۚ","lakukan"],["قَدْ","Sesungguhnya"],["خَسِرُوٓا۟","mereka kalah"],["أَنفُسَهُمْ","diri mereka"],["وَضَلَّ","dan sesat"],["عَنْهُم","daripada mereka"],["مَّا","apa"],["كَانُوا۟","mereka dahulu"],["يَفْتَرُونَ","mencipta"]]],"1008":["(Sesungguhnya Tuhan kamu ialah Allah yang telah menciptakan langit dan bumi dalam enam masa) menurut ukuran hari dunia atau yang sepadan dengannya, sebab pada zaman itu masih belum ada matahari. Akan tetapi jika Allah menghendakinya niscaya Ia dapat menciptakannya dalam sekejap mata, adapun penyebutan hal ini dimaksud guna mengajari makhluk-Nya agar tekun dan sabar dalam mengerjakan sesuatu (lalu Dia bersemayam di atas Arsy) Arsy menurut istilah bahasa artinya singgasana raja, yang dimaksud dengan bersemayam ialah yang sesuai dengan kebesaran Allah dan kesucian-Nya (Dia menutupkan malam kepada siang) bisa dibaca takhfif yakni yughsyii dan dibaca tasydid, yakni yughasysyii, artinya: keduanya itu saling menutupi yang lain silih-berganti (yang mengikutinya) masing-masing di antara keduanya itu mengikuti yang lainnya (dengan cepat) secara cepat (dan diciptakan-Nya pula matahari, bulan dan bintang-bintang) dengan dibaca nashab diathafkan kepada as-samaawaat, dan dibaca rafa` sebagai mubtada sedangkan khabarnya ialah (masing-masing tunduk) patuh (kepada perintah-Nya) kepada kekuasaan-Nya (ingatlah, menciptakan itu hanya hak Allah) semuanya (dan memerintah) kesemuanya adalah hak-Nya pula (Maha Suci) Maha Besar (Allah, Tuhan) Pemelihara (semesta alam).",[["إِنَّ","Sesungguhnya"],["رَبَّكُمُ","Tuhanmu"],["ٱللَّهُ","(ialah) Allah"],["ٱلَّذِى","yang Esa"],["خَلَقَ","dicipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["فِى","dalam"],["سِتَّةِ","enam"],["أَيَّامٍۢ","zaman"],["ثُمَّ","kemudian"],["ٱسْتَوَىٰ","Dia naik"],["عَلَى","pada"],["ٱلْعَرْشِ","takhta"],["يُغْشِى","Dia meliputi"],["ٱلَّيْلَ","malam"],["ٱلنَّهَارَ","(dengan) hari itu"],["يَطْلُبُهُۥ","mencarinya"],["حَثِيثًۭا","dengan pantas"],["وَٱلشَّمْسَ","dan matahari"],["وَٱلْقَمَرَ","dan bulan"],["وَٱلنُّجُومَ","dan bintang"],["مُسَخَّرَٰتٍۭ","tertakluk"],["بِأَمْرِهِۦٓ ۗ","dengan perintahNya"],["أَلَا","Tidak dinafikan"],["لَهُ","untuk Dia"],["ٱلْخَلْقُ","(ialah) penciptaan"],["وَٱلْأَمْرُ ۗ","dan perintah"],["تَبَارَكَ","diberkati"],["ٱللَّهُ","(ialah) Allah"],["رَبُّ","Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"1009":["(Berdoalah kepada Tuhanmu dengan berendah diri) menjadi hal, yakni merendahkan diri (dan dengan suara yang lembut) secara berbisik-bisik (Sesungguhnya Allah tidak menyukai orang-orang yang melampaui batas) di dalam berdoa. Seperti banyak berbicara dengan suara yang keras.",[["ٱدْعُوا۟","Seruan"],["رَبَّكُمْ","Tuhanmu"],["تَضَرُّعًۭا","dengan rendah hati"],["وَخُفْيَةً ۚ","dan secara persendirian"],["إِنَّهُۥ","Sesungguhnya Dia"],["لَا","tidak"],["يُحِبُّ","cinta"],["ٱلْمُعْتَدِينَ","orang yang melampaui batas"]]],"1010":["(Dan janganlah kamu membuat kerusakan di muka bumi) dengan melakukan kemusyrikan dan perbuatan-perbuatan maksiat (sesudah Allah memperbaikinya) dengan cara mengutus rasul-rasul (dan berdoalah kepada-Nya dengan rasa takut) terhadap siksaan-Nya (dan dengan penuh harap) terhadap rahmat-Nya. (Sesungguhnya rahmat Allah amat dekat kepada orang-orang yang berbuat baik) yakni orang-orang yang taat. Lafal qariib berbentuk mudzakkar padahal menjadi khabar lafal rahmah yang muannats, hal ini karena lafal rahmah dimudhafkan kepada lafal Allah.",[["وَلَا","Dan jangan"],["تُفْسِدُوا۟","menyebabkan rasuah"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["بَعْدَ","selepas"],["إِصْلَـٰحِهَا","reformasinya"],["وَٱدْعُوهُ","Dan panggil Dia"],["خَوْفًۭا","(dalam) ketakutan"],["وَطَمَعًا ۚ","dan harapan"],["إِنَّ","Sesungguhnya"],["رَحْمَتَ","(the) Rahmat"],["ٱللَّهِ","(milik) Allah"],["قَرِيبٌۭ","(ada) dekat"],["مِّنَ","bagi"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"1011":["(Dan Dialah yang meniupkan angin sebagai pembawa berita gembira sebelum kedatangan rahmat-Nya) yakni terpencar-pencar sebelum datangnya hujan. Menurut suatu qiraat dibaca dengan takhfif, yaitu syin disukunkan; dan menurut qiraat lainnya dengan disukunkan syinnya kemudian memakai nun yang difatahkan sebagai mashdar. Menurut qiraat lainnya lagi dengan disukunkan syinnya kemudian didamahkan huruf sebelumnya sebagai pengganti dari nun, yakni mubsyiran. Bentuk tunggal (dari yang pertama ialah nusyuurun seperti lafal rasuulun, sedangkan bentuk tunggal yang kedua ialah basyiirun (sehingga apabila angin itu membawa) maksudnya meniupkan (mendung yang tebal) yaitu hujan (Kami halau mendung itu) mega yang mengandung air hujan itu. Di dalam lafal ini terkandung makna iltifat `anil ghaibiyyah (ke suatu daerah yang tandus) daerah yang tidak ada tetumbuhannya guna menyuburkannya (lalu Kami turunkan di daerah itu) di kawasan tersebut (hujan, maka Kami keluarkan dengan sebab hujan itu berbagai macam buah-buahan. Seperti itulah) cara pengeluaran itulah (Kami membangkitkan orang-orang yang telah mati) dari kuburan mereka dengan menghidupkan mereka kembali (mudah-mudahan kamu mengambil pelajaran) kemudian kamu mau beriman.",[["وَهُوَ","Dan Dia"],["ٱلَّذِى","(ialah) Yang"],["يُرْسِلُ","menghantar"],["ٱلرِّيَـٰحَ","angin"],["بُشْرًۢا","(sebagai) berita gembira"],["بَيْنَ","daripada"],["يَدَىْ","sebelum"],["رَحْمَتِهِۦ ۖ","KerahimanNya"],["حَتَّىٰٓ","sehingga"],["إِذَآ","apabila"],["أَقَلَّتْ","mereka telah membawa"],["سَحَابًۭا","awan"],["ثِقَالًۭا","berat"],["سُقْنَـٰهُ","Kami memandu mereka"],["لِبَلَدٍۢ","ke sebuah tanah"],["مَّيِّتٍۢ","mati"],["فَأَنزَلْنَا","kemudian Kami turunkan"],["بِهِ","daripadanya"],["ٱلْمَآءَ","air itu"],["فَأَخْرَجْنَا","kemudian Kami lahirkan"],["بِهِۦ","daripadanya"],["مِن","(daripada)"],["كُلِّ","semua (jenis)"],["ٱلثَّمَرَٰتِ ۚ","(dari) buah-buahan"],["كَذَٰلِكَ","Demikianlah"],["نُخْرِجُ","Kami akan melahirkan"],["ٱلْمَوْتَىٰ","yang mati"],["لَعَلَّكُمْ","supaya kamu"],["تَذَكَّرُونَ","ambil iktibar"]]],"1012":["(Dan tanah yang baik) yang subur tanahnya (tanaman-tanamannya tumbuh subur) tumbuh dengan baik (dengan seizin Tuhannya) hal ini merupakan perumpamaan bagi orang mukmin yang mau mendengar petuah/nasihat kemudian ia mengambil manfaat dari nasihat itu (dan tanah yang tidak subur) jelek tanahnya (tidaklah mengeluarkan) tanamannya (kecuali tumbuh merana) sulit dan susah tumbuhnya. Hal ini merupakan perumpamaan bagi orang yang kafir. (Demikianlah) seperti apa yang telah Kami jelaskan (Kami menjelaskan) menerangkan (ayat-ayat Kami kepada orang-orang yang bersyukur) terhadap Allah, kemudian mereka mau beriman kepada-Nya.",[["وَٱلْبَلَدُ","Dan tanah"],["ٱلطَّيِّبُ","[yang] suci"],["يَخْرُجُ","keluar"],["نَبَاتُهُۥ","tumbuh-tumbuhannya"],["بِإِذْنِ","dengan izin (yang)"],["رَبِّهِۦ ۖ","(dari) Tuhannya"],["وَٱلَّذِى","tetapi yang mana"],["خَبُثَ","adalah buruk"],["لَا","tidak"],["يَخْرُجُ","keluar"],["إِلَّا","kecuali"],["نَكِدًۭا ۚ","(dengan) kesukaran"],["كَذَٰلِكَ","Demikianlah"],["نُصَرِّفُ","Kami terangkan"],["ٱلْـَٔايَـٰتِ","Tanda-tanda"],["لِقَوْمٍۢ","bagi kaum"],["يَشْكُرُونَ","yang bersyukur"]]],"1013":["(Sesungguhnya) merupakan jawab dari qasam/sumpah yang mahdzuf/tidak disebutkan. (Kami telah mengutus Nuh kepada kaumnya lalu ia berkata, \"Wahai kaumku, sembahlah Allah, sekali-kali tak ada Tuhan bagimu selain-Nya.\") dengan dibaca jar sebagai sifat dari lafal ilaahun, dan dibaca rafa' sebagai badal dari lafal ilaahun (Sesungguhnya aku takut kamu) jika kamu menyembah selain Allah (akan ditimpa azab yang besar) yakni azab pada hari kiamat.",[["لَقَدْ","Sungguh"],["أَرْسَلْنَا","Kami utus"],["نُوحًا","Nuh"],["إِلَىٰ","kepada"],["قَوْمِهِۦ","umatnya"],["فَقَالَ","dan dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["ٱعْبُدُوا۟","Ibadah"],["ٱللَّهَ","Allah"],["مَا","tidak"],["لَكُم","bagi kamu"],["مِّنْ","sebarang"],["إِلَـٰهٍ","tuhan"],["غَيْرُهُۥٓ","selain Dia"],["إِنِّىٓ","Sesungguhnya aku"],["أَخَافُ","[Aku] takut"],["عَلَيْكُمْ","bagi kamu"],["عَذَابَ","hukuman"],["يَوْمٍ","hari"],["عَظِيمٍۢ","Hebat"]]],"1014":["(Pemuka-pemuka) orang-orang terhormat (dari kaumnya berkata, \"Sesungguhnya kami memandang kamu berada dalam kesesatan yang nyata.\") yang jelas.",[["قَالَ","Berkata"],["ٱلْمَلَأُ","ketua-ketua"],["مِن","daripada"],["قَوْمِهِۦٓ","umatnya"],["إِنَّا","Sesungguhnya kami"],["لَنَرَىٰكَ","pasti jumpa"],["فِى","dalam"],["ضَلَـٰلٍۢ","ralat"],["مُّبِينٍۢ","yang nyata"]]],"1015":["(Nuh menjawab, \"Hai kaumku, tak ada padaku kesesatan sedikit pun) lafal dhalaalah lebih umum pengertiannya daripada lafal adh-dhalaal dengan demikian maka penolakannya pun lebih kuat (tetapi aku adalah utusan dari Tuhan semesta alam.\")",[["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["لَيْسَ","tidak ada"],["بِى","dalam diri aku"],["ضَلَـٰلَةٌۭ","ralat"],["وَلَـٰكِنِّى","tetapi aku"],["رَسُولٌۭ","seorang Rasul"],["مِّن","daripada"],["رَّبِّ","(yang) Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"1016":["(\"Aku sampaikan kepadamu) dengan dibaca takhfif dan tasydid (amanat-amanat Tuhanku dan aku memberi nasihat) maksudnya, aku menghendaki kebaikan (kepadamu, dan aku mengetahui dari Allah apa yang tidak kamu ketahui.\")",[["أُبَلِّغُكُمْ","Aku sampaikan kepada kamu"],["رِسَـٰلَـٰتِ","Mesej"],["رَبِّى","(dari) Tuhanku"],["وَأَنصَحُ","dan [aku] menasihati"],["لَكُمْ","[kepada] kamu"],["وَأَعْلَمُ","dan aku tahu"],["مِنَ","daripada"],["ٱللَّهِ","Allah"],["مَا","apa"],["لَا","tidak"],["تَعْلَمُونَ","kamu tahu"]]],"1017":["(Apakah) kamu tidak percaya (dan heran bahwa datang kepada kamu peringatan) yakni pelajaran (dari Tuhanmu dengan perantaraan) lisan (seorang laki-laki dari golonganmu agar dia memberi peringatan kepadamu) tentang siksaan jika kamu tidak mau beriman (dan mudah-mudahan kamu bertakwa) kepada Allah (dan supaya kamu mendapat rahmat?) oleh sebab pelajaran itu.",[["أَوَعَجِبْتُمْ","Adakah kamu tertanya-tanya"],["أَن","bahawa"],["جَآءَكُمْ","telah datang kepada kamu"],["ذِكْرٌۭ","peringatan"],["مِّن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["عَلَىٰ","pada"],["رَجُلٍۢ","seorang lelaki"],["مِّنكُمْ","antara kamu"],["لِيُنذِرَكُمْ","supaya dia memberi amaran kepada kamu"],["وَلِتَتَّقُوا۟","dan supaya kamu takut"],["وَلَعَلَّكُمْ","dan supaya kamu boleh"],["تُرْحَمُونَ","mendapat rahmat"]]],"1018":["(Maka mereka mendustakan Nuh, kemudian Kami selamatkan dia dan orang-orang yang bersamanya) dari tenggelam (di dalam bahtera) perahu (dan Kami tenggelamkan orang-orang yang mendustakan ayat-ayat Kami) dengan banjir besar. (Sesungguhnya mereka adalah kaum yang buta) mata hatinya dari kebenaran.",[["فَكَذَّبُوهُ","Tetapi mereka menafikannya"],["فَأَنجَيْنَـٰهُ","maka Kami selamatkan dia"],["وَٱلَّذِينَ","dan orang yang"],["مَعَهُۥ","(ada) bersamanya"],["فِى","dalam"],["ٱلْفُلْكِ","kapal itu"],["وَأَغْرَقْنَا","Dan Kami tenggelam"],["ٱلَّذِينَ","orang yang"],["كَذَّبُوا۟","dinafikan"],["بِـَٔايَـٰتِنَآ ۚ","Ayat Kami"],["إِنَّهُمْ","Sesungguhnya mereka"],["كَانُوا۟","adalah"],["قَوْمًا","suatu kaum"],["عَمِينَ","buta"]]],"1019":["(Dan) Kami telah mengutus (kepada kaum Ad) yang pertama (saudara mereka yaitu Hud. Ia berkata, \"Hai kaumku, sembahlah Allah) tauhidkanlah Allah (sekali-kali tidak ada Tuhan bagimu selain dari-Nya. Maka mengapa kamu tidak bertakwa?\") kamu tidak takut kepada-Nya sehingga kamu mau mengimani-Nya.",[["۞ وَإِلَىٰ","Dan kepada"],["عَادٍ","Aad"],["أَخَاهُمْ","(Kami hantar) saudara mereka"],["هُودًۭا ۗ","Hud"],["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["ٱعْبُدُوا۟","Ibadah"],["ٱللَّهَ","Allah"],["مَا","tidak"],["لَكُم","bagi kamu"],["مِّنْ","sebarang"],["إِلَـٰهٍ","tuhan"],["غَيْرُهُۥٓ ۚ","selain Dia"],["أَفَلَا","Kemudian tidak akan"],["تَتَّقُونَ","kamu takut (Allah)"]]],"1020":["(Pemuka-pemuka yang kafir dari kaumnya berkata, \"Sesungguhnya kami benar-benar memandang kamu dalam keadaan kurang akal) yaitu bodoh (dan sesungguhnya kami menganggap kamu termasuk orang-orang yang berdusta.\") di dalam kerasulanmu.",[["قَالَ","Berkata"],["ٱلْمَلَأُ","ketua-ketua"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["مِن","daripada"],["قَوْمِهِۦٓ","umatnya"],["إِنَّا","Sesungguhnya kami"],["لَنَرَىٰكَ","pasti, jumpa lagi"],["فِى","dalam"],["سَفَاهَةٍۢ","kebodohan"],["وَإِنَّا","dan sesungguhnya, kita"],["لَنَظُنُّكَ","[kami] fikir kamu"],["مِنَ","(adalah) daripada"],["ٱلْكَـٰذِبِينَ","pendusta"]]],"1021":["(Hud berkata, \"Hai kaumku! Tidak ada padaku kekurangan akal sedikit pun tetapi aku ini adalah utusan dari Tuhan semesta alam)",[["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["لَيْسَ","tidak ada"],["بِى","dalam diri aku"],["سَفَاهَةٌۭ","kebodohan"],["وَلَـٰكِنِّى","tetapi aku"],["رَسُولٌۭ","seorang Rasul"],["مِّن","daripada"],["رَّبِّ","(yang) Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"1022":["(Aku menyampaikan amanat-amanah Tuhanku kepadamu dan aku hanyalah pemberi nasihat yang terpercaya bagimu\") yakni orang yang dipercaya untuk mengemban risalah.",[["أُبَلِّغُكُمْ","Aku sampaikan kepada kamu"],["رِسَـٰلَـٰتِ","Mesej"],["رَبِّى","(dari) Tuhanku"],["وَأَنَا۠","dan aku"],["لَكُمْ","kepada kamu"],["نَاصِحٌ","seorang penasihat"],["أَمِينٌ","boleh dipercayai"]]],"1023":["(Apakah kamu tidak percaya dan heran bahwa datang kepadamu peringatan dari Tuhanmu yang dibawa oleh) lisan (seorang laki-laki di antara kamu untuk memberi peringatan kepadamu? Dan ingatlah oleh kamu sekalian di waktu Allah menjadikan kamu sebagai pengganti-pengganti yang berkuasa) di muka bumi (sesudah lenyapnya kaum Nuh dan Tuhan telah melebihkan kekuatan tubuh dan perawakanmu) memberi kekuatan dan tinggi tubuh; tersebutlah bahwa orang yang paling tinggi di antara mereka adalah seratus hasta, sedangkan yang paling pendek enam puluh hasta (Maka ingatlah nikmat-nikmat Allah) yaitu karunia-karunia-Nya (supaya kamu mendapat keberuntungan) supaya kamu memperoleh keberhasilan.",[["أَوَعَجِبْتُمْ","Adakah kamu tertanya-tanya"],["أَن","bahawa"],["جَآءَكُمْ","telah datang kepada kamu"],["ذِكْرٌۭ","peringatan"],["مِّن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["عَلَىٰ","pada"],["رَجُلٍۢ","seorang lelaki"],["مِّنكُمْ","antara kamu"],["لِيُنذِرَكُمْ ۚ","supaya dia memberi amaran kepada kamu"],["وَٱذْكُرُوٓا۟","Dan ingat"],["إِذْ","apabila"],["جَعَلَكُمْ","Dia buat kamu"],["خُلَفَآءَ","pengganti"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["قَوْمِ","kaum"],["نُوحٍۢ","(daripada) Nuh"],["وَزَادَكُمْ","dan menambah kamu"],["فِى","dalam"],["ٱلْخَلْقِ","perawakan itu"],["بَصْۜطَةًۭ ۖ","secara meluas"],["فَٱذْكُرُوٓا۟","Jadi ingat"],["ءَالَآءَ","(the) Karunia"],["ٱللَّهِ","(milik) Allah"],["لَعَلَّكُمْ","supaya kamu"],["تُفْلِحُونَ","berjaya"]]],"1024":["(Mereka berkata, \"Apakah kamu datang kepada kami agar kami hanya menyembah Allah saja dan meninggalkan) artinya membiarkan (apa yang biasa disembah oleh bapak-bapak kami? Maka datangkanlah apa yang kamu ancamkan kepada kami) berupa azab (jika kamu termasuk orang-orang yang benar\") di dalam pengakuanmu.",[["قَالُوٓا۟","Mereka berkata"],["أَجِئْتَنَا","Adakah kamu datang kepada kami"],["لِنَعْبُدَ","yang (harus) kami sembah"],["ٱللَّهَ","Allah"],["وَحْدَهُۥ","bersendirian"],["وَنَذَرَ","dan kita tinggalkan"],["مَا","apa"],["كَانَ","dulu"],["يَعْبُدُ","ibadah"],["ءَابَآؤُنَا ۖ","nenek moyang kita"],["فَأْتِنَا","Kemudian bawa kami"],["بِمَا","tentang apa"],["تَعِدُنَآ","kamu berjanji kepada kami"],["إِن","jika"],["كُنتَ","kamu"],["مِنَ","daripada"],["ٱلصَّـٰدِقِينَ","yang benar"]]],"1025":["(Ia berkata, \"Sungguh sudah pasti) telah wajib (kamu akan ditimpa azab Tuhanmu) yakni siksaan-Nya (dan kemarahan-Nya. Apakah kamu sekalian hendak berbantah dengan aku tentang nama-nama yang telah kamu menamakannya) artinya yang telah diberi nama oleh kamu (kamu beserta nenek-moyangmu) yang dimaksud ialah berhala-berhala yang biasa mereka sembah (padahal Allah sekali-kali tidak menurunkan untuk itu) untuk menyembahnya (suatu hujah pun?) bukti argumentasi. (Maka tunggulah olehmu) azab itu (sesungguhnya aku juga termasuk orang-orang yang menunggu bersama kamu.\") menanti azab itu disebabkan kedustaanmu kepadaku. Kemudian dikirimkan kepada mereka angin yang panas sekali. Maksudnya, Allah menimpakan azab-Nya atas mereka dengan angin yang amat panas.",[["قَالَ","Dia berkata"],["قَدْ","Sesungguhnya"],["وَقَعَ","telah jatuh"],["عَلَيْكُم","ke atas kamu"],["مِّن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["رِجْسٌۭ","hukuman"],["وَغَضَبٌ ۖ","dan kemarahan"],["أَتُجَـٰدِلُونَنِى","Adakah kamu berselisih dengan aku"],["فِىٓ","tentang"],["أَسْمَآءٍۢ","nama"],["سَمَّيْتُمُوهَآ","kamu telah menamakan mereka"],["أَنتُمْ","kamu"],["وَءَابَآؤُكُم","dan nenek moyang kamu"],["مَّا","Tidak"],["نَزَّلَ","(telah) diturunkan"],["ٱللَّهُ","(oleh) Allah"],["بِهَا","baginya"],["مِن","sebarang"],["سُلْطَـٰنٍۢ ۚ","pihak berkuasa"],["فَٱنتَظِرُوٓا۟","Kemudian tunggu"],["إِنِّى","sesungguhnya, aku"],["مَعَكُم","bersama kamu"],["مِّنَ","daripada"],["ٱلْمُنتَظِرِينَ","mereka yang menunggu"]]],"1026":["(Maka Kami selamatkan dia) Hud (beserta orang-orang yang bersamanya) dari kalangan orang-orang yang beriman (dengan rahmat yang besar dari Kami dan Kami tumpas) kaumnya itu (orang-orang yang mendustakan ayat-ayat Kami) Kami habiskan mereka dengan akar-akarnya (dan tiadalah mereka orang-orang yang beriman) diathafkan kepada lafal kadzdzabuu.",[["فَأَنجَيْنَـٰهُ","Maka Kami selamatkan dia"],["وَٱلَّذِينَ","dan mereka"],["مَعَهُۥ","dengan dia"],["بِرَحْمَةٍۢ","oleh Mercy"],["مِّنَّا","daripada Kami"],["وَقَطَعْنَا","Dan Kami putuskan"],["دَابِرَ","akarnya"],["ٱلَّذِينَ","orang yang"],["كَذَّبُوا۟","dinafikan"],["بِـَٔايَـٰتِنَا ۖ","Tanda-Tanda Kami"],["وَمَا","dan bukan"],["كَانُوا۟","mereka adalah"],["مُؤْمِنِينَ","orang yang beriman"]]],"1027":["(Dan) Kami telah mengutus (kepada kaum Tsamud) tanpa tanwin, yang dimaksud adalah kabilahnya (saudara mereka Saleh. Ia berkata, \"Hai kaumku, sembahlah Allah sekali-kali tidak ada Tuhan bagimu selain-Nya. Sesungguhnya telah datang bukti yang nyata) yakni mukjizat (dari Tuhanmu) yang membenarkan kerasulanku. (Unta betina ini menjadi tanda bagimu) menjadi hal sedangkan amilnya adalah makna yang terkandung dalam isyarah. Sebelumnya kaum Nabi Saleh itu meminta kepadanya agar ia mengeluarkan unta betina tersebut dari sebuah batu besar yang telah mereka tentukan sendiri (maka biarkanlah dia makan di bumi Allah dan janganlah kamu mengganggunya dengan gangguan apa pun) menyembelihnya atau memukulnya (maka kamu ditimpa siksaan yang pedih.\").",[["وَإِلَىٰ","Dan kepada"],["ثَمُودَ","kaum Thamud"],["أَخَاهُمْ","(Kami hantar) saudara mereka"],["صَـٰلِحًۭا ۗ","Salih"],["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["ٱعْبُدُوا۟","Ibadah"],["ٱللَّهَ","Allah"],["مَا","tidak"],["لَكُم","bagi kamu"],["مِّنْ","sebarang"],["إِلَـٰهٍ","tuhan"],["غَيْرُهُۥ ۖ","selain Dia"],["قَدْ","Sesungguhnya"],["جَآءَتْكُم","telah datang kepada kamu"],["بَيِّنَةٌۭ","bukti yang jelas"],["مِّن","daripada"],["رَّبِّكُمْ ۖ","Tuhanmu"],["هَـٰذِهِۦ","Ini"],["نَاقَةُ","(ialah) seekor unta betina"],["ٱللَّهِ","(milik) Allah"],["لَكُمْ","(ia adalah) untuk kamu"],["ءَايَةًۭ ۖ","sebuah Tanda"],["فَذَرُوهَا","Jadi kamu tinggalkan dia"],["تَأْكُلْ","(untuk) makan"],["فِىٓ","pada"],["أَرْضِ","(the) bumi"],["ٱللَّهِ ۖ","(milik) Allah"],["وَلَا","dan jangan"],["تَمَسُّوهَا","sentuh dia"],["بِسُوٓءٍۢ","dengan kemudaratan"],["فَيَأْخُذَكُمْ","supaya tidak menangkap kamu"],["عَذَابٌ","azab"],["أَلِيمٌۭ","yang pedih"]]],"1028":["(Dan ingatlah olehmu di waktu Tuhan menjadikan kamu pengganti-pengganti) di bumi ini (sesudah kaum Ad dan memberikan tempat bagimu) yakni menempatkan kamu (di bumi. Kamu dirikan istana-istana di atas tanah-tanah yang datar) sebagai tempat tinggalmu di musim panas (dan kamu pahat gunung-gunungnya untuk dijadikan rumah) yang kamu tempati di musim dingin, dinashabkannya lafal buyuutan menjadi hal dari lafal yang tersimpan (maka ingatlah nikmat-nikmat Allah dan janganlah kamu merajalela di muka bumi membuat kerusakan).",[["وَٱذْكُرُوٓا۟","Dan ingat"],["إِذْ","apabila"],["جَعَلَكُمْ","Dia buat kamu"],["خُلَفَآءَ","pengganti"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["عَادٍۢ","Aad"],["وَبَوَّأَكُمْ","dan menyelesaikan kamu"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["تَتَّخِذُونَ","kamu ambil"],["مِن","daripada"],["سُهُولِهَا","datarannya"],["قُصُورًۭا","istana"],["وَتَنْحِتُونَ","dan kamu mengukir"],["ٱلْجِبَالَ","pergunungan"],["بُيُوتًۭا ۖ","(sebagai) rumah"],["فَٱذْكُرُوٓا۟","Jadi ingat"],["ءَالَآءَ","(the) Karunia"],["ٱللَّهِ","(milik) Allah"],["وَلَا","dan jangan"],["تَعْثَوْا۟","bertindak jahat"],["فِى","dalam"],["ٱلْأَرْضِ","(the) bumi"],["مُفْسِدِينَ","menyebarkan rasuah"]]],"1029":["(Pemuka-pemuka yang menyombongkan diri di antara kaumnya berkata) maksudnya mereka yang sombong tidak mau beriman kepada Saleh (kepada orang-orang yang dianggap lemah yang telah beriman di antara mereka,) di antara kaumnya, menjadi badal dari lafal yang sebelumnya dengan mengulangi huruf jar (\"Tahukah kamu bahwa Saleh diutus menjadi rasul oleh Tuhannya?) kepadamu (Mereka menjawab,) 'Ya, betul.' (Sesungguhnya kami beriman kepada wahyu yang Saleh diutus untuk menyampaikannya.\")",[["قَالَ","Berkata"],["ٱلْمَلَأُ","ketua-ketua"],["ٱلَّذِينَ","mereka"],["ٱسْتَكْبَرُوا۟","(yang) sombong"],["مِن","antara"],["قَوْمِهِۦ","umatnya"],["لِلَّذِينَ","kepada mereka yang"],["ٱسْتُضْعِفُوا۟","telah ditindas"],["لِمَنْ","[kepada] mereka yang"],["ءَامَنَ","beriman"],["مِنْهُمْ","antara mereka"],["أَتَعْلَمُونَ","Adakah kamu tahu"],["أَنَّ","bahawa"],["صَـٰلِحًۭا","Salih"],["مُّرْسَلٌۭ","(adalah) yang dihantar"],["مِّن","daripada"],["رَّبِّهِۦ ۚ","Tuhannya"],["قَالُوٓا۟","Mereka berkata"],["إِنَّا","Sesungguhnya kami"],["بِمَآ","pada apa"],["أُرْسِلَ","dia telah dihantar"],["بِهِۦ","dengan [ia]"],["مُؤْمِنُونَ","(adalah) orang yang beriman"]]],"1030":["(Orang-orang yang menyombongkan diri berkata, \"Sesungguhnya kami adalah orang yang tidak percaya kepada apa yang kamu imani itu.\")",[["قَالَ","Berkata"],["ٱلَّذِينَ","orang yang"],["ٱسْتَكْبَرُوٓا۟","adalah sombong"],["إِنَّا","Sesungguhnya kita"],["بِٱلَّذِىٓ","dalam yang"],["ءَامَنتُم","kamu beriman"],["بِهِۦ","di dalamnya"],["كَـٰفِرُونَ","(adalah) orang-orang kafir"]]],"1031":["Tersebutlah bahwa bagi unta betina itu satu hari minum, dan untuk mereka satu hari lainnya, akhirnya mereka bosan dengan ketentuan itu. (Kemudian mereka sembelih unta betina itu) yang melakukannya adalah orang yang terkuat berdasarkan perintah dari mereka, yaitu ia diperintahkan agar menyembelihnya dengan pedangnya (dan mereka berlaku angkuh terhadap perintah Tuhan. Dan mereka berkata, \"Hai Saleh! Datangkanlah apa yang kamu ancamkan itu kepada kami) yakni azab sebagai balasan atas pembunuhan unta itu (jika betul kamu termasuk orang yang diutus Allah.\").",[["فَعَقَرُوا۟","Kemudian mereka hamstrung"],["ٱلنَّاقَةَ","unta betina itu"],["وَعَتَوْا۟","dan (berada) kurang ajar"],["عَنْ","ke arah"],["أَمْرِ","(perintah)."],["رَبِّهِمْ","(dari) Tuhan mereka"],["وَقَالُوا۟","dan mereka berkata"],["يَـٰصَـٰلِحُ","Wahai Salih"],["ٱئْتِنَا","Bawa kami"],["بِمَا","apa"],["تَعِدُنَآ","kamu berjanji kepada kami"],["إِن","jika"],["كُنتَ","kamu"],["مِنَ","daripada"],["ٱلْمُرْسَلِينَ","para Rasul"]]],"1032":["(Karena itu mereka ditimpa gempa) gempa bumi yang keras beserta suara gemuruh dari langit (maka jadilah mereka mayat-mayat yang bergelimpangan di tempat tinggal mereka) mereka mati dalam keadaan bertekuk-lutut.",[["فَأَخَذَتْهُمُ","Maka tangkaplah mereka"],["ٱلرَّجْفَةُ","gempa bumi"],["فَأَصْبَحُوا۟","kemudian mereka menjadi"],["فِى","dalam"],["دَارِهِمْ","rumah mereka"],["جَـٰثِمِينَ","jatuh tersungkur"]]],"1033":["(Maka Saleh berpaling) ia meninggalkan (mereka seraya berkata, \"Hai kaumku! Sesungguhnya aku telah menyampaikan kepadamu amanat Tuhanku dan aku telah memberi nasihat kepadamu tetapi kamu tidak menyukai orang-orang yang memberi nasihat.\")",[["فَتَوَلَّىٰ","Jadi dia berpaling"],["عَنْهُمْ","daripada mereka"],["وَقَالَ","dan dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["لَقَدْ","Sesungguhnya"],["أَبْلَغْتُكُمْ","Aku telah sampaikan kepada kamu"],["رِسَالَةَ","(the) Mesej"],["رَبِّى","(dari) Tuhanku"],["وَنَصَحْتُ","dan [aku] menasihati"],["لَكُمْ","[kepada] kamu"],["وَلَـٰكِن","tetapi"],["لَّا","tidak"],["تُحِبُّونَ","kamu suka"],["ٱلنَّـٰصِحِينَ","para penasihat"]]],"1034":["(Dan) ingatlah (Luth) kemudian disebutkan badalnya yaitu, (tatkala dia berkata kepada kaumnya, \"Mengapa kamu mengerjakan perbuatan fahisyah itu) yakni mendatangi dubur/anus laki-laki (yang belum pernah dikerjakan oleh seorang pun di dunia ini sebelummu?\") dari kalangan manusia dan jin.",[["وَلُوطًا","Dan Lut"],["إِذْ","apabila"],["قَالَ","dia berkata"],["لِقَوْمِهِۦٓ","kepada umatnya"],["أَتَأْتُونَ","Adakah kamu komited"],["ٱلْفَـٰحِشَةَ","(seperti) maksiat"],["مَا","tidak"],["سَبَقَكُم","telah mendahului kamu"],["بِهَا","di dalamnya"],["مِنْ","sebarang"],["أَحَدٍۢ","satu"],["مِّنَ","daripada"],["ٱلْعَـٰلَمِينَ","dunia"]]],"1035":["(Tiada lain kamu itu) dengan menetapkan dua hamzah yang ditashilkan nomor duanya serta memasukkan alif di antara keduanya, menurut dua bacaan (mendatangi lelaki untuk melepaskan nafsumu kepada mereka bukan kepada wanita, melainkan kamu itu adalah orang-orang yang melampaui batas) melewati batas kehalalan menuju kepada keharaman.",[["إِنَّكُمْ","Sesungguhnya kamu"],["لَتَأْتُونَ","kamu mendekati"],["ٱلرِّجَالَ","kaum lelaki"],["شَهْوَةًۭ","dengan penuh nafsu"],["مِّن","daripada"],["دُونِ","bukannya"],["ٱلنِّسَآءِ ۚ","kaum wanita"],["بَلْ","Bahkan"],["أَنتُمْ","kamu"],["قَوْمٌۭ","(adalah) suatu kaum"],["مُّسْرِفُونَ","(yang) melakukan keterlaluan"]]],"1036":["(Jawab kaumnya tidak lain hanya mengatakan, \"Usirlah mereka) Luth dan pengikut-pengikutnya (dari kotamu ini; sesungguhnya mereka adalah orang-orang yang berpura-pura menyucikan diri.\") dari mendatangi dubur laki-laki/homosek.",[["وَمَا","Dan tidak"],["كَانَ","adalah"],["جَوَابَ","(the) jawapan"],["قَوْمِهِۦٓ","(dari) kaumnya"],["إِلَّآ","kecuali"],["أَن","bahawa"],["قَالُوٓا۟","mereka berkata"],["أَخْرِجُوهُم","halau mereka keluar"],["مِّن","daripada"],["قَرْيَتِكُمْ ۖ","bandar kamu"],["إِنَّهُمْ","Sesungguhnya mereka"],["أُنَاسٌۭ","(adalah) orang"],["يَتَطَهَّرُونَ","yang menjaga kesucian diri"]]],"1037":["(Kemudian Kami selamatkan dia dan pengikut-pengikutnya kecuali istrinya; dia termasuk orang-orang yang tertinggal) yang ikut binasa oleh azab Allah.",[["فَأَنجَيْنَـٰهُ","Maka Kami selamatkan dia"],["وَأَهْلَهُۥٓ","dan keluarganya"],["إِلَّا","kecuali"],["ٱمْرَأَتَهُۥ","isterinya"],["كَانَتْ","dia"],["مِنَ","daripada"],["ٱلْغَـٰبِرِينَ","mereka yang tinggal di belakang"]]],"1038":["(Dan Kami turunkan kepada mereka hujan) yakni hujan batu dari neraka Sijjiil kemudian membinasakan mereka (maka perhatikanlah bagaimana kesudahan orang-orang yang berdosa.)",[["وَأَمْطَرْنَا","Dan Kami mandi"],["عَلَيْهِم","ke atas mereka"],["مَّطَرًۭا ۖ","hujan"],["فَٱنظُرْ","Jadi lihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلْمُجْرِمِينَ","(dari) penjenayah"]]],"1039":["(Dan) Kami telah mengutus (kepada penduduk Madyan saudara mereka Syuaib. Ia berkata, \"Hai kaumku, sembahlah Allah, sekali-kali tidak ada Tuhan bagimu selain-Nya. Sesungguhnya telah datang kepadamu bukti yang nyata) yakni mukjizat (dari Tuhanmu) yang membenarkan kerasulanku (Maka sempurnakanlah) genapkanlah (takaran dan timbangan dan janganlah kamu kurangkan) maksudnya menekorkan (bagi manusia barang-barang takaran dan timbangan mereka dan janganlah kamu membuat kerusakan di muka bumi) dengan kekafiran dan maksiat-maksiat (sesudah Tuhan memperbaikinya) dengan mengutus rasul-rasul-Nya (Yang demikian itu) yang telah disebutkan itu (lebih baik bagimu jika betul-betul kamu orang-orang yang beriman) yang menghendaki keimanan, maka bersegeralah kamu kepada keimanan.",[["وَإِلَىٰ","Dan kepada"],["مَدْيَنَ","Madyan"],["أَخَاهُمْ","abangnya"],["شُعَيْبًۭا ۗ","Shuaib"],["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["ٱعْبُدُوا۟","Ibadah"],["ٱللَّهَ","Allah"],["مَا","tidak"],["لَكُم","bagi kamu"],["مِّنْ","sebarang"],["إِلَـٰهٍ","tuhan"],["غَيْرُهُۥ ۖ","selain Dia"],["قَدْ","Sesungguhnya"],["جَآءَتْكُم","telah datang kepada kamu"],["بَيِّنَةٌۭ","bukti yang jelas"],["مِّن","daripada"],["رَّبِّكُمْ ۖ","Tuhanmu"],["فَأَوْفُوا۟","Jadi berikanlah sepenuhnya"],["ٱلْكَيْلَ","ukuran"],["وَٱلْمِيزَانَ","dan berat"],["وَلَا","dan jangan"],["تَبْخَسُوا۟","melucutkan"],["ٱلنَّاسَ","[orang]"],["أَشْيَآءَهُمْ","dalam barang mereka"],["وَلَا","dan jangan"],["تُفْسِدُوا۟","menyebabkan rasuah"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["بَعْدَ","selepas"],["إِصْلَـٰحِهَا ۚ","reformasinya"],["ذَٰلِكُمْ","Itu"],["خَيْرٌۭ","(lebih) baik"],["لَّكُمْ","bagi kamu"],["إِن","jika"],["كُنتُم","kamu"],["مُّؤْمِنِينَ","orang yang beriman"]]],"1040":["(Dan janganlah kamu duduk di tiap-tiap jalan) yakni tempat orang berlalu lintas (dengan menakut-nakuti) membuat orang-orang takut untuk melewatinya karena takut pakaian mereka diambil atau dikenakan pajak (dan menghalang-halangi) menghambat (dari jalan Allah) agama-Nya (terhadap orang yang beriman kepada-Nya) dengan cara kamu mengancam akan membunuhnya (dan kamu menginginkan agar jalan Allah itu) kamu menghendaki agar jalan itu (menjadi bengkok) tidak lurus (Dan ingatlah di waktu dahulunya kamu berjumlah sedikit, kemudian Allah membuat kamu menjadi banyak, lalu perhatikanlah bagaimana kesudahan orang-orang yang berbuat kerusakan\") sebelum kamu, oleh karena mereka mendustakan rasul-rasul mereka; yakni akhir dari perkara mereka ialah kebinasaan.",[["وَلَا","Dan jangan"],["تَقْعُدُوا۟","duduk"],["بِكُلِّ","pada setiap"],["صِرَٰطٍۢ","laluan"],["تُوعِدُونَ","mengancam"],["وَتَصُدُّونَ","dan menghalang"],["عَن","daripada"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["مَنْ","(mereka) yang"],["ءَامَنَ","beriman"],["بِهِۦ","dalam Dia"],["وَتَبْغُونَهَا","dan berusaha (untuk membuatnya)."],["عِوَجًۭا ۚ","bengkok"],["وَٱذْكُرُوٓا۟","Dan ingat"],["إِذْ","apabila"],["كُنتُمْ","kamu dahulu"],["قَلِيلًۭا","sedikit"],["فَكَثَّرَكُمْ ۖ","dan Dia menambah kamu"],["وَٱنظُرُوا۟","Dan lihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلْمُفْسِدِينَ","(dari) para perasuah"]]],"1041":["(Jika ada segolongan daripada kamu beriman kepada apa yang aku diutus untuk menyampaikannya, dan ada pula segolongan yang tidak beriman) terhadapnya (maka bersabarlah kamu) artinya kamu harap menunggu (hingga Allah menetapkan hukum-Nya di antara kita) antara kami dan kamu, dengan menyelamatkan yang hak dan menghancurkan yang batil (dan Dia adalah hakim yang sebaik-baiknya) yang paling adil.",[["وَإِن","Dan jika"],["كَانَ","(ada) ada"],["طَآئِفَةٌۭ","satu kumpulan"],["مِّنكُمْ","antara kamu"],["ءَامَنُوا۟","(yang telah) beriman"],["بِٱلَّذِىٓ","dalam yang"],["أُرْسِلْتُ","Aku telah dihantar"],["بِهِۦ","dengan [ia]"],["وَطَآئِفَةٌۭ","dan kumpulan"],["لَّمْ","tidak"],["يُؤْمِنُوا۟","mereka beriman"],["فَٱصْبِرُوا۟","maka bersabarlah"],["حَتَّىٰ","sehingga"],["يَحْكُمَ","hakim"],["ٱللَّهُ","Allah"],["بَيْنَنَا ۚ","antara kita"],["وَهُوَ","Dan Dia"],["خَيْرُ","(adalah) Terbaik"],["ٱلْحَـٰكِمِينَ","(dari) [para] Hakim"]]]});